/* ÇEVİRİ ko · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ko","olay",{
"OLAYLAR:1299-01:0":{"b": ["오스만 베이국의 건국", "9f0b7c0a"], "d": ["카이 부족의 오스만 가지가 쇠위트-도마니치 일대에서 독자적으로 움직이기 시작한 것은 오스만 국가 건국의 관례적인 출발점으로 받아들여진다. 일부 역사가는 1302년 바페우스 전투의 승리를 진정한 전환점으로 본다. 베이국은 비잔티움 접경 지대라는 위치 덕분에 가자(성전) 원정을 통해 빠르게 세력을 키웠다. 셀주크의 유산이 해체되어 가던 이러한 환경에서 오스만 가지는 아히(상공업 형제단), 가지, 유목 투르크멘들을 주위에 모았다. 셰이흐 에데발리와 맺은 유대는 베이국의 정신적 정통성의 토대로 여겨진다. 같은 날짜에 편입된 다른 지역: 이네괼, 야르히사르.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["부르사 정복", "98c727fa"], "d": ["여러 해 동안 봉쇄되어 있던 부르사는 포위의 마지막 단계를 지휘한 오르한 가지에게 항복했으며, 이 도시는 베이국의 첫 번째 대규모 수도가 되었다. 정복 소식이 임종을 앞둔 오스만 가지에게 전해졌다는 이야기가 전하며, 오스만 가지는 유언에 따라 부르사에 안장되었다. 도시는 곧 모스크, 이마레트(빈민 급식소), 마드라사로 채워져 초기 오스만 도시 건설의 본보기가 되었다.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["이즈니크 정복", "a846a811"], "d": ["아나톨리아에서 비잔티움의 가장 중요한 중심지 가운데 하나였던 이즈니크(니케아)는 1329년 펠레카논 전투의 승리 이후 저항의 희망을 잃고 오르한 가지에게 항복했다. 최초의 오스만 마드라사가 이곳에 세워졌고 다부드 카이세리 같은 학자들이 강의를 시작했으며, 이 도시는 초기의 학문 중심지가 되었다. 아야 소피아 교회는 모스크로 바뀌어 정복 전통의 이른 사례를 보여 주었다.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["이즈미트 정복", "06a35035"], "d": ["이즈미트(니코메디아)가 함락되면서 아나톨리아 쪽에 남아 있던 비잔티움의 마지막 주요 요새도 오스만의 통치 아래 들어갔으며, 이스탄불 건너편 해안에 이르는 코자엘리 반도 전체가 오스만 영토가 되었다. 이로써 베이국은 마르마라해의 남쪽과 동쪽 해안 전체를 장악하여 루멜리아로 건너갈 기반을 마련했다.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["침페 요새 — 루멜리아 진출", "c2f0a07d"], "d": ["오르한 가지의 아들 쉴레이만 파샤는 비잔티움 내전 중에 넘겨받은 침페 요새를 1352년에 거점으로 삼았다. 1354년 3월 갈리폴리를 무너뜨린 대지진 이후 비게 된 요새들이 신속히 방비를 갖추면서 이 반도는 오스만의 영구적인 교두보로 바뀌었다. 아나톨리아에서 데려온 투르크멘 주민의 정착으로 뒷받침된 이 조치는 550년을 넘게 될 유럽 대륙에서의 오스만 존재의 시작이다.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["에디르네 정복", "2f54ebb0"], "d": ["트라키아의 요충 도시인 에디르네(아드리아노폴리스)의 점령은 발칸 정복의 주요 거점과 방향을 결정지었다. 정복 연대는 사료에 따라 1361년에서 1369년 사이로 논쟁이 있다. 이 도시는 얼마 지나지 않아 수도가 되어 국가의 무게 중심이 루멜리아로 옮겨 갔음을 선포했으며, 이스탄불 정복 때까지 약 90년 동안 왕도(파이타흐트)로 남았다.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["무라드 1세 즉위", "f8d48a26"], "d": ["오르한 가지의 죽음으로 즉위한 무라드 1세(휘다벤디갸르)는 27년의 치세 동안 국가를 접경 베이국에서 제국의 골격을 갖춘 나라로 끌어올렸다. 펜치크 제도를 통해 예니체리 군단의 기초가 놓였고, 티마르 제도가 확대되었으며, 루멜리아 베일레르베이령이 설치되고 재상직 제도가 강화되었다. 발칸 정복은 그의 시대에 체계적인 국가 정책이 되었다.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["제1차 코소보 전투 — 무라드 1세의 순교", "10b8ddc9"], "d": ["라자르 공이 이끈 발칸 동맹군은 코소보 평원에서 결정적으로 패배했고, 세르비아는 오스만의 종주권 아래 들어갔다. 전장을 둘러보던 무라드 1세는 세르비아 귀족 밀로시 오빌리치의 단검에 찔려 순교했는데, 그는 전장에서 목숨을 잃은 유일한 오스만 술탄이다. 진영에서 이을드름(번개왕) 바예지드가 그의 뒤를 이어 즉위했으며, 그의 동생 야쿠브 첼레비는 교살되었다. 이는 알려진 형제 살해 관행의 초기 사례 가운데 하나가 되었다.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["니코폴리스 전투의 승리", "75716e96"], "d": ["헝가리 왕 지기스문트의 호소로 모이고 프랑스-부르고뉴 기사들까지 참가한 대규모 십자군은 도나우강 변의 니코폴리스 앞에서 이을드름 바예지드에게 참패했다. 이 승리는 불가리아에 대한 오스만의 지배를 확정했으며, 유럽에서는 한 세대 동안 대규모 십자군 원정이 조직되지 못했다.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["앙카라 전투 — 공위 시대(페트레트기)의 시작", "b4a99d96"], "d": ["추부크 평원에서 티무르의 군대에 당한 대패에서 이을드름 바예지드는 포로가 되었고 몇 달 뒤 억류 중에 죽었다. 티무르는 아나톨리아의 베이국들을 부활시켰다. 오스만 영토는 바예지드의 아들들 사이에 분열되었고, 11년 동안 이어질 왕위 다툼(공위 시대, 페트레트기)이 시작되었다. 건국 이래 국가가 겪은 가장 심각한 위기였던 이 시기는 중앙집권 체제의 중요성을 오스만의 기억에 깊이 새겼다. 같은 날짜에 상실한 다른 정착지: 다트차, 마르마리스, 페티예(마크리), 쇠케, 퀴타히아, 아피온, 으스파르타, 마니사, 아이든, 데니즐리, 무을라, 안탈리아, 코니아, 카라만, 카이세리, 카스타모누, 바르튼, 사프란볼루, 삼순, 시바스, 말라티아, 베이셰히르, 시브리히사르, 크르셰히르, 초룸, 찬크르, 예니셰히르(부르사), 이네괼, 아이도스 요새, 게이베, 쾨프뤼히사르(예니셰히르), 마르마라즉, 아크히사르(파무코바), 메케제, 케스텔, 울루바트, 하르만카야, 아크야즈, 임랄르섬, 칸드라, 무다니아, 얄로바, 카라뮈르셀, 아르무틀루, 겜리크(키오스), 쇠위트, 빌레지크, 에스키셰히르, 부르사, 이즈니크, 이즈미트, 발르케시르, 차나칼레, 베르가마, 아마시아, 토카트, 초를루, 륄레부르가즈, 말카라, 케샨, 입살라, 킬리트바히르, 치르멘, 스타라 자고라(에스키 자으라), 타타르파자르즈으, 이흐티만, 큐스텐딜, 페트리치, 네브로코프(고체 델체프), 드라마, 갈리폴리, 침페, 에디르네, 디메토카, 크르클라렐리, 테키르다으, 필리베, 소피아, 니시, 비딘, 터르노보, 바르나, 슈멘, 실리스트라, 니코폴리스, 루세, 테살로니키, 세레스, 카발라, 스코페, 마나스트르, 오흐리드, 예니셰히르(라리사), 트르할라, 이즈딘(라미아), 플레벤, 귀뮐지네, 비가, 도마니치, 쿨라자히사르, 카라자히사르, 야르히사르, 딤보스, 키테(케테), 레프케(오스마넬리), 레블레비지히사르, 카라체퓌시, 카라티긴, 압수(힙수), 아드라노스(오르하넬리), 펠레카논(에스키히사르), 게브제, 헤레케, 사만드라, 키르마스티(M.케말파샤), 미할리치(카라자베이), 콘스탄차, 괼야즈(아폴로니아).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["첼레비 메흐메드의 통일 재건", "03413dfd"], "d": ["형제들 사이의 마지막 결전에서 차무를루에서 무사 첼레비를 꺾은 메흐메드 1세는 나라의 영토를 단일한 통치 아래 통합했으며, 이 때문에 '국가의 제2의 건국자'로 여겨진다. 그의 치세에 약해진 국가 체제가 복구되었고, 아나톨리아 베이국들과의 관계에 균형이 잡혔으며, 루멜리아에서는 신중한 평화 정책이 추진되었다. 같은 날짜에 지도에서 공위 시대의 과도기에서 오스만 행정으로 돌아온 다른 정착지: 압수(힙수), 아드라노스(오르하넬리), 아크히사르(파무코바).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["셰이흐 베드레딘의 반란", "e0a072ca"], "d": ["공위 시대에 군법관(카자스케르)을 지낸 위대한 법학자이자 수피인 셰이흐 베드레딘을 중심으로 전개된 종교·사회 운동은, 카라부룬의 뵈르클뤼제 무스타파와 마니사의 토를라크 케말의 봉기와 동시에 터져 나왔다. 반란은 유혈 진압되었고, 베드레딘은 델리오르만에서 붙잡혀 세레스에서 처형되었다. 이 사건은 오스만 역사상 가장 이른 대규모 사회적·마흐디 신앙적 봉기로서 문학과 역사 서술에 깊은 흔적을 남겼다.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["바르나 전투의 승리", "f739eedc"], "d": ["세게드 조약을 깨고 남하한 헝가리-폴란드 십자군은, 퇴위했다가 다시 군대의 선두에 선 무라드 2세에게 바르나에서 섬멸당했으며, 젊은 국왕 브와디스와프 3세는 전장에서 죽었다. 이 승리로 발칸에서 오스만의 존재를 제거하려던 마지막 대규모 외부 개입의 기회가 사라졌고, 이스탄불 정복으로 가는 길이 확보되었다.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["제2차 코소보 전투", "ebe0b662"], "d": ["바르나의 복수를 하려던 후녀디 야노시의 군대는 사흘 동안 이어진 격전에서 무라드 2세에게 결정적으로 패배했다. 이는 십자군이 발칸에서 오스만을 상대로 벌인 마지막 대규모 회전이었으며, 이 승리로 도나우강 이남에서 오스만의 지배는 이제 되돌릴 수 없을 만큼 확고해졌다.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["이스탄불 정복", "583d5e3e"], "d": ["54일(1453년 4월 6일–5월 29일) 동안 계속된 포위 끝에 5월 29일 아침 성벽을 넘은 오스만군이 도시에 진입했다. 마지막 황제 콘스탄티노스 11세는 전투 중에 죽었고, 1100년 역사의 동로마 제국은 역사 속으로 사라졌다. 젊은 술탄은 '파티흐(정복자)' 칭호를 얻었고, 도시를 수도로 삼으며 아야 소피아를 모스크로 바꾸었다. 도시는 곧 이주 정착과 건설 사업으로 다시 활기를 찾았다. TDV에 따르면 실리브리와 비제는 1453년에야 비로소 확실하게 정복되었다. TDV 림노스 항목에 따르면 이 섬은 정복 직후 오스만의 통치 아래 들어갔고, 공납을 조건으로 가틸루시오 가문에 맡겨졌다. 지도에서 실리브리, 비제, 림노스는 이날부터 비잔티움에서 오스만으로 넘어간 것으로 기록되어 있다(림노스는 공납국). 거대한 대포의 주조, 육로를 통한 선박 이동, 성벽 앞의 포위 배치는 당대 군사 공학의 절정으로 평가된다. 이 정복은 유럽 역사 서술에서 중세의 종말을 상징하는 연대 가운데 하나로 꼽힌다.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["트라브존 정복", "15f52403"], "d": ["정복자 메흐메드가 육군과 함대를 동시에 움직인 험난한 흑해 원정 끝에 트레비존드 제국이 항복했다. 아나톨리아에 남은 비잔티움 세계의 이 마지막 잔재가 청산되면서 흑해 남안 전체가 오스만의 지배 아래 들어갔다. 콤네노스 왕조의 종말은 '두 바다와 두 대륙의 통치자'라는 정복자의 주장을 더욱 굳혔다. 같은 날짜에 편입된 다른 지역: 기레순, 리제.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["실리프케의 최종 정복 — 카라만 베이국의 마지막 저항 분쇄", "d988bee4"], "d": ["실리프케 요새는 1472년에 한 번 게디크 아흐메드 파샤에게 항복했으나, 같은 해 카라만 가문의 카슴 베이가 지중해의 십자군 함대의 도움을 받아 요새를 되찾았다. 오틀루크벨리 전투의 승리 이후 정복자는 자신의 아들과 게디크 아흐메드 파샤에게 이 지역을 확실히 장악하라는 임무를 맡겼다. 이전 오스만 포병들의 도움으로 화약고에 불이 붙어 요새는 빠르게 함락되었다. 이로써 타셸리-이첼 산지에서의 카라만 베이국의 마지막 저항이 분쇄되었으며, 베이국의 청산은 1474년에 마무리되었다.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["오틀루크벨리 전투", "42c7194e"], "d": ["동방의 강대 세력이 되어 베네치아와 동맹을 맺은 백양 왕조의 통치자 우준 하산은 오틀루크벨리에서 화기로 무장한 정복자의 군대에게 대패했다. 이 승리는 아나톨리아에서 오스만의 우위를 확정했으며, 고전적인 군대에 대해 대포와 총을 사용하는 중앙집권적 군대가 우월함을 보여 준 이른 증거이기도 했다. TDV 귀뮈슈하네 항목에 따르면 이 도시는 1467년 이래 백양 왕조의 지배 아래 있었으며, 이 지배는 오틀루크벨리의 패배로 끝나고 귀뮈슈하네는 확실하게 오스만의 지배로 넘어갔다.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["크림의 오스만 보호령 편입", "44e3f7c8"], "d": ["게디크 아흐메드 파샤가 지휘하는 함대는 제노바가 장악하고 있던 카파를 비롯한 크림 남해안의 도시들을 정복했으며, 이 해안 지대는 오스만 직할 산자크가 되었다. 크림 칸국은 멩글리 기라이와 함께 오스만의 종주권을 인정하는 특권적 속국이 되어 300년 동안 북방 정책의 초석이 되었으며, 흑해는 이제 사실상 오스만의 내해가 되었다. 같은 날짜에 편입된 다른 지역: 바흐치사라이, 케르치, 아조프.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["정복자의 죽음 — 젬 술탄 사건", "190ecf01"], "d": ["정복자 메흐메드가 원정길에서 갑자기 죽자 바예지드 2세가 즉위했다. 그의 동생 젬 술탄은 왕위를 주장하며 부르사에서 자신의 이름으로 후트바를 낭송하게 하고 화폐를 주조했다. 패배한 뒤 그는 먼저 맘루크 왕조에, 이어 로도스 기사단에 몸을 의탁했다. 기사단과 교황청의 수중에서 유럽 외교의 협상 카드가 된 젬은 1495년 나폴리에서 죽었다. 이 사건은 15년 동안 오스만의 대외 정책이 신중하게 움직이도록 강요했다.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["찰드란 전투의 승리", "fea64ebb"], "d": ["아나톨리아에서 사파비의 선전이 일으킨 위협을 뿌리부터 해결하려 한 야부즈 술탄 셀림은, 찰드란 평원에서 대포와 총의 우세를 바탕으로 샤 이스마일의 군대에 대패를 안겼다. 타브리즈에 입성했으며, 동부와 남동부 아나톨리아 및 모술-디야르바크르 선이 오스만의 통치에 편입되었다. 이드리스 비틀리시의 노력으로 쿠르드 베이들이 오스만에 귀속되면서 수백 년 동안 이어질 동쪽 국경의 틀이 세워졌다.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["마르지 다비크 전투의 승리", "07d254d3"], "d": ["맘루크군은 알레포 북쪽의 마르지 다비크에서 몇 시간 만에 궤멸되었고, 노령의 술탄 칸수 알가우리는 전투 중에 죽었다. 알레포와 다마스쿠스의 문을 활짝 연 이 승리로 시리아, 레바논, 팔레스타인이 오스만의 통치로 넘어갔으며, 맘루크 왕조의 종말을 가져올 이집트 원정의 길이 열렸다.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["리다니야 전투 — 이집트 정복과 칼리파 지위", "caf378d6"], "d": ["시나이 사막을 신속히 건넌 오스만군은 리다니야에서 투만바이의 방어선을 돌파하고 카이로에 입성했다. 저항을 계속하던 투만바이는 붙잡혀 처형되었고, 맘루크 왕조는 역사 속으로 사라졌다. 이집트, 히자즈, 성지의 도시들이 오스만의 통치 아래 들어갔으며, 압바스 칼리파와 성유물은 이스탄불로 옮겨졌다. 칼리파 지위가 오스만 왕조로 넘어가면서 술탄들은 이슬람 세계의 지도자라는 주장을 내세우게 되었고, 향신료 길의 통제는 제국에 막대한 수입을 안겨 주었다. 같은 날짜에 편입된 다른 지역: 아크레, 마안, 시돈, 카라크.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["카누니 술탄 쉴레이만 즉위", "f6512269"], "d": ["야부즈 셀림이 죽자 외아들로서 즉위한 쉴레이만 1세의 46년 치세는 제국의 정치적, 군사적, 법률적, 문화적 절정기로 평가된다. 관습법을 체계화한 법령집(카눈나메) 덕분에 그는 '카누니(입법자)'라는 칭호를 얻었고, 서방에서는 '대제(Magnificent)'로 불렸다. 건축가 시난의 작품, 디완 문학의 황금기, 지중해에서의 해군 우위가 이 시대의 상징이다.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["베오그라드 정복", "59ef5cec"], "d": ["정복자 메흐메드가 1456년에 함락하지 못했고 '중부 유럽의 자물쇠'로 여겨지던 베오그라드는, 카누니의 첫 원정에서 도나우강과 사바강의 합류점에서 벌어진 포위전으로 함락되었다. 헝가리의 남부 방어선은 무너졌으며, 이 정복은 5년 뒤의 모하치 전투와 20년 뒤의 부다 병합으로 이어지는 중부 유럽 작전의 문을 열었다.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["로도스 정복", "807bbb1e"], "d": ["동지중해의 항로와 순례길을 위협하던 성 요한 기사단의 거점 로도스는 여러 달에 걸친 유혈 포위 끝에 협정에 따라 항복했다. 기사단은 섬을 자유롭게 떠날 수 있도록 허락받았다(이후 몰타에 정착했다). 아나톨리아 해안의 안전이 확보되었고, 이스탄불-이집트 해상로는 중단 없는 오스만의 통제 아래 들어갔다.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["모하치 전투", "f3418b0d"], "d": ["헝가리군은 모하치 평원에서 약 두 시간 만에 포격과 기동의 우세로 괴멸되었고, 러요시 2세 왕은 도주하다가 늪에서 죽었다. 오스만 역사에서 가장 신속하게 승리한 대규모 회전 가운데 하나인 모하치 전투는 독립 헝가리 왕국을 사실상 끝내고 중부 유럽에서 오스만-합스부르크 경쟁의 시대를 열었다.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["제1차 빈 포위", "dc49ea4f"], "d": ["합스부르크가 헝가리 왕위에 손을 뻗은 데 맞서 일으킨 원정에서 오스만군은 빈을 포위했다. 중포를 도중에 두고 온 것, 일찍 닥친 겨울, 보급의 어려움 때문에 3주 만에 포위가 풀렸다. 도시를 함락하지는 못했으나 헝가리에 대한 오스만의 영향력은 유지되었다. 빈 앞은 중부 유럽에서 제국의 병참이 미칠 수 있는 한계를 보여 주었다.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["바그다드 정복 — 두 이라크 원정", "897092c3"], "d": ["'두 이라크'(아랍 이라크와 페르시아 이라크)를 향한 원정에서 먼저 타브리즈에, 이어 전투 없이 바그다드에 입성했다. 압바스 왕조의 옛 수도를 차지한 것은 오스만 통치자에게 이슬람 세계에서 큰 위신을 안겨 주었다. 이맘 아자므 아부 하니파의 영묘가 복원되었고, 바그다드와 바스라의 편입으로 오스만 영토는 페르시아만에 이르렀다. 같은 날짜에 편입된 다른 지역: 키르쿠크, 카르발라.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["프레베자 해전의 승리", "30dc0f97"], "d": ["교황의 주도로 결성된 십자군 함대는 수적으로 우세했음에도, 바람과 해안을 능숙하게 활용한 바르바로스의 전술에 프레베자 앞바다에서 흩어졌고, 안드레아 도리아는 전장을 이탈했다. 이 승리로 지중해에서 약 33년 동안 이어질 확고한 오스만의 제해권이 확립되었으며, 튀르키예 해양 전통에서 해군의 날을 상징하는 날짜이다. 같은 날짜에 편입된 다른 지역: 아덴, 벤데르.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["부다 병합 — 헝가리의 오스만 속주화", "db53b244"], "d": ["합스부르크가 부다를 포위하자 원정에 나선 카누니는 도시를 구한 뒤 중부 헝가리를 오스만 직할 통치 아래 두고 부다 베일레르베이령을 설치했으며, 트란실바니아는 오스만에 속한 자치 공국이 되었다. 헝가리가 셋으로 나뉜 이 체제는 약 150년 동안 이어졌고, 중부 유럽에서 오스만의 영속적인 통치 골격을 이루었다.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["아마시아 화약", "a5afe0d1"], "d": ["여러 해 동안 이어진 오스만-사파비 전쟁을 끝낸 최초의 공식 평화 조약이다. 바그다드와 이라크는 오스만에 남았고, 동부 아나톨리아 국경이 처음으로 상호 인정되었다. 사파비는 오스만 영토 내의 시아파 선전을 중단하기로 했고, 오스만은 이란 순례자들의 안전한 통행을 보장하기로 했다. 이 조약은 두 나라 관계의 법적 틀을 마련한 첫 사례가 되었다.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["시게트바르 — 카누니의 서거", "e2917ed2"], "d": ["72세의 카누니는 열세 번째 원정에서 포위하던 시게트바르 요새가 함락되기 몇 시간 전에 군막에서 서거했다. 소콜루 메흐메드 파샤는 군대가 흩어지지 않도록 그의 죽음을 여러 주 동안 숨겼다. 요새는 함락되었으나 국가는 가장 오래 재위하고 가장 찬란했던 술탄을 잃었다. 그의 아들 셀림 2세가 즉위했고, 국정에서 대재상들의 비중이 커지기 시작했다.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["키프로스 정복", "e364a2b3"], "d": ["베네치아가 통치하던 키프로스에 1570년 상륙이 이루어졌다. 니코시아는 빠르게 함락되었으나 파마구스타는 11개월의 포위 끝에 1571년 8월에야 항복했다. 동지중해의 교역로와 순례길의 안전에 결정적이던 이 섬은 베일레르베이령으로 편제되었고 아나톨리아에서 주민이 이주해 정착했다. 이 정복은 레판토 해전으로 이어질 대규모 십자군 동맹의 명분도 되었다.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["레판토(이네바흐트) 해전의 패배", "6a1d44a9"], "d": ["키프로스 정복에 맞서 결집한 십자군 함대는 레판토만에서 오스만 함대를 붙잡아 대부분을 파괴했다. 해군 총사령관(카푸단 파샤) 뮈에진자데 알리 파샤는 순교했고, 울루츠 알리의 함대만이 살아남았다. 이 참사 뒤에 대재상 소콜루 메흐메드 파샤는 울루츠 알리 파샤를 해군 총사령관으로 임명하여 흩어진 함대를 수습하게 했고, 이스탄불에서 알라니아에 이르는 모든 조선소에서 새 함대의 건조를 시작했다. 그러나 지중해에서의 절대적 우위는 심리적으로 흔들렸다.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["하초바(메죄케레스테시) 전투", "da308ec5"], "d": ["장기 전쟁(1593–1606)의 가장 큰 회전에서, 메흐메드 3세가 직접 지휘한 군대는 흩어지기 직전에 호자 사데딘 에펜디의 설득으로 전열을 가다듬어 합스부르크군을 격파했다. 이는 오스만이 승리한 마지막 대규모 고전적 회전으로 여겨진다. 그러나 전쟁의 전반적인 흐름을 바꾸지 못한 것은 군사 체제의 마모를 보여 주는 징표로도 받아들여졌다.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["지트버토로크 조약", "39c01142"], "d": ["13년에 걸친 소모전을 끝낸 이 조약으로 합스부르크 통치자는 처음으로 '로마 황제'라는 자격으로 술탄과 대등하게 인정되었고 연례 공납은 폐지되었다. 영토 상실은 거의 없었으나, 이러한 외교 언어의 변화는 유럽에 대한 오스만의 절대적 우위 주장이 끝났음을 상징하는 것으로 해석된다.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["카스르 쉬린 조약", "c1acf3af"], "d": ["무라드 4세가 바그다드를 되찾은(1638) 뒤 체결된 이 조약은 100년이 넘는 오스만-사파비 전쟁에 종지부를 찍었다. 바그다드와 이라크는 확정적으로 오스만에 남았고 레반(예레반)은 사파비에 넘겨졌다. 그어진 선은 약간의 변화를 거쳐 오늘날 튀르키예-이란 국경의 기초가 되었으며, 세계에서 가장 오래 지속된 국경 가운데 하나로 꼽힌다. 조약은 베드레, 제산, 멘델리, 데르텡, 데르네를 오스만에 남겼다. 국경의 젠지르 요새는 철거하고, 그 서쪽 마을들은 오스만에, 동쪽 마을들은 이란에 속하게 했다. 셰흐리조르 부근의 잘림 요새 일대와 크즐자 칼레는 오스만에, 아브로만과 미흐리반은 이란에 남았으며, 코투르, 마쿠, 마아즈베르드 요새는 양측이 모두 철거하기로 했다.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["크레타 정복 완료", "e0d85604"], "d": ["1645년에 시작된 크레타 전쟁의 마지막 막인 칸디아 포위전은 파즐 아흐메드 파샤의 3년에 걸친 단호한 작전으로 끝났고, 베네치아 지휘관 모로시니는 협정에 따라 도시를 넘겨주었다. 약 25년에 걸친 이 투쟁은 오스만 역사상 가장 긴 포위전으로 기록되었으며, 동지중해의 마지막 라틴 대요새도 오스만의 통치 아래 들어갔다. 섬 북쪽 해안의 작은 바위 요새 셋, 곧 수다, 스피날롱가, 그람부사는 아직 베네치아에 남았다. 이들은 별개의 작은 섬 위에 세워져 있어 지도에서 크레타의 나머지 부분과 따로 표시할 수 없다.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["부차치 조약 — 최대 판도", "b17b6e5a"], "d": ["폴란드 원정에서 카미야네치를 정복한 뒤 체결된 부차치 조약으로 포돌리아가 오스만에 편입되고 우크라이나의 일부가 보호 아래 들어갔다. 제국은 이로써 유럽에서 가장 넓은 국경에 도달했으며, 이 시점은 팽창 시대의 절정이자 마지막 고리로 여겨진다.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["제2차 빈 포위의 패주", "7d889252"], "d": ["메르지폰루 카라 무스타파 파샤가 두 달 동안 이어 간 빈 포위는, 폴란드 왕 얀 소비에스키가 칼렌베르크 언덕에서 가한 기습 타격으로 패주로 바뀌었다. 군대는 짐을 버리고 퇴각했으며, 메르지폰루는 베오그라드에서 처형되었다. 이후 결성된 신성 동맹과의 전쟁은 16년 동안 이어졌고, 이 패배는 오스만 역사에서 대후퇴가 시작된 순간으로 거론된다.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["그람부사 요새 정복 — 베네치아에 남아 있던 크레타의 바위 요새 가운데 하나", "3ddf9eeb"], "d": ["1669년 칸디아의 항복으로 크레타 정복은 대체로 완료된 것으로 여겨졌으나, 섬 북서쪽 끝의 바위섬 요새 그람부사는 23년 더 베네치아의 손에 남았다. 1692년에 이곳이 점령되면서 크레타에 남은 베네치아의 세 거점 가운데 하나가 정리되었다. 수다와 스피날롱가는 1715년 모레아 원정을 기다려야 했다.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["카를로비츠 조약 — 최초의 대규모 영토 상실", "8f7e2546"], "d": ["16년에 걸친 신성 동맹 전쟁을 끝낸 카를로비츠 조약으로 헝가리와 트란실바니아는 오스트리아에, 포돌리아는 폴란드에, 모레아와 달마티아 해안은 베네치아에 넘겨졌다. 오스만 역사상 처음으로 이 정도 규모의 영토가 협상 탁자에서 영구히 상실된 것이다. 이 조약은 제국이 유럽에 대해 수세로 돌아선 새 시대의 출발 문서로 여겨지며, 오스만 외교사의 전환점이기도 하다. 같은 날 지도에서 주인이 바뀐 정착지: 코스타이니차와 야세노바츠(오스만에서 합스부르크로. 조약문은 카스타노비츠를 황제의 수중에 남기며, 야세노바츠의 인도 날짜는 사료에 없어 조약 날짜를 적었다), 그리고 프레베자(베네치아에서 오스만으로. TDV karlofca: 1110년 라자브월 24일 / 1699년 1월 26일에 서명된 조항에 따라 레판토만 북쪽의 베네치아 점령지가 반환되었다). 지도는 또한 코스타이니차와 야세노바츠를 합스부르크 쪽에, 우크라이나 우안의 우만과 빈니차를 오스만에서 폴란드로(TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: 1672-99 튀르크 지배), 달마티아의 나딘을 베네치아로 기록한다(해당 정착지의 인도 날짜는 사료에 없어 조약 날짜를 적었다. 나딘의 시기 구간 양 끝은 사료로 검증되지 않았다 — 명시된 근사치). 레판토만 북쪽의 보니차도 베네치아에서 오스만으로 반환되며(TDV karlofca), 달마티아의 브라나(우라나)는 베네치아에 남은 곳에 속한다(시기 구간 끝은 미검증 — 명시).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["프루트 전투의 승리", "2583572f"], "d": ["폴타바에서 패한 뒤 오스만에 망명한 스웨덴 왕 문제로 일어난 전쟁에서, 차르 표트르 1세의 군대는 프루트강 변에서 포위되어 항복할 수밖에 없었다. 체결된 조약으로 아조프가 되찾아졌으며, 군대를 섬멸하지 않고 차르를 풀어 준 결정은 그날부터 오늘날까지 논란이 되는 결정으로 역사에 남았다.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["수다와 스피날롱가 요새 정복 — 크레타에서 베네치아의 마지막 흔적 제거", "7261f7ba"], "d": ["1692년 그람부사가 함락된 지 23년 뒤, 모레아 원정의 한 지류 작전으로 크레타에 남은 베네치아의 마지막 두 거점인 수다와 스피날롱가 요새도 정복되었다. 이로써 1645년에 시작된 크레타 정복은 46년 만에 섬의 마지막 한 치까지 완료되었다.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["파트로나 할릴의 반란", "100941a4"], "d": ["이란 전선의 실패, 세금, 궁정 주변의 사치에 대한 분노는 목욕탕 때밀이였던 파트로나 할릴이 이끄는 대규모 봉기로 번졌다. 대재상 이브라힘 파샤가 살해되고 아흐메드 3세가 폐위되었으며 튤립 시대는 끝났다. 반란자들이 몇 달 동안 도시를 지배한 것은 중앙 권력의 취약성을 극명하게 보여 주었다.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["베오그라드 조약 — 베오그라드, 스메데레보, 북부 세르비아의 탈환", "ba7f8e46"], "d": ["오스트리아와 러시아에 맞서 두 전선에서 벌인 전쟁(1736–1739)의 끝에 베오그라드와 북부 세르비아가 되찾아졌고, 러시아는 아조프를 비무장화하고 흑해에 함대를 두지 않기로 했다. 18세기 오스만 외교와 군대의 마지막 큰 성공으로 여겨지는 이 조약은 제국에 25년의 평화기를 안겨 주었다. 같은 날 지도에서 오스트리아에서 오스만으로 돌아온 다른 정착지: 히사르즈크(그로츠카)(베오그라드의 상위 중심지 연쇄; TDV belgrad), 크라이오바, 르므니쿠블체아, 투르누세베린(소왈라키아의 오스만 귀환, 왈라키아 속국 지위로). 사바강 지대의 보산스키 브로드와 보산스카 두비차는 지도상 1739년 9월 28일에 오스만으로 돌아온다(TDV bosna-hersek; TDV mahmud-i--osmanli: 1739년 9월 28일). 소왈라키아의 트르구지우도 같은 날 오스만으로 돌아온다.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["체슈메 습격", "840b30bd"], "d": ["영국의 지원을 받아 지중해로 나온 러시아 함대는 체슈메 항구에 피신한 오스만 함대를 화공선으로 급습하여 거의 전부를 불태웠다. 러시아는 처음으로 지중해의 대해군국으로 등장했다. 이 참사는 1774년 퀴취크 카이나르자 조약에 이르는 전쟁의 운명을 결정지은 타격 가운데 하나였으며, 해군의 근본적인 개혁이 필요함을 드러냈다.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["퀴취크 카이나르자 조약", "2776dcdb"], "d": ["1768–1774년 전쟁을 끝낸, 오스만 역사상 가장 가혹한 조약 가운데 하나로 꼽히는 퀴취크 카이나르자 조약으로 크림 칸국에 '독립'이 부여되었는데, 이는 사실상 러시아의 영향권이 만들어진 것이었다. 러시아는 흑해 연안에 자리 잡았고, 상선의 해협 통과권과 이스탄불 상주 대사관을 얻었으며, 정교도 신민에 대한 모호한 보호 조항은 다음 세기 간섭의 명분에 문을 열어 주었다. 처음으로 주민이 무슬림인 땅이 오스만의 지배에서 벗어나게 되었다.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["러시아의 크림 병합", "bdf6faa8"], "d": ["퀴취크 카이나르자 조약이 만들어 낸 '독립' 크림은 마지막 칸 샤힌 기라이 시기의 혼란을 구실로 예카테리나 2세의 선언에 의해 러시아에 병합되었다. 300년에 걸친 오스만-크림의 동반 관계는 끝났다. 북방 초원의 상실은 이스탄불의 전략적 종심을 없앴고, 수만 명의 크림 타타르인이 오스만 영토로 이주하는 첫 대규모 물결을 일으켰다. 이날 크림반도(알루슈타, 카파, 수다크, 얄타, 발라클라바, 인케르만, 망구프, 아라바트)는 러시아에 편입되었으며, 타만과 쿠반도 같은 병합으로 러시아에 넘어갔다(TDV 크림 항목: 율리우스력 1783년 4월 8일 = 그레고리력 4월 19일).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["셀림 3세와 니자므 제디드", "d53aec21"], "d": ["전쟁 한가운데에서 즉위한 셀림 3세는 패배가 구조적인 것임을 깨닫고 '니자므 제디드'(신질서)라는 이름으로 포괄적인 개혁 프로그램을 시작했다. 유럽식으로 훈련한 새 군대, 이를 재정적으로 뒷받침하는 별도의 국고(이라드 제디드), 공병 학교의 강화, 그리고 유럽 수도들에 둔 최초의 상주 대사관이 그것이다. 이 프로그램은 근대 튀르키예 개혁 전통의 시작으로 여겨진다. 그러나 군단들과 지방 유력자(아얀)의 저항으로 1807년에 무너지게 된다.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["몰타 기사단의 청산 — 프랑스 함대의 도중 기항지", "d62f901d"], "d": ["이집트로 향하던 프랑스 함대는 도중에 몰타에 기항했고, 성 요한(몰타) 기사단은 별다른 저항 없이 섬을 넘겨주었다. 이로써 1522년 로도스에서 쫓겨나 이곳에 정착했던 기사 수도회의 마지막 요새가 사라졌다. 몰타는 2년 뒤 영국의 손에 들어가게 되며, 나폴레옹은 이 섬에서 곧바로 알렉산드리아로 향했다.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["나폴레옹의 이집트 침공", "93fede5f"], "d": ["보나파르트 장군의 군대는 알렉산드리아에 상륙해 이집트를 점령했다. 영국의 인도 항로를 겨냥한 이 원정은 유럽 강국이 오스만의 중심 영토를 직접 공격한 최초의 사건이었다. 아부키르에서의 넬슨의 기습과 제자르 아흐메드 파샤의 아크레 방어가 프랑스의 진격을 꺾었다. 점령은 1801년에 끝났으나, 그것이 남긴 공백 속에서 카발라 출신의 메흐메드 알리 파샤의 부상과 '동방 문제'의 시대가 시작되었다.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["세네디 이티팍(동맹 협약)", "cce49ef5"], "d": ["마흐무드 2세를 즉위시킨 루스추크의 유력자 알렘다르 무스타파 파샤의 주도로, 궁정과 지방의 강력한 아얀 가문들 사이에 체결된 문서이다. 아얀들은 술탄에 대한 충성과 군사 지원을 약속했고, 국가는 그들의 존재와 권리를 인정했다. 술탄의 권위가 문서로 제한된 오스만 역사상 최초의 사례였기 때문에 일부 역사가는 이를 헌정 전통의 먼 시발점으로 본다. 그러나 사실상 몇 달 만에 효력을 잃었다.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["그리스 독립 봉기의 시작", "a7293715"], "d": ["필리키 에테리아 조직이 준비한 봉기는 먼저 왈라키아에서, 이어 주력이 모인 모레아에서 터져 나왔다. 테펠레니의 알리 파샤 사태에 몰두해 있던 국가는 초기 대응이 늦었다. 이 반란은 유럽 여론의 강한 친그리스 정서(필헬레니즘) 덕분에 곧 국제적 대의가 되었으며, 이렇게 오스만 영토에서 민족주의 시대의 첫 성공적인 독립 운동에 불이 붙었다. 같은 날짜에 상실한 다른 정착지: 아테네, 파트라(발랴바드라), 테베, 리바디아, 엘레우시스(아티카), 미솔롱기.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["모레아의 첫 무장 봉기", "77e6250f"], "d": ["프루트강을 건넌 뒤 반란은 모레아로 번졌다. 칼라브리타에서(율리우스력 3월 21일) 시작된 무장 행동에 이어 파트라, 칼라마타, 마니에서 움직임이 일어났다. 모레아는 곧 전면 봉기 상태가 되었고 오스만 행정부는 반도의 대부분을 상실했다. 같은 날짜에 상실한 다른 정착지: 아테네, 파트라(발랴바드라), 테베, 리바디아, 엘레우시스(아티카), 미솔롱기.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["바카이 하이리예(경사스러운 사건) — 예니체리 군단 폐지", "08c9372a"], "d": ["새로 창설된 에쉬킨지 군단의 훈련에 반발해 '솥을 뒤엎은'(반란을 일으킨) 예니체리들은, 마흐무드 2세가 미리 준비한 충성 부대의 포격으로 에트메이다느의 병영에서 섬멸되었다. 군단은 모든 하부 조직 및 연계된 벡타시 교단의 수도장과 함께 폐지되었다. '경사스러운 사건'이라는 뜻의 이름으로 역사에 남은 이 작전은 400년 된 제도를 청산함으로써 아사키리 만수레이 무함마디예 군대와 이후의 모든 중앙집권화 개혁의 길을 열었다.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["나바리노 해전(기습)", "ee579e7f"], "d": ["그리스 반란을 진압하던 오스만-이집트 함대는, 선전포고 없이 항구에 들어온 영국-프랑스-러시아 연합 함대에 의해 나바리노에서 불태워졌다. 60척에 가까운 배와 수천 명의 선원을 잃었다. 유럽 외교가에서 '불행한 사건'으로 얼버무려진 이 습격은 그리스의 독립을 사실상 보장했으며 1828–29년 러시아-튀르크 전쟁의 길을 열었다.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["탄지마트 칙령", "5042ce7b"], "d": ["귈하네에서 낭독된 황제 칙서(핫트 휘마윤)로, 종교의 구분 없이 모든 신민의 생명, 재산, 명예의 안전이 국가의 보장 아래 놓였으며, 조세의 공정, 병역 질서, 재판 없는 처벌 금지의 원칙이 선포되었다. 무스타파 레시드 파샤의 작품인 이 칙령은 오스만 근대화의 헌법적 성격을 띤 첫 주요 문서로 여겨지며, 개혁의 시대인 '탄지마트 시대'(1839–1876)라는 명칭의 유래가 되었다. 행정, 법, 교육, 재정의 근본적인 재편이 이 틀 안에서 진행되었다.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["크림 전쟁 발발", "3b9ca3c8"], "d": ["성지 문제와 정교도 신민에 대한 러시아의 보호권 주장에서 시작된 위기는 오스만의 선전포고로 공개적인 무력 충돌이 되었다. 시노프 습격 이후 영국과 프랑스(나중에는 피에몬테)가 오스만 편에서 참전했다. 연합군이 크림에 상륙해 세바스토폴을 점령함으로써 전쟁은 1856년 파리 조약으로 승리했다. 그러나 전쟁 기간에 처음 들여온 외채(1854)는 제국을 반세기 동안 이어질 재정 종속의 악순환에 빠뜨렸다.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["개혁 칙령(이슬라하트 칙령)", "78ff234d"], "d": ["파리 강화 회담에 앞서 선포된 이 칙령은 탄지마트의 원칙을 확대하여 비무슬림 신민에게 관직 임용, 병역, 학교 설립을 포함한 폭넓은 평등권을 부여했고, 종교 공동체의 조직도 재편했다. 이어 체결된 파리 조약으로 오스만 국가는 유럽 국제법 공동체에 공식적으로 받아들여졌고, 영토 보전은 열강의 공동 보장 아래 놓였다. 그러나 이 보장은 실제로는 간섭의 새로운 문이 되었다.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["카눈 에사시(기본법) — 제1차 입헌기", "0fe052c1"], "d": ["발칸 위기를 논의하기 위해 이스탄불에 모인 국제 회의가 개막한 날, 최초의 오스만 헌법이 예포와 함께 선포되었다. 미드하트 파샤가 이끈 '신오스만인' 운동의 산물인 카눈 에사시로 양원제 의회가 설치되었다. 하원(메즐리시 메부산)은 1877년 3월에 개원했으나, 압뒬하미드 2세는 93 전쟁을 구실로 1878년 2월에 의회를 무기한 정회했고, 헌법은 30년 동안 정지 상태로 남았다.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["93 전쟁(1877–78년 러시아-튀르크 전쟁)", "5bd96af7"], "d": ["루미력 1293년에 해당하여 '93 전쟁'으로 불리는 이 전쟁에서 러시아군은 두 전선에서 공격했다. 가지 오스만 파샤의 플레브나 방어전과 아흐메드 무흐타르 파샤의 캅카스 전투는 서사시가 되었으나, 전선은 붕괴했고 러시아군은 예실쾨이(산스테파노)까지 진격했다. 이 전쟁은 발칸과 캅카스에서 이스탄불로 향하는, 그 영향이 오늘날까지 이어지는 대규모 무슬림 이주의 물결을 일으켰으며, 제국의 인구와 재정 구조는 다시는 이전 상태로 돌아가지 못했다.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["베를린 조약", "47f76a49"], "d": ["산스테파노가 만든 '대불가리아'를 열강의 세력 균형이라는 명분으로 수정한 베를린 회의도 여전히 무거운 결과를 남겼다. 세르비아, 몬테네그로, 루마니아가 독립했고, 자치 불가리아 공국이 세워졌으며, 보스니아-헤르체고비나는 오스트리아의 점령에, 키프로스는 영국의 통치에, 카르스-아르다한-바툼은 러시아에 넘겨졌다. 루멜리아의 500년 오스만 질서는 대체로 해체되었고, '동방 문제'는 유럽 외교의 상시적인 의제가 되었다. 같은 날짜에 상실한 다른 정착지: 플로브디프, 비딘, 터르노보, 바르나, 슈멘, 실리스트라, 루세, 부쿠레슈티, 이아시, 콘스탄차. 루마니아는 베사라비아를 러시아에 넘기는 대신 툴체아와 도브루자를 얻었다. 북도브루자의 툴체아, 바바다그, 머친, 이삭체아, 허르쇼바, 망갈리아가 루마니아로 넘어갔다.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["튀니지 점령과 오스만 공채 관리청", "c7e25598"], "d": ["프랑스는 알제리 국경의 사건들을 구실로 튀니지를 점령하고 바르도 조약으로 보호령으로 삼았으며, 북아프리카에서 오스만의 존재는 트리폴리타니아로 줄어들었다. 같은 해 반포된 무하람 칙령으로 파산 상태의 외채를 관리하기 위해 채권자들이 대표로 참여하는 오스만 공채 관리청(뒤윤 우무미예)이 설립되었다. 소금, 담배, 비단 같은 기본 세입이 이 외국 기구에 직접 귀속되었고, 재정 주권은 심각하게 제한되었다. 같은 날짜에 상실한 다른 정착지: 카이르완, 가베스, 스팍스, 제르바.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["영국의 이집트 점령", "f1269768"], "d": ["이집트에서 재정 파탄과 외국의 통제에 맞서 일어난 우라비 파샤 운동은, 알렉산드리아 포격 이후 상륙한 영국군의 텔 엘케비르 전투 승리로 분쇄되었고 카이로가 점령되었다. 이집트는 법적으로는 오스만에 계속 속해 있었으나 사실상 영국의 통치 아래 들어갔다. 수에즈 운하의 통제는 대영 제국 전략의 중심에 자리 잡았다.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["제2차 입헌기의 선포", "95ee2fd2"], "d": ["통일진보위원회에 속한 장교들이 마케도니아의 산으로 들어가면서 커진 운동 앞에서, 압뒬하미드 2세는 카눈 에사시를 다시 발효시켰다. '자유의 선포'는 열광 속에서 환영받았고 선거가 치러졌다. 그러나 안정은 오지 않았다. 3월 31일 사건(1909년 4월)이 진압된 뒤 압뒬하미드는 폐위되었다. 불가리아의 독립, 보스니아의 병합, 크레타의 그리스 지향도 이 격동의 몇 달 동안 일어났다.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["트리폴리타니아 전쟁", "ed441994"], "d": ["식민지를 찾던 이탈리아는 북아프리카에 남은 오스만의 마지막 영토인 트리폴리타니아에 선전포고하고 해안을 점령했다. 해군이 없는 국가가 정규군을 보낼 수 없게 되자, 무스타파 케말과 엔베르 베이 같은 젊은 장교들이 비밀리에 이 지역으로 건너가 사누시 부족들과 함께 효과적인 저항을 조직했다. 발칸 전쟁이 터지자 체결된 우시 조약(1912년 10월 18일)으로 리비아는 이탈리아에 넘겨졌고, 이탈리아는 로도스와 도데카네스 제도도 점령했다.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["런던 조약 — 루멜리아의 상실", "f3f976df"], "d": ["제1차 발칸 전쟁을 끝낸 런던 조약으로 미디예-에네즈 선 서쪽의 모든 영토와 에게해 섬들을 잃었고, 알바니아는 독립했다. 500년 넘게 제국의 인구, 경제, 문화의 무게 중심이던 루멜리아 가운데 남는 것은 동트라키아뿐이었다(에디르네는 제2차 발칸 전쟁에서 되찾았다). 이 상실은 통일파 정권의 전쟁 정책과 이주 정착 정책을 근본적으로 강경하게 만들었다. 미디예-에네즈 선 서쪽의 다음 지역들이 상실되었다: 스코페, 벨레스, 슈티프, 스트루미차, 도이란, 게브겔리야, 모나스티르, 오흐리드, 데바르(디브라), 프리즈렌, 프리슈티나, 페치, 노비파자르, 코소보폴례; 세레스, 드라마, 카발라, 페트리치, 네브로코프, 크산티, 코모티니, 데데아아치, 디디모티호, 치르멘, 페레스, 수플리, 오레스티아다(쿰치프틀리이), 프라비슈테(엘레프테루폴리), 스테르나, 타브리, 우무르 파키흐(파키아), 말락 데르벤트(랄코보); 크레타에서는 하니아, 칸디아, 레팀노, 시티아, 스파키아.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["제1차 세계 대전 참전", "05a0252e"], "d": ["영국 해군을 피해 온 전함 괴벤과 브레슬라우를 구입한 것처럼 꾸며 해협 안으로 받아들인 일은 국가를 차츰 독일 편으로 끌어들였다. 수숑 제독이 지휘하는 함대가 러시아 항구들을 포격하면서(10월 29일) 전쟁은 사실상 시작되었고, 상호 선전포고는 11월 초에 이루어졌다. 대지하드(지하디 에크베르) 선포에도 기대한 효과는 나타나지 않았다. 제국은 4년 동안 캅카스에서 팔레스타인에 이르는 다섯 개의 전선에서 생존 전쟁에 뛰어들었다.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["차나칼레 전투의 승리", "95d888e8"], "d": ["이스탄불을 함락해 러시아에 닿으려던 연합 함대는 3월 18일 기뢰선과 포대의 화력에 막혀 해협에서 격퇴되었다. 기뢰 부설함 누스레트가 부설한 기뢰선이 전투의 운명을 결정지었다. 4월에 시작된 갈리폴리 지상 작전도 아나파르탈라르와 존크바이으르에서 저지되었고, 연합군은 1916년 1월 반도에서 완전히 철수했다. 무스타파 케말 중령의 이름은 이 전선에서 알려졌다. 약 25만 명의 전사자와 사상자를 대가로 거둔 이 승리는 민족 투쟁의 인재들과 그 정신이 태어난 곳으로 여겨진다.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["샤리프 후세인의 반란", "75f7c58c"], "d": ["메카의 아미르 샤리프 후세인은 영국과의 비밀 서신 교환 끝에 독립 아랍 왕국의 약속을 받고 봉기했으며, 히자즈 철도는 습격의 표적이 되었다. 휴전 이후까지 이어진 파흐레딘 파샤의 전설적인 메디나 방어는 저항의 상징으로 남았으나, 이 반란은 팔레스타인 전선의 영국군 진격과 맞물려 아랍 속주들에서 오스만 지배의 해체를 앞당겼다. 같은 날짜에 상실한 다른 정착지: 후르마, 투라바.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["무드로스 휴전 협정", "9e87c767"], "d": ["불가리아의 붕괴로 전선들이 서로 단절된 오스만 국가는 전함 아가멤논호에서 체결한 휴전 협정으로 전쟁에서 물러났다. 해협의 개방, 특히 안전이 위협받는 지역의 점령을 가능하게 한 제7조는 곧 사실상의 분할을 위한 법적 외피가 되었다. 모술, 이스켄데룬, 이어 이즈미르와 이스탄불이 점령되었다. 이 휴전 협정은 제국의 사실상 종말을 알리는 문서로 여겨진다. 같은 날짜에 상실한 다른 정착지: 하마, 다마스쿠스, 홈스.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["삼순에 도착한 무스타파 케말 — 민족 투쟁", "09a8f784"], "d": ["이즈미르 점령이 일으킨 격분의 분위기 속에서 제9군 감찰관 자격으로 삼순에 상륙한 무스타파 케말 파샤는 자신의 공식 임무를 아나톨리아의 저항을 조직하는 일로 바꾸었다. 아마시아 회람과 에르주룸 및 시바스 회의는 이 행보의 연장이다. '민족의 독립은 다시 민족의 의지와 결단이 구할 것이다'라는 원칙은 민족 투쟁의 정치 강령의 핵심이 되었다.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["튀르키예 대국민의회 개원과 세브르 조약", "2008feec"], "d": ["이스탄불이 공식 점령되고 하원이 해산되자 1920년 4월 23일 앙카라에서 대국민의회가 개원했다. 비상 권한을 한 손에 모은 의회는 국민의 의지에 기초한 새 국가의 핵심이 되었다. 8월에 이스탄불 정부가 서명한 세브르 조약은 아나톨리아를 분할하는 것이었다. 튀르키예 대국민의회는 조약에 서명한 이들을 조국의 반역자로 선언했고, 세브르 조약은 끝내 시행되지 못했다.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["사카리아 전투", "f2f970a6"], "d": ["앙카라에서 50킬로미터까지 다가온 그리스군의 공세는, 총사령관 권한을 맡은 무스타파 케말 파샤의 '방어선은 없다, 방어면이 있을 뿐이다'라는 명령 아래 치러진 22일 밤낮의 전투에서 꺾였다. 그리스군은 처음으로 전략적 수세로 돌아섰다. 이 승리는 무스타파 케말에게 가지 칭호와 원수(뮈시르) 계급을 안겨 주었고, 프랑스와의 앙카라 협정과 대외 승인의 문을 열었다.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["대공세와 이즈미르 해방", "172a50c4"], "d": ["8월 26일 아침 코자테페에서 시작된 공세는 8월 30일 둠루프나르에서의 총사령관 전투로 그리스군 주력의 섬멸에 이르렀다. '군대여, 제군의 첫 목표는 지중해다, 전진!'이라는 명령과 함께 이어진 추격으로 9월 9일 이즈미르가 해방되었다. 무다니아 휴전 협정(10월 11일)으로 동트라키아는 전투 없이 되찾아졌다. 이 군사적 승리는 로잔에서 수립될 새 국가가 협상 탁자에서 지닐 힘을 결정지었다.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["술탄제 폐지", "9f36a9f6"], "d": ["이스탄불 정부도 로잔 회담에 초청되자 튀르키예 대국민의회는 1922년 11월 1일 술탄제와 칼리파 지위를 분리하고 술탄제를 폐지했다. 623년에 걸친 오스만 왕조의 통치는 법적으로 종말을 맞았다. 메흐메드 6세 바히데딘은 11월 17일 영국 전함을 타고 나라를 떠났다. 대국민의회의 결정으로 압뒬메지드 에펜디가 칼리파 직에 올랐으며, 이 직위도 1924년 3월 3일에 폐지된다.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["로잔 조약", "38c27f7d"], "d": ["8개월에 걸친 힘겨운 협상 끝에 체결된 로잔 강화 조약으로 새 튀르키예 국가의 국경, 완전한 독립, 주권이 국제적으로 인정되었다. 불평등 특권(카피툴레이션)은 폐지되었고, 오스만 공채 관리청은 청산 절차에 들어갔으며, 주민 교환이 규정되었다. 세브르를 사실상 무효로 만든 로잔 조약은 민족 투쟁의 외교적 승리이자 공화국의 건국 대외 문서로 여겨진다.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["공화국 선포", "d5bfcdfb"], "d": ["튀르키예 대국민의회가 헌법 개정을 통해 '튀르키예 국가의 정부 형태는 공화국이다'라는 조항을 채택하면서 공화국이 선포되었고, 무스타파 케말 파샤가 초대 대통령으로 선출되었다. 1299년 접경 베이국으로 시작한 624년의 오스만 여정은 이렇게 막을 내렸으며, 주권이 조건 없이 국민에게 속하는 새 국가가 제국의 유산 위에 세워졌다.", "f5cabb8c"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["페르디난트의 부다 장악 — 서포여이가 수도에서 축출되다", "99f77c29"], "d": ["모하치 전투 이후 헝가리 왕위에는 두 명의 왕이 등장했다. 귀족 일부는 서포여이 야노시를, 일부는 합스부르크가의 페르디난트를 선출했다. 페르디난트는 1527년 부다를 장악하고 서포여이를 수도에서 몰아냈으며, 서포여이는 술탄 쉴레이만에게 도움을 청했다. 이것이 1529년 빈 원정의 첫 번째 목표가 부다였던 이유이다.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["바르바로스의 에게해 도서 원정 — 낙소스 공국이 오스만의 통제하에 들어가다", "722b2fea"], "d": ["1207년부터 베네치아의 종주권 아래 라틴계 공작들이 다스리던 낙소스 공국은 바르바로스 하이레딘 파샤의 도서 원정으로 오스만의 통제하에 들어갔다. 섬의 지위는 건드리지 않아 공국은 오스만의 속국으로 존속했으며, 1540년 오스만-베네치아 조약으로 주권이 공식적으로 오스만에 이양되었다.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["십자군 함대의 제르바 점령 — 투르구트 파샤의 근거지 상실", "f41b3f2a"], "d": ["스페인, 교황령, 몰타, 제노바, 피렌체의 선박으로 구성된 십자군 함대는 투르구트 레이스가 1551년부터 습격 기지로 사용해 온 제르바를 목표로 삼았다. 함대는 폭풍과 전염병 때문에 1560년 초에야 섬 앞바다에 도달할 수 있었고, 1560년 3월 12일 섬을 점령하고 요새를 쌓았다. 이 소식을 들은 피얄레 파샤는 3월 28일 갤리선 120척의 함대를 이끌고 이스탄불을 출항했다. 점령은 오래가지 못했다. 오스만 함대는 5월 제르바 앞바다에서 연합군을 격파했고, 요새도 7월 말에 탈환되었다. 이 원정은 프레베자 이후 지중해에서 오스만의 우위를 굳힌 두 번째 대규모 해상 작전의 시작이다.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["제르바 요새의 함락 — 섬의 오스만 행정 편입", "f1efc0df"], "d": ["1560년 5월 14일 피얄레 파샤의 해전 승리 후 십자군 병력은 자신들이 섬에 쌓은 요새에 틀어박혔고, 트리폴리 베일레르베이 투르구트 파샤의 병력이 육지에서 이를 포위했다. 두 달간 이어진 포위전은 1560년 7월 30일 요새가 함락되면서 끝났고, 섬은 트리폴리 베일레르베이령에 편입되었다. 해전 승리와 요새 정복 사이에는 77일의 간격이 있으며, 섬은 5월 14일이 아니라 7월 30일에 실질적으로 주인이 바뀌었다.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["단치히의 러시아-프로이센 이중 통치 종료 — 나폴레옹의 자유시가 프로이센으로 돌아가다", "1ccda4d2"], "d": ["틸지트 강화(1807년 7월 9일)로 프로이센에서 분리되어 프랑스의 보호를 받는 자유시가 된 단치히를 나폴레옹의 군대는 1813년의 포위전 이후 포기했다. 1814년 1월 2일부터 2월 4일까지 이 도시에서는 러시아-프로이센의 이중 통치가 이어졌으며, 차르 알렉산드르가 단치히와 비스와강 하구를 차지하려던 계획을 포기하면서 도시는 프로이센의 행정하에 들어갔다.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["빈에서 크라쿠프를 자유·독립·중립 도시로 선포", "19eea839"], "d": ["빈 회의에서 러시아, 오스트리아, 프로이센은 크라쿠프시와 그 주변 지역을 세 나라의 보호를 받는 자유 국가로 만들었으며, 빈 회의 최종 의정서가 이 체제를 확인했다.", "21a6fe2b"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["보르누가 라비흐 이븐 주바이르의 지배하에 들어가다", "8be4ca96"], "d": ["바기르미와 와다이를 뒤흔든 수단 출신의 군벌 라비흐 이븐 주바이르가 보르누를 장악했다. 그는 1896년까지 나라 전체를 손에 넣고 디크와를 중심지로 삼았다.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["라비흐 이븐 주바이르가 프랑스군에 패해 전사 — 보르누에서의 지배 붕괴", "fb5a3ace"], "d": ["프랑스 식민지 군대에 패한 라비흐는 죽임을 당했다. 그의 아들이 지배를 이어가려 했으나 버티지 못했고, 보르누는 1902년 프랑스, 영국, 독일 사이에 분할되었다.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["귀뮐지네를 중심으로 한 서트라키아 임시정부 선포", "974b2e28"], "d": ["부쿠레슈티 조약(1913년 8월 10일)이 서트라키아를 불가리아에 넘기자, 이 지역의 튀르크계 주민은 귀뮐지네를 중심으로 한 임시정부를 선포했다. 데데아아치를 점령한 뒤 정부는 '서트라키아 독립정부'라는 이름으로 독립을 선언했다. 열강의 개입으로 오스만 정부는 이 정부를 지원하지 않았고, 1913년 9월 29일의 이스탄불 조약이 서트라키아를 불가리아에 넘기면서 이 정부는 1913년 10월 25일까지 겨우 57일간 존속했다.", "86d3bfee"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["오르한 가지의 서거 — 베이국에서 국가로 이행한 40년의 마감", "62c59cfd"], "d": ["1324년 오스만 가지가 죽자 베이국의 수장이 된 오르한 가지는 38년의 통치 동안 오스만을 변경의 베이국에서 마르마라해 양안에 자리 잡은 국가로 변모시켰다. 부르사(1326), 이즈니크(1331), 이즈미트(1337)를 점령하고 카레시 베이국을 병합했으며, 최초의 악체를 주조했고(1327), 이즈니크에 최초의 마드라사를 세웠으며(1331), 침페(1352)와 갈리폴리(1354)를 통한 루멜리아 진출을 영구적인 것으로 만들었다. 그는 루멜리아 정복을 이끌던 맏아들 쉴레이만 파샤를 1357년 사냥 중 사고로 잃었다. 오르한 자신은 1362년 3월 부르사에서 세상을 떠났고 아들 무라드 1세가 뒤를 이었다.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["바레인 제도가 자브르 왕조의 수중에 넘어가다", "6a242b16"], "d": ["TDV의 바레인 항목은 이 섬이 \"차례로 우윤 왕조, 살구르 왕조, 타브 왕조, 자브르 왕조의 통치하에 있었으며, 자브르 왕조 시대에 다수파가 시아파에서 수니파로 바뀌었다\"고 기록하면서도 어느 것에도 연대를 제시하지 않는다. 일반 연구 문헌에 따르면 자브르 왕조는 15세기 초 카티프의 마지막 자르완 왕조 통치자를 무너뜨리고 세워졌으며, 전성기(아즈와드 이븐 자밀, 1496년 사망)에는 페르시아만의 아랍 해안 전체와 알하사, 카티프, 바레인 제도를 지배했다. 아즈와드 이후 아왈 제도는 무크린 이븐 자밀에게 넘어갔는데, 그가 바로 1521년 포르투갈인에게 패하게 되는 통치자이다.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["포르투갈의 아르질라 점령 — 모로코 해안의 두 번째 교두보", "83444a11"], "d": ["아폰수 5세는 3만 명의 병력과 400척의 함대를 이끌고 몸소 모로코 해안에 상륙하여, 와타스 왕조가 다스리던 아르질라를 1471년 8월 24일 점령했다. 이 도시의 함락은 탕헤르의 저항 의지를 꺾었고, 탕헤르는 나흘 뒤인 8월 28일 싸우지 않고 항복했다. 이로써 포르투갈은 세우타(1415)와 크사르 에스세기르(1458)에 이어 모로코 대서양 연안에 세 번째와 네 번째 거점을 확보했다. 국왕은 이 원정 이후 자신의 칭호에 \"아프리카의 주군\"이라는 문구를 덧붙였다.", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["사피가 포르투갈의 영향권에 들어가다", "765e703e"], "d": ["대서양 연안에서 곡물과 어업이 가장 활발한 항구였던 사피는 1488년 포르투갈의 영향권에 들어갔다. 이 도시는 한동안 포르투갈의 보호 아래 현지 통치자들을 통해 다스려졌고, 1508년에 직접 점령되었다. 사료마다 이 두 단계에 두는 비중이 달라 시작 연도는 1488년과 1508년 사이에서 엇갈리지만, 둘 다 같은 과정의 양 끝이다. 사피는 53년간 포르투갈의 수중에 있었으며, 1541년 아가디르가 함락된 뒤 철수가 이루어졌다.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["산타크루스 두 카부 드 게의 건설 — 아가디르의 포르투갈 요새", "cc22c433"], "d": ["수스 해안에서 그때까지 포르투갈의 손이 닿지 않았던 지점에 민간 사업으로 세워진 산타크루스 두 카부 드 게 요새는 1505년에 건설되었고 1513년 포르투갈 왕실에 이관되었다. 이 요새는 수스 계곡의 설탕과 금 교역을 통제하며 마라케시의 남서쪽 출구를 막았기 때문에 사드 왕조 운동의 첫 번째 주요 목표가 되었다. 1533년의 포위는 격퇴되었으나 1541년의 포위는 성공하여 모로코에서 포르투갈의 붕괴가 시작되었다.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["아제무르 점령 — 움 에르 르비아강 하구의 장악", "232acd4b"], "d": ["브라간사 공작 자이므가 지휘하는 포르투갈군은 1513년 9월 3일 움 에르 르비아강 하구의 아제무르에 아무런 저항 없이 입성했다. 이 도시를 점령함으로써 강 하구와 내륙으로 통하는 곡물 수송로를 모두 장악하게 되었고, 이듬해 남서쪽 12km 지점에 마자간 요새를 세우는 길이 열렸다. 아제무르는 28년간 포르투갈의 수중에 있었다.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["마자간 요새의 건설 — 모로코에서 가장 오래 유지될 포르투갈 거점", "786cdb40"], "d": ["아제무르를 점령한 이듬해인 1514년 여름, 해안에 마자간 성채가 건설되었다. 1541년의 전면적 붕괴 이후 포르투갈은 모로코의 모든 거점을 포기하면서도 마자간만은 버리지 않았다. 오히려 이탈리아식 능보를 갖춘 요새로 처음부터 다시 쌓았으며, 이 도시는 255년 동안 유지되었다. 1562년의 대규모 포위도 격퇴되었다. 마자간은 모로코의 마지막 포르투갈 거점으로서 1769년에 철수가 이루어지게 된다.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["마르딘 요새의 항복 — 디야르베키르 남쪽에서 사파비 저항의 종결", "e6226de5"], "d": ["찰디란 전투 이후 디야르베키르 지방으로 진군한 브이으클르 메흐메드 파샤가 마르딘을 포위하자, 사파비 병력은 1515년 10월 요새 안으로 물러났다. 도시는 오스만의 손에 넘어갔으나 요새는 저항했다. 사파비 총독 카라 칸이 증원군을 얻어 감행한 반격은 1516년 5월의 코치히사르(크즐테페) 전투로 귀결되었다. 데데 가르큰 평원에서 하루 종일 이어진 전투에서 카라 칸은 참수되었고 그의 군대는 흩어졌다. 그러나 요새는 TDV의 표현에 따르면 \"9개월 뒤에야\" 항복했다.", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["포르투갈의 바레인 점령 — 자브르 왕조 지배의 종말", "315a435a"], "d": ["자브르 왕조의 통치자 무크린 이븐 자밀이 호르무즈에 공납 바치기를 거부하자, 포르투갈 함대와 포르투갈의 속국인 호르무즈 왕국의 병력이 섬에 상륙했다. 무크린은 전투에서 패했고 바레인은 1521년 포르투갈의 지배하에 들어갔다. 이후 80년간 이 섬은 호르무즈를 통해, 대개 수니파 이란인 총독들의 손으로 다스려졌다. 바레인의 진주와 전략적 위치는 이 섬을 페르시아만에서 벌어진 오스만-포르투갈 경쟁의 직접적인 목표로 만들게 된다.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["아가디르 함락 — 사드 왕조가 모로코에서 포르투갈을 몰아내기 시작하다", "bb1568f6"], "d": ["사드 왕조의 술탄 무함마드 앗셰이흐는 1541년 2월 16일 산타크루스 요새를 포위하여 3월 12일 점령했다. 총독 구테르 드 몬로이를 포함하여 약 600명의 포르투갈인이 포로가 되었다.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["사피와 아제무르에서의 철수 — 포르투갈이 대서양 연안에서 물러나다", "4cb6099a"], "d": ["1541년 3월 12일 아가디르가 함락되고 모로코 술탄과 기대하던 동맹을 맺지 못하자, 주앙 3세는 대서양 연안의 두 대거점에서 철수하라고 명령했다. 사피와 아제무르의 철수는 1541년 가을인 9~10월에 완료되었다. 이로써 단 한 해에 세 거점을 잃었고, 모로코 해안에서 50년간 이어진 포르투갈의 팽창은 역전되었다. 남은 곳은 세우타, 탕헤르, 아르질라, 크사르 에스세기르, 그리고 새로 요새를 보강한 마자간이었다.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["아르질라 철수 — 포르투갈이 북부 해안의 영역을 줄이다", "b5d18373"], "d": ["재정 위기와 사드 왕조의 압박이 겹치자 주앙 3세는 1471년부터 보유해 온 아르질라에서 철수했다. 이로써 모로코에서 포르투갈의 세력은 세우타, 탕헤르, 마자간으로 줄었다. 아르질라는 1577년 잠시 다시 점령되었다가 1589년에 완전히 포기되었다.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["오스만의 바레인 원정 — 페르시아만에서 포르투갈에 맞선 마지막 대공세", "14501df3"], "d": ["1546년 바스라를 병합하고 라흐사(알하사) 주를 설치하여 페르시아만의 아랍 해안에 자리 잡은 오스만 국가는 섬의 진주 교역과 포르투갈의 호르무즈 노선을 겨냥하여, 라흐사 베일레르베이 무스타파 파샤의 지휘 아래 바레인으로 진군했다. 원정의 결과는 사료마다 엇갈린다. TDV 이슬람 백과사전은 오스만이 \"1559년 바레인을 점령하고 그곳에 기지를\" 세웠으며 제도가 \"그 후 다시 포르투갈의 통치하에\" 넘어갔다고 쓴다. 반면 서구의 문헌은 포위가 실패했고, 호르무즈에서 해로로 온 포르투갈 증원군이 오스만 병력을 격퇴했으며, 양측 모두에 큰 타격을 준 페스트 유행 이후 오스만 측이 항복 조건을 요청했다고 기록한다. 두 서술은 결과 자체에서 갈라지지만, 바레인이 오스만의 수중에 영속적으로 남지 않았다는 점은 공통된다.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["울루츠 알리 파샤의 튀니스 점령 — 하프스-스페인 체제의 종말", "d4498698"], "d": ["카를 5세는 1535년 튀니스를 점령했을 때 도시를 직접 다스리지 않고 하프스 왕조의 술탄 물라이 하산을 다시 왕위에 앉혔다. TDV의 표현에 따르면 튀니스시는 \"1569년 오스만의 두 번째 개입이 있기까지 스페인의 보호 아래, 그리고 물라이 아흐마드 3세의 통치 아래\" 있었다. 1568년 6월 27일 알제 베일레르베이령에 임명된 울루츠 알리는 육로로 튀니스를 향해 진군하여 베자에서 하프스 술탄을 격파하고 도시에 입성했다. 물라이 아흐마드는 스페인의 요새 거점(프레시디오)인 라굴레트(할쿨와디)로 피신했다. 이로써 만은 도시는 오스만, 항구 요새는 스페인의 둘로 나뉘었으며, 이 분할은 4년간 지속되었다.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["돈 후안 데 아우스트리아의 튀니스 탈환 — 레판토 승리가 육지에서 거둔 유일한 결실", "a6f044ee"], "d": ["레판토 해전(1571) 이후 신성동맹이 해체되었는데도 스페인은 단독으로 북아프리카를 압박했다. TDV의 표현에 따르면 \"1573년 10월 10일 스페인인들은 튀니스의 지배권을 장악할 목적으로 새로운 작전에 착수했다. 그들은 튀니스를 점령하고 이곳에 8000명의 병사를 남겼다.\" 돈 후안 데 아우스트리아가 지휘한 이 작전은 레판토의 승리가 육지에서 결실을 거둔 유일한 곳이다. 그러나 이는 오래가지 못했고 도시는 11개월 뒤에 탈환되었다. 이 점령이 무너뜨린 것은 이미 확립되어 있던 오스만 행정이었다. 히즈라력 980년 둘 히자월 2일(1573년 4월 5일) 당시 튀니스의 사령관은 클르츠 알리 파샤, 카이마캄(대리관)은 라마잔 파샤, 베일레르베이는 하이다르 파샤였다.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["사파비 왕조가 포르투갈로부터 바레인을 탈취하다", "c37d982c"], "d": ["샤 아바스 1세가 보낸 병력은 섬의 반란 세력과 합세하여 포르투갈 수비대를 요새에서 몰아냈다. TDV의 표현에 따르면 이 제도는 \"1602년 이란에 속한 병력에 의해\" 포르투갈인의 손에서 빼앗겼다. 이로써 바레인은 81년간의 포르투갈 통치에서 벗어나 사파비 왕조의 지배하에 들어갔고, 115년 동안 이란에 속했다. 이는 페르시아만에서 포르투갈 세력이 해체되는 첫 번째 고리이다. 20년 뒤에는 호르무즈 자체도 영국-이란 합동 작전으로 함락되게 된다.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["오만의 바레인 침공 — 사파비 지배의 종말", "c9be5820"], "d": ["사파비 국가 말기의 해체 과정에서 야루브 왕조가 다스리던 오만의 함대가 섬을 침공했고, 사파비의 지배는 끝났다. 뒤이은 35년은 페르시아만에서 가장 혼란한 시기였다. 섬은 오만, 이란, 현지 아랍 세력 사이에서 여러 차례 주인이 바뀌었다.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["바레인이 부셰르의 알 마즈쿠르 가문의 통치로 넘어가다", "610e2f9d"], "d": ["본래 오만에서 와서 부셰르에 정착했으며 후왈라족으로 간주되는 알 마즈쿠르 가문은 1753년 부셰르의 근거지에서 출발하여 바레인을 자신들의 통치 아래 두었다. 이 가문은 이란의 페르시아만 연안에 사는 아랍 공동체들을 이끌었고 이란의 이름으로 섬을 다스렸다. 마지막 대표자인 나스르 알 마즈쿠르는 잔드 정권에 의해 바레인 총독으로 임명되었다. 이는 알 칼리파 가문 이전 섬의 마지막 통치 체제이다.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["마자간 철수 — 모로코의 마지막 포르투갈 거점 상실", "f9e9749d"], "d": ["알라위 왕조의 술탄 무함마드 3세 이븐 압달라가 1769년 초에 시작한 포위 앞에서 592명의 수비대는 버틸 수 없었다. 2월 1일 리스본을 출항한 철수 선단은 1769년 3월 11일 마지막 병사들을 승선시켰고, 총독 디니스 그레고리우가 가장 마지막으로 도시를 떠났다. 이로써 1415년 세우타 점령으로 시작된 모로코 내 포르투갈의 존재는 3세기 반 만에 끝났다. 마자간은 1541년의 전면적 붕괴 이후 유지된 대서양 연안의 유일한 거점이었으며, 255년이라는 기간으로 포르투갈이 모로코에서 가장 오래 보유한 곳이 되었다.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["알 칼리파 가문의 바레인 정복 — 오늘날까지 이어지는 왕조의 성립", "8773b011"], "d": ["잔드 정권의 바레인 총독 나스르 알 마즈쿠르는 카타르반도의 주바라를 포위했다. 아흐마드 이븐 무함마드 이븐 칼리파가 지휘하는 우투브 병력은 포위를 깨뜨리고 반격에 나서 같은 해에 바레인을 점령했다. TDV의 기록은 짧다. \"바레인은 1783년 우투브 부족의 알 칼리파 가문의 지배하에 들어갔다.\" 아흐마드 이븐 무함마드는 이 승리 이후 \"알파티흐\"(정복자)라는 칭호로 불렸고, 그가 세운 왕조는 오늘날까지 섬을 통치해 왔다.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["바레인과 영국의 조약 — 페르시아만의 보호령 체제 편입", "576796b2"], "d": ["TDV의 기록에 따르면 \"1861년 5월 21일 영국과, 바레인을 대표한 셰이크 무함마드의 동생 알리는 이 지역에서 노예무역과 해적 행위를 금지하는 협정에 서명했다.\" 영국 문서에서는 같은 조약(Perpetual Truce of Friendship and Peace, 우호와 평화의 영구 휴전 조약)의 날짜가 1861년 5월 31일로 되어 있다. 이 조약은 바레인의 대외 관계를 영국에 종속시킨 보호령 체제의 첫 번째 고리이며, 1871년 오스만이 라흐사와 카티프에 다시 자리 잡은 뒤에도 섬은 이 체제 밖에 남았다.", "ab2ad5ff"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["에디르네 에스키 모스크(울루 모스크)의 착공", "da7a22ac"], "d": ["민간에서 울루자미(자미이 아티크)라는 이름으로도 알려진 에스키자미의 건설은 에미르 쉴레이만 첼레비에 의해 1402~1403년에 시작되었다.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["부르사 예실 모스크 복합 단지의 착공", "280b8a21"], "d": ["공위 시대 이후 왕위를 다시 통일한 메흐메드 1세는 1414년 이 복합 단지의 공사를 시작했으며, 부르사의 중심부에 할아버지와 아버지의 복합 단지와 구별되도록 자리를 잡았다. 수석 건축가는 하즈 이바즈 파샤였다.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["부르사 예실 모스크 복합 단지의 완공", "bc82821f"], "d": ["타브리즈 출신 장인들도 기여한 타일 장식과 장식 프로그램으로 알려진 예실(녹색) 모스크 복합 단지는 1419년 12월에 완공되었다. 복합 단지는 모스크, 영묘(예실 튀르베, 녹색 영묘), 마드라사, 이마레트, 목욕장으로 이루어져 있으며, 초기 오스만 건축의 가장 풍부한 사례 가운데 하나이다.", "b3e76f7c"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["위치 셰레펠리 모스크와 복합 단지의 완공", "cde6993e"], "d": ["무라드 2세가 무슬리훗딘과 셰하벳딘이라는 장인들에게 10년(1437~1447)에 걸쳐 짓게 한 위치 셰레펠리 모스크는 오스만 건축에서 중앙 집중식 평면 모스크의 첫 사례로 인정되며, 고전기 이전 과도기 건축의 전환점 가운데 하나이다.", "daf1585b"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["바예지드 모스크와 복합 단지의 완공", "eb9ab65b"], "d": ["바예지드 2세를 위해 지어진 바예지드 모스크와 복합 단지의 공사는 한 기록 문서에 따르면 906년(1500)에 시작되어 911년 주마다 알울라월 14일(1505년 10월 13일)에 완료되었다. 건축가에 대해서는 논란이 있다. 아이반사라이의 기록을 근거로 오랫동안 건축가 하이렛딘의 작품으로 여겨졌고, 이후에는 건축가 케말렛딘의 것으로 보았으며, 일부에 따르면 두 사람이 함께 작업했다. 그러나 같은 문서는 장인이 술탄 샤의 아들 야쿠브 샤였음을 보여 준다. 이 모스크는 고전기 이전 오스만 건축에서 고전기로의 이행을 보여 주는 중요한 기념물 가운데 하나로 꼽힌다.", "9b7591c4"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["미마르 시난의 황실 수석 건축가 임명", "7a753f0e"], "d": ["TDV 이슬람 백과사전의 시난 항목에 따르면, 1537년 황실 수석 건축가 아젬 알리시가 죽자, 몰다비아 원정 때 프루트강에 놓은 다리로 주목을 받은 시난이 대재상 뤼트피 파샤의 인정을 받아 이 직책에 올랐다. 이로써 50년 넘게 이어질 시난의 수석 건축가 시대가 시작되었다.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["셰흐자데 모스크와 복합 단지의 착공", "1a70ddfd"], "d": ["카누니 술탄 쉴레이만은 1543년 페스트 유행으로 잃은 아들 셰흐자데(황자) 메흐메드의 이름으로 복합 단지를 짓도록 명했다. 공사는 1543년 6월에 시작되었으며, 먼저 영묘를 완성한 다음 모스크 건축에 들어갔다. 미마르 시난 자신의 표현에 따르면 이 건축물은 \"나의 도제 시절 작품\"이다.", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["위스퀴다르 이스켈레(미흐리마흐 술탄) 복합 단지의 완공", "3769007f"], "d": ["위스퀴다르 이스켈레(선착장) 광장의 복합 단지 공사는 1540년대 초에 시작되어 1547년에 완료되었다. 미흐리마흐 술탄이 미마르 시난에게 짓게 한 두 대형 모스크 가운데 연대순으로 첫 번째이며, 두 번째(에디르네카프)는 약 20년 뒤에 완공된다.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["셰흐자데 모스크의 예배 개시", "2bb3f4b2"], "d": ["약 5년에 걸친 공사 끝에 셰흐자데 모스크는 1548년 8월 예배를 위해 문을 열었다. 두 개의 미너렛과 중앙 돔을 갖춘 평면 구성은 미마르 시난의 이후 대작들을 예고하는 것으로 평가된다. 복합 단지는 모스크, 영묘, 마드라사, 이마레트(빈민 급식소), 타브하네(숙박소), 카라반사라이로 이루어져 있다.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["크르크체시메 상수도 송수로의 착공", "14124b59"], "d": ["미마르 시난은 카누니의 명에 따라 베오그라드 숲에서 이스탄불로 물을 끌어오는 방안을 조사하여 가능하다고 보고했다. 대규모 수도 시설의 공사는 1554년에 시작되어 1563년 이전에 완료되었다. TDV는 이 구조물을 시난의 \"공학적으로 가장 중요하며 규모 면에서도 가장 큰 작품\"으로 규정한다.", "dc29aa04"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["모스타르 다리의 완공", "e7f434af"], "d": ["네레트바강에 놓인 유명한 모스타르 다리는 1566~67년경 건축가 하이렛딘이 건설했다. 1568년 자의 공식 문서에 다리가 언급된 것은 다리가 이미 완공되었음을 확인해 준다. 이 구조물은 단일 경간의 첨두아치를 지닌 고전 오스만 교량 건축의 가장 널리 알려진 사례 가운데 하나이다.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["에디르네카프(미흐리마흐 술탄) 모스크의 완공", "f2d21a82"], "d": ["카누니의 딸 미흐리마흐 술탄을 위해 1563년에 확인된 건축 허가 이후 시작된 모스크 공사는 1566년에 완료되었다. 복합 단지의 와크프 문서는 1570~71년에 작성되었다. 이 건물은 이스탄불 성벽에 가장 가까운 미마르 시난의 대작 가운데 하나이다.", "0f9e5ecd"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["뷔위크체크메제 다리의 완공", "5f49b3c5"], "d": ["카누니 술탄 쉴레이만의 명으로 착공된 이 다리는 술탄이 시게트바르 원정 중에 서거하자 그의 아들 셀림 2세가 1567~68년에 완공하게 했다. 미마르 시난은 뷔위크체크메제 호수가 바다와 만나는 지점에 지은 이 다리에서 홍수로 손상된 구간도 직접 보수했다.", "4478b56a"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["드리나(소콜루 메흐메드 파샤) 다리의 완공", "1d668c73"], "d": ["대재상 소콜루 메흐메드 파샤의 후원으로 미마르 시난이 지은 이 다리는 비문에 새겨진 연대에 따르면 1577~78년에 완공되었다. 일부 연구자들은 공사가 1571~72년에 시작되었다고 주장한다. 이 다리는 소콜루가 자신이 태어난 비셰그라드에 품은 애착의 상징이다.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["아자프카프(소콜루 메흐메드 파샤) 모스크의 건립", "f7b57feb"], "d": ["운카파느 다리의 시슈하네 쪽 교각 옆에 있는 이 모스크는 대재상 소콜루 메흐메드 파샤가 미마르 시난에게 짓게 한 것이다. 이 건물은 소콜루의 이름으로 세워진 시난의 모스크 두 곳 가운데 하나이다(다른 하나는 카드르가의 모스크).", "badb6241"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["다부드 아가의 황실 수석 건축가 취임", "8cdc7f53"], "d": ["1588년 미마르 시난이 죽은 뒤 짧은 공백기를 거쳐, 다부드 아가는 1592년부터 공식 문서에서 황실 수석 건축가로 언급되기 시작했다. 셀리미예 복합 단지의 일부 부속 요소와 예니 모스크의 초기 공사를 맡은 다부드 아가는 그 시대의 가장 중요한 건축가 가운데 한 사람이다.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["예니 모스크(에미뇌뉘)의 정초", "d3cddc01"], "d": ["메흐메드 3세의 어머니 사피예 술탄의 발원으로, 지반을 말뚝으로 다진 뒤 석재 블록으로 모스크의 기초를 놓았다. TDV의 두 항목은 이 사건에 서로 다른 날짜를 제시한다(예니자미 복합 단지 항목은 1598년 4월 9일, 다부드 아가 항목은 1597년 8월 23일). 여기서는 건물 자체를 다룬 전용 항목의 날짜를 기준으로 삼았다.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["다부드 아가의 페스트 사망과 예니 모스크 공사의 중단", "81f2cd04"], "d": ["다부드 아가는 예니 모스크를 지면에서 겨우 1지라(약 한 완척) 높이까지 올렸을 때인 1598년 9월 페스트 유행 중에 죽었고, 달그츠 아흐메드 차우시가 후임 수석 건축가로 임명되었다. TDV는 역사 연대시(타리흐)에 근거한 다른 전승에서는 사망 연도가 1599~1600년으로도 나오며, 정확한 날짜는 확정할 수 없다고 밝힌다.", "02ee24e4"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["메흐메드 3세의 서거로 예니 모스크 공사가 중단되다", "5acef053"], "d": ["발원자 사피예 술탄의 아들 메흐메드 3세가 1603년에 서거한 뒤 사피예 술탄은 구궁(에스키 사라이)으로 보내졌고 예니 모스크의 공사는 중단되었다. 건물은 이 상태로 약 60년 동안 완공되지 못한 채 남아 있었다.", "6d8a4c2b"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["예니 모스크의 완공과 예배 개시", "d6d86c82"], "d": ["60년 넘게 미완성으로 남아 있던 예니 모스크의 공사는 하티제 투르한 발리데 술탄(모후)이 1661년에 임명한 수석 건축가 메레메트치 무스타파 아가의 지휘 아래 완료되었고, 1665년 10월 30일 금요 예배와 함께 문을 열었다.", "0ec54cd6"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["최초의 오스만 아크체 주조", "38d2d638"], "d": ["오르한 가지의 이름으로 주조된 최초의 은화 아크체는 베이국의 독립 주권을 화폐로 선포한 것이었다. 아크체는 5세기 동안 기본 화폐 단위로 남았다.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["루멜리아 베일레르베이령 설치", "ffa16089"], "d": ["유럽 쪽의 정복지가 하나의 군사·행정 체계 아래 모였으며, 베일레르베이 제도는 제국 지방 조직의 근간이 되었다.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["이을드름 바예지드와 데스피나 하툰의 혼인", "4b10dc6c"], "d": ["코소보 이후 세르비아 전제공국과 맺은 속국 관계는 라자르의 딸 올리베라와 바예지드의 혼인으로 굳어졌다. 초기 혼인 외교의 전형적인 사례이다.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["아나톨리아 베일레르베이령 설치", "5ef8d3a7"], "d": ["병합한 베이국 영토를 다스리기 위해 아나톨리아 베일레르베이령이 조직되었고, 루멜리아와 아나톨리아의 두 날개를 갖춘 행정 체제가 완성되었다.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["부르사 울루 자미(대모스크) 완공", "27bcc4a5"], "d": ["니코폴리스의 전리품으로 지은 스무 개의 돔을 가진 대모스크는 초기 오스만 건축의 기념비적 사례이자 서예의 야외 박물관이다.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["찬다를르 할릴 파샤의 파면과 처형", "5e19438f"], "d": ["정복 이후, 포위전에 거리를 두었던 유서 깊은 찬다를르 가문 출신의 대재상이 처형되었다. 대재상이 술탄의 명령으로 처형된 것은 처음이었으며, 데브시르메 출신 재상들의 시대가 열리고 있었다.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["몰다비아의 공납국화", "25bd3693"], "d": ["몰다비아 총독령은 공납을 바치기로 했으며, 왈라키아, 트란실바니아와 함께 도나우강 북쪽의 세 속국 지대가 제국의 북방 완충 지대가 되었다. 같은 날짜에 편입된 다른 지역: 이아시.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["두브로브니크(라구사)의 공납", "d127c78a"], "d": ["상인 공화국 라구사는 공납의 대가로 자치와 통상 특권을 보장받았으며, 아드리아해에서 오스만의 창구로서 번영했다. 공화국의 영토인 믈레트섬도 같은 지위를 누렸다.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["왈라키아 원정: 꿰뚫는 자 블라드(카즈클르 보이보다)", "fd4530bb"], "d": ["공납을 거부하고 사절을 살해한 블라드 체페슈에 대한 원정으로 왈라키아는 속국 지위로 되돌려졌다. 야간 기습과 꼬챙이에 꿴 공포의 광경은 유럽에서 전설이 되었다. 같은 날짜에 편입된 다른 지역: 부쿠레슈티.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["파티흐 복합 단지 개관", "a150ea55"], "d": ["여덟 개의 마드라사(사흔 이 세만)를 갖춘 이 복합 단지는 이스탄불을 이슬람 세계의 학문 중심지로 바꾸려는 계획의 첫 번째 큰 걸음이었다.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["이스탄불의 알리 쿠슈추", "8508229d"], "d": ["사마르칸트 천문대의 마지막 위대한 대표자인 알리 쿠슈추는 정복자의 초청으로 아야 소피아 마드라사의 교수(뮈데리스)가 되었으며, 이스탄불에 수학·천문학의 전통을 세웠다.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["정복자의 법령집(파티흐 카눈나메)", "b08944c9"], "d": ["국가 조직, 의전, 형벌을 집성한 최초의 포괄적 관습법 법령집이다. '세계 질서(니자므 알렘)를 위해' 형제 살해를 허용한 유명한 조항으로 오랫동안 논쟁의 대상이 되어 왔다.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["최초의 오스만 금화(술타니) 주조", "2fd5c0dd"], "d": ["베네치아 두카트에 상당하는 최초의 오스만 금화가 주조되었으며, 제국의 재정은 국제 화폐 질서에 합류했다.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["톱카프 궁전으로 이전", "b9cd6a5e"], "d": ["신궁(톱카프)이 완공되면서 국정의 중심이 이곳으로 옮겨졌으며, 궁전은 4세기 동안 제국의 두뇌로 남았다.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["피렌체 공화국의 공국 전환 — 알레산드로 데 메디치", "c08764e1"], "d": ["교황 클레멘스 7세의 압력으로 피렌체의 통치 위원회(발리아)는 새 헌법을 채택했다. 500년 동안 이어진 공화정은 폐지되고 알레산드로 데 메디치가 세습 공작으로 선포되었으며, 그는 5월 1일에 실제로 권좌에 올랐다. 이로써 피렌체는 독립 도시 공화국에서 메디치 가문의 세습 공국으로 바뀌었다.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["카누니와 휘렘 술탄의 혼인 계약", "abc05f26"], "d": ["카누니가 휘렘과 정식 혼인 계약을 맺은 것은 궁정 전통을 근본적으로 바꾸었다. '하세키 술탄' 제도가 생겨났고 왕조 정치에서 여성의 시대가 열렸다.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["프랑스에 대한 최초의 포괄적 카피툴레이션", "e2264e48"], "d": ["합스부르크의 포위에 맞선 프랑스 동맹의 일환으로 장 드 라 포레와 마크불 이브라힘 파샤 사이에 통상 특권이 체결되었다. 그날에는 외교 수단이던 카피툴레이션은 수세기를 거치며 재정 종속의 문으로 변하게 된다.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["인도양 원정: 디우 포위", "fcd1217a"], "d": ["수에즈에서 출항한 함대는 홍해를 건너 구자라트의 디우를 포위했다. 요새는 함락하지 못했으나 오스만의 힘이 처음으로 인도양에 이르렀고 포르투갈의 독점이 흔들렸다.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["세이디 알리 레이스의 인도 여행", "e5da3b2c"], "d": ["바스라의 함대를 이집트로 데려오는 임무를 맡은 세이디 알리 레이스는 폭풍에 밀려 인도에 표류했다. 그가 귀환의 모험을 서술한 『미르아튈 메말리크』는 초기 오스만 여행기 가운데 하나이다.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["피리 레이스의 처형", "63026444"], "d": ["호르무즈 원정에서 함대를 바스라에 남겨 두고 돌아온 위대한 항해가이자 지도 제작자는 84세에 처형되었다. 이는 우리 과학사에서 가장 논란이 많은 결정 가운데 하나이다.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["쉴레이마니예 복합 단지 개관", "1c6458b2"], "d": ["건축가 시난이 '나의 숙련공 시절 작품'이라 부른 이 복합 단지는 마드라사, 병원(다뤼쉬시파), 도서관을 갖춘 고전기 최대의 교육·자선 복합 시설이 되었다.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["몰타 포위", "f57f6a85"], "d": ["지중해의 자물쇠인 몰타가 넉 달 동안 포위되었다. 투르구트 레이스가 전사(순교)했고 포위는 풀렸다. 이는 카누니 시대 해양 활동의 첫 번째 큰 후퇴였다.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["셀리미예 모스크 완공", "3b0484e1"], "d": ["시난이 '나의 장인 시절 작품'이라 부른, 하나의 돔이 공간을 지배하는 셀리미예는 오스만 고전 건축의 절정으로 평가된다(유네스코 세계 유산).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["이스탄불 천문대 설립", "169bdf5d"], "d": ["당대에 가장 잘 갖춰진 천문대 가운데 하나였던 타키윗딘의 천문대는 1577년 혜성 이후 일어난 논쟁 끝에 1580년에 철거되었으며, 제도적 천문학은 3세기 늦어졌다.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["츨드르 전투의 승리 — 동방 전쟁의 시작", "13125a54"], "d": ["사파비군이 츨드르에서 패하면서 캅카스의 문이 열렸으며, 트빌리시가 점령되고 조지아가 오스만의 지배 아래 들어갔다.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["횃불 전투 — 시르반의 확정적 오스만 귀속", "3bbc23bc"], "d": ["밤에도 횃불 아래에서 계속되어 이 이름으로 불리는 전투에서 사파비는 결정적으로 패배했으며, 시르반과 바쿠에서의 오스만 지배가 확고해졌다.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["대규모 화폐 개악 — 아크체 위기", "9205c3d4"], "d": ["장기 전쟁과 아메리카 은의 압력으로 아크체의 은 함량이 절반으로 줄었다. 물가 혁명은 시파히 체제의 해체와 젤랄리 반란의 혼란을 키웠다.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["타브리즈 정복", "6506bdb9"], "d": ["총사령관(세르다르) 외즈데미르오을루 오스만 파샤가 타브리즈에 입성했으며, 사파비의 옛 수도가 오스만의 통치 아래 들어갔다. 오스만 파샤는 몇 주 뒤 진영에서 서거했다.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["페르하드 파샤 조약 — 동방에서의 최대 판도", "c429972f"], "d": ["샤 압바스의 사절 하이다르 미르자가 이스탄불에 도착한(1590년 1월 18일) 뒤, 정복지를 오스만에 남긴다는 조건으로 맺어져 12년 전쟁을 끝낸 이 조약으로 타브리즈, 카라바흐, 시르반, 조지아, 로레스탄이 오스만에 남았으며, 제국은 동방에서 역사상 가장 넓은 국경에 도달했다.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["오스만-사파비 전쟁(1603-1612) 발발 — 샤 압바스의 반격과 타브리즈 상실", "abf27dd8"], "d": ["군대를 재편한 샤 압바스는 젤랄리 반란의 혼란을 틈타 공세에 나섰다. 타브리즈가 함락되었고, 캅카스에서 얻은 성과는 몇 년 안에 상실되었다. 같은 원정과 그 이후에 상실한 다른 정착지: 나흐츠반, 호이, 마란드, 살마스. 카라자다으(아하르)와 무크리의 영주들도 사파비 편으로 돌아섰다.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["에블리야 첼레비 탄생", "2b6051ff"], "d": ["50년이 넘는 여행을 10권의 『세야하트나메(여행기)』에 담은 에블리야 첼레비는 17세기 오스만 세계의 비길 데 없는 파노라마를 남겼다.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["나수흐 파샤 조약", "bb69e388"], "d": ["1603년부터 이어진 전쟁을 끝낸 이 조약으로 1590년의 획득을 포기하고 1555년 아마시아 국경으로 돌아갔으며, 동부 전선의 균형이 다시 확립되었다.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["술탄 아흐메드 모스크 개관", "e39dfd43"], "d": ["여섯 개의 첨탑과 푸른 이즈니크 타일을 가진 '블루 모스크'는 고전기의 마지막 대규모 술탄 복합 단지이다.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["술탄 이브라힘의 처형", "bc4eb452"], "d": ["낭비와 국정의 위기를 이유로 군단과 울레마의 동맹이 이브라힘을 폐위했으며, 열흘 뒤 파트와(법적 견해)에 따라 교살되었다. 일곱 살의 메흐메드 4세가 즉위했고, 권력은 사실상 대왕대비 쾨셈 술탄의 손에 넘어갔다.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["캬티브 첼레비의 죽음", "e167e89d"], "d": ["서지 『케슈퓌쥬누눈』과 지리서 『지한뉘마』로 오스만 학술사의 정점에 선 이름이며, 유럽 자료를 활용한 선구적인 접근으로 알려져 있다.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["에디르네 사건 — 무스타파 2세의 폐위", "0291c1cd"], "d": ["술탄이 에디르네에 머무는 것과 페이줄라 에펜디의 세력에 대한 분노는 군인과 상공인의 대규모 봉기로 번졌다. 셰이흘이슬람은 군중에게 살해되고 술탄은 폐위되었으며, 궁정은 이스탄불로 돌아왔다.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["파리 주재 대사: 이르미세키즈 메흐메드 첼레비", "26312a3f"], "d": ["프랑스에 파견된 대사절단은 서구를 현지에서 살펴본 최초의 체계적인 관찰이었으며, 그의 『세파레트나메(사행록)』는 튤립 시대의 쇄신에 영감을 주었다.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["최초의 오스만 인쇄소 설립", "4943f7e5"], "d": ["튀르크어 서적의 인쇄 허가가 내려졌고, 첫 작품인 반쿨루 사전이 1729년에 인쇄되었다. 인쇄소는 튤립 시대 쇄신의 가장 영속적인 유산이다.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["카피툴레이션의 항구화", "d044a79e"], "d": ["프랑스에 부여된 특권은 해당 술탄의 치세에 한정되지 않고 영구 조약으로 묶였다. 일방적으로 폐기할 수 없게 된 카피툴레이션 체제는 로잔에서야 폐지될 수 있었다.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["황립 해군 공병 학교(뮈헨디스하네이 바흐리이 휘마윤) 설립", "9bf3f439"], "d": ["체슈메의 참사 이후 근대적 해군 장교를 양성하기 위해 설립된 이 공병 학교는 서구식 기술 교육의 최초의 영구적 기관이다. 육군 공병 학교는 1795년에 뒤따랐다.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["런던에 최초의 상주 대사관 설치", "6b5630eb"], "d": ["니자므 제디드 프로그램의 일환으로 유럽 수도들에 상주 대사관이 개설되었으며, 오스만 외교는 상호주의 원칙으로 옮겨 갔다.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["알렘다르 무스타파 파샤의 죽음", "4426534e"], "d": ["1808년 11월 15일 밤에 시작된 예니체리 봉기에서, 바브알리(대재상부)에 포위된 개혁파 대재상은 기다리던 원군이 오지 않자 이튿날 화약고에 불을 질러 수백 명의 공격자와 함께 죽었다. 세네디 이티팍 체제와 첫 개혁 시도는 그와 함께 묻혔다.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["최초의 관보: 타크비미 베카이", "c637f623"], "d": ["국가의 관보가 발행되기 시작했다. 이는 근대적 여론과 공식 공지 전통의 시작이다.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["발타 리마느 통상 조약", "e790b383"], "d": ["영국은 국내 상업에서조차 가장 특혜적인 지위를 인정받았고 전매 제도(예드 이 바히드)는 폐지되었다. 국내 생산이 보호받지 못하게 된 가운데, 이 조약은 오스만 시장이 자유 무역에 전면 개방되었음을 보여 주는 문서가 되었다.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["레바논 에미르령의 종말 — 바시르 시하브 3세의 해임", "f85ae454"], "d": ["기독교도와 드루즈의 갈등 및 슈프 지방의 내부 균형을 통제하지 못한 에미르 바시르 2세(3세)는 1842년 1월에 해임되었다. 1516년부터 (마안 가문과 이어 시하브 가문을 통해) 이어진 현지 에미르령 체제는 끝났으며, 이 지역은 오스만의 직접 통치로, 이어 이중 카임마캄 제도로 넘어갔다.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["화폐 정비: 메지디예 체제", "c77be809"], "d": ["화폐 개혁으로 순도가 떨어진 주화들이 회수되었고, 금 리라(메지디예)를 기준으로 하는 안정적인 금은 복본위제가 수립되었다.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["바알베크 하르푸시 가문의 지방 지배 종식", "8438f4ae"], "d": ["1521년(잔비르디 가잘리의 반란 이후)부터 바알베크에서 작은 지방 왕조로 군림하던 하르푸시 가문의 세력은 오스만 정부의 새로운 행정 개편으로 끝났으며, 도시는 다마스쿠스주에 속한 평범한 카자(군) 중심지가 되었다.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["시르케티 하이리예 설립", "462830e7"], "d": ["보스포루스에서 증기선을 운항하기 위해 설립된 이 회사는 최초의 오스만 주식회사로 여겨진다. 증기선 선착장은 도시 생활에 뚜렷한 자취를 남겼다.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["최초의 외채 계약", "9017c579"], "d": ["크림 전쟁의 자금을 마련하기 위해 런던 시장에서 최초의 외채를 들여왔다. 21년 동안 15차례의 차입 끝에 도달한 지점은 1875년의 지불 유예와 오스만 공채 관리청이었다.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["이스탄불의 전신선", "d320f39f"], "d": ["크림 전쟁의 필요에 따라 가설된 최초의 전신선이 운영을 시작했으며, 제국은 수십 년 만에 세계에서 가장 넓은 전신망 가운데 하나를 갖게 되었다.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["토지법(아라지 카눈나메)", "6bae243a"], "d": ["토지법을 근대화한 이 법령은 국유지(미리)에서의 사실상의 점유를 토지 등기(타푸)와 연결했으며, 오늘날 중동의 소유 질서의 기본 문서 가운데 하나이다.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["다륄퓌눈의 첫 강의", "08f74066"], "d": ["대학 수준의 교육을 담당할 다륄퓌눈이 공개 강의로 활동을 시작했다. 중단을 거듭하며 이어진 이 기관은 1900년에 영구적으로 개교했으며 이스탄불 대학교의 핵심이 되었다.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["주(빌라예트) 규정", "ad20853b"], "d": ["에얄레트 제도를 대신하여 프랑스 모델의 빌라예트 조직이 수립되었으며, 미드하트 파샤의 도나우주 시행 사례를 본보기로 전국에 확대되었다.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["압뒬아지즈의 유럽 순방", "9ff0fa1e"], "d": ["오스만 술탄의 평화 목적 유럽 방문으로는 최초였다. 파리 박람회와 런던 방문은 외교와 근대화를 동시에 보여 주는 진열장 구실을 했다.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["갈라타사라이 황립 고등학교(메크테비 술타니) 개교", "f9688524"], "d": ["프랑스어로 교육한 이 고등학교는 종교와 민족 공동체(밀레트)를 가리지 않는 학생 구성으로 교육 평등이라는 탄지마트 이상의 상징이 되었다.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["메젤레 제1권 시행", "6475461c"], "d": ["이슬람법의 채권·물권 분야를 근대적 입법 기술로 집성한 메젤레는 최초의 이슬람 민법전으로 여겨진다. 제브데트 파샤가 이끈 위원회는 1876년에 16권을 완성했다.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["압뒬아지즈의 폐위", "eb7397ea"], "d": ["입헌파 정치가들과 군 수뇌부는 조용한 쿠데타로 압뒬아지즈를 끌어내렸다. 닷새 뒤의 의문스러운 죽음과 이어진 츠라안 사건들은 여러 해 동안 이어질 청산 다툼을 낳았다.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["츠라안 습격 (알리 수아비 사건)", "d2a9ac87"], "d": ["언론인 알리 수아비는 무라드 5세를 다시 왕위에 앉히기 위해 츠라안 궁을 습격했다. 습격은 유혈 진압되었고, 압뒬하미드 정권은 경비망을 영구적으로 강화했다.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["레지 관리국 설립 (담배 전매)", "bad9b030"], "d": ["담배 세입은 오스만 공채 관리청 산하의 외국 자본 회사인 레지에 이양되었다. 농민과 감시원(콜주) 사이의 '레지 밀수' 충돌은 수십 년 동안 이어졌다. 같은 날짜에 상실한 다른 정착지: 제일라.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["빌헬름 2세 황제의 이스탄불·예루살렘 방문", "2988cd06"], "d": ["독일 황제의 두 번째 방문은 오스만-독일의 접근을 확고히 했다. 바그다드 철도 이권의 길이 열렸고, 다마스쿠스에서는 '3억 무슬림의 친구'라는 연설이 이루어졌다.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["메디나에 닿은 히자즈 철도", "95009b9c"], "d": ["오직 무슬림의 기부금과 자국의 기술로 건설된 1464km의 노선이 메디나에 닿았으며, 성지 순례 여정은 몇 주에서 며칠로 줄었다. 압뒬하미드 2세 시대의 가장 큰 기반 시설 사업이다.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["3월 31일 사건", "1d7c2bb2"], "d": ["입헌 체제에 반대하는 대규모 봉기가 이스탄불을 장악했다. 테살로니키에서 온 행동군이 반란을 진압했고 압뒬하미드 2세는 폐위되었다.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["에디르네 포위 시작", "234d9b28"], "d": ["쉬크뤼 파샤의 다섯 달에 걸친 방어는 발칸의 참사 속에서 저항의 서사시가 되었다. 도시는 기아로 함락되었으며 1913년 7월에 되찾았다.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["바브알리(대재상부) 습격", "b304d02d"], "d": ["에디르네를 넘겨줄 준비를 하던 정부는 통일파의 무장 습격으로 무너졌고, 육군 장관 나즘 파샤는 살해되었다. 통일진보위원회의 전면 집권기가 시작되었다.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["레바논산 무타사르리프령 폐지", "b5639051"], "d": ["1861년 기본 규정(Règlement Organique)으로 설립되어 1864년에 갱신된 국제 의정서에 기초한 자치 무타사르리프 체제는 제1차 세계 대전 중에 오스만 국가에 의해 일방적으로 폐지되었으며, 내무부는 이 지역에 무슬림 무타사르리프(지사)를 직접 임명하기 시작했다. 1861년부터 1915년까지 8명의 무타사르리프가 재임한 자치 시기는 이렇게 막을 내렸다.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["왕자들 사이의 국토 분할", "82f26bfb"], "d": ["앙카라의 패전 이후 쉴레이만 첼레비는 루멜리아로 건너가 에디르네에서 술탄을 선언했다. 이사 첼레비는 부르사를, 첼레비 메흐메드는 아마시아-토카트-시바스 지역을 장악했다. 지도에서는 이 세 몫이 각각 다른 색으로 표시된다.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["갈리폴리 조약: 메셈브리아까지의 흑해 연안을 비잔티움에 이양", "a4164eca"], "d": ["앙카라의 패전 이후 루멜리아에서 자리를 지키려던 에미르 쉴레이만은 갈리폴리에서 비잔티움 황제 마누엘과 조약을 맺었다. 그는 카르탈, 펜디크, 게브제와 일부 섬들, 루멜리아의 테살로니키와 테살리아, 그리고 흑해에서는 메셈브리아까지 이어지는 해안 지대를 비잔티움에 넘겨주었으며, 비잔티움이 오스만에게 바치던 세금도 폐지되었다. 이로써 이스트란자 해안의 아흐토폴, 이으네아다, 레조보는 21년 동안 비잔티움의 통치 아래 남았으며, 무라드 2세는 1424년의 평화 협정으로 이곳들 대부분을 되찾았다.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["억류 중 이을드름 바예지드의 죽음", "7e968d83"], "d": ["티무르에게 포로로 잡혀 있던 술탄은 악셰히르에서 서거했으며, 그의 유해는 부르사로 옮겨져 안장되었다. 그의 죽음은 왕자들 사이의 왕위 다툼을 돌이킬 수 없게 만들었다.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["갈리폴리 조약 — 비잔티움에 대한 양보", "dfacbd00"], "d": ["루멜리아에서의 지위를 확보하려던 쉴레이만 첼레비는 비잔티움 및 라틴 국가들과 합의하여 테살로니키, 마르마라 연안, 일부 섬들을 반환했으며, 심지어 공납을 바치는 것까지 받아들였다.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["울루바트 전투 — 이사 첼레비의 패배", "500c5d24"], "d": ["부르사를 장악하고 있던 이사 첼레비는 울루바트에서 동생 메흐메드에게 패했으며, 몇 차례의 재기 시도도 성과 없이 끝났다.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["이사 첼레비의 소멸", "0effa11e"], "d": ["쉴레이만 첼레비의 지원을 받아 몇 차례 아나톨리아로 돌아왔던 이사 첼레비는 마지막 패배 이후 자취를 감추었다. 그의 몫은 첼레비 메흐메드에게 넘어갔으며, 지도에서 메흐메드의 영역은 서쪽으로 넓어졌다.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["무사 첼레비의 왈라키아행", "8441267a"], "d": ["쉴레이만 첼레비에게 부르사와 앙카라를 잃고 토카트-아마시아로 물러난 첼레비 메흐메드는 동생 무사에게 루멜리아로 가도록 부추겼다. 무사는 왈라키아 총독 미르체아의 초청을 받아들여 해로로 왈라키아에 도착했으며, 이곳에서 쉴레이만을 두 전선 사이에 놓이게 할 투쟁에 나서게 된다.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["첼레비 메흐메드의 부르사·앙카라 탈환 — 아나톨리아 몫이 쉴레이만 첼레비에게서 벗어남", "bfb69f12"], "d": ["무사 첼레비가 루멜리아에서 거둔 성공(얌볼, 1410년 2월 13일)에 대응하여, 아나톨리아에 있던 에미르 쉴레이만 첼레비는 루멜리아로 건너갔다. 쉴레이만이 아나톨리아를 떠난 뒤 메흐메드 첼레비는 앙카라를 포함한 부르사 일대를 다시 장악했으며, 즉위의 표시로 813년 연호가 새겨진 화폐를 주조하게 했다. 지도에서 마르마라의 아나톨리아 쪽은 에미르 쉴레이만의 몫에서 첼레비 메흐메드의 색으로 바뀐다.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["코스미디온 전투", "0efc2caa"], "d": ["비잔티움의 지원을 받아 이스탄불 성벽 앞에서 벌어진 전투에서 쉴레이만 첼레비는 동생 무사를 격파했으나, 루멜리아에서 그의 지지 기반은 빠르게 녹아내리기 시작하고 있었다. 같은 날짜에 상실한 다른 정착지: 엘라소나, 아이토스, 볼라이으르(지도상 루멜리아에서 무사에게서 쉴레이만에게 넘어간 곳).", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["무사 첼레비의 이스탄불 포위", "4932f586"], "d": ["쉴레이만을 지원한 비잔티움을 응징하려던 무사 첼레비는 이스탄불을 포위했으며, 이 포위는 비잔티움을 첼레비 메흐메드와의 동맹으로 몰아갔다.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["에미르 쉴레이만의 죽음 — 루멜리아를 장악한 무사", "325c1549"], "d": ["에디르네에서 도주하다 붙잡힌 쉴레이만 첼레비는 살해되었으며, 루멜리아 전체가 무사 첼레비의 손에 넘어갔다. 지도에서 루멜리아는 파란색에서 보라색으로 바뀐다.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["차무를루 전투 — 통일의 회복", "0b23173e"], "d": ["비잔티움, 세르비아 전제공국, 루멜리아 영주들의 지원을 얻은 첼레비 메흐메드는 차무를루에서 동생 무사에게 결정적인 패배를 안겼고, 무사는 도주 중에 살해되었다. 무사가 장악하던 루멜리아는 에디르네와 함께 메흐메드에게 넘어갔으며, 메흐메드 첼레비는 에디르네에서 자신이 오스만 국가의 유일한 통치자임을 선포했다. 11년에 걸친 공위 시대가 끝났고, 지도상의 왕자들의 몫은 하나의 몸체로 합쳐졌다.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["빈 원정 결정 — 바슈바르 평화는 갱신되지 않고 목표는 죄르에서 빈으로 바뀌다", "1bf278f2"], "d": ["황제 레오폴트 1세는 아직 만료되지 않은 바슈바르 조약의 갱신을 원했고, 메흐메드 4세도 평화 쪽으로 기운 듯 보였다. 그러나 대재상 메르지폰루 카라 무스타파 파샤는 자신이 중부 헝가리의 왕으로 선포하게 한 퇴쾨이 임레의 불만을 근거로 평화를 갱신하지 못하게 했으며, 바니 메흐메드 에펜디를 필두로 한 설교자들을 동원해 술탄이 전쟁을 결심하도록 설득했다. 협의에서 술탄은 베오그라드에 남고 총사령관(세르다르 에크렘)은 죄르를 점령하러 전진하기로 결정되었다. 그러나 세케슈페헤르바르(이스톨니 벨그라드)에서 열린 협의에서는 크림 칸 무라드 기라이와 부다 총독 우준 이브라힘 파샤의 반대에도 불구하고 목표가 빈 포위로 바뀌었다.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["제2차 빈 포위 시작 — 빈 앞에 이른 군대", "bb542e49"], "d": ["대재상 카라 무스타파 파샤가 지휘하는 오스만군은 1683년 7월 14일 빈 앞에 도착했다. 황제 레오폴트 1세는 도시의 방어를 슈타르헴베르크에게 맡기고 오스트리아 내륙으로 물러났다. 첫 번째와 달리 처음부터 빈을 목표로 준비된 이 두 번째 포위는 9월 12일까지 이어진다.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["파르카니의 패주와 에스테르곰 상실", "a7366740"], "d": ["빈에서 퇴각하던 군대는 파르카니에서 두 번째로 패주했으며, 이어 헝가리의 요충 요새 가운데 하나인 에스테르곰이 함락되었다. 퇴각은 붕괴로 바뀌기 시작했다.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["메르지폰루 카라 무스타파 파샤의 처형", "ce8b10ac"], "d": ["빈 패전의 책임자로 지목된 대재상은 베오그라드에서 교살되었다. 그러나 그의 처형은 전선을 바로잡지도, 흔들린 국가의 위신을 되돌리지도 못했다.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["신성 동맹 결성", "060280d0"], "d": ["교황청의 주도로 오스트리아, 폴란드, 베네치아 사이에 오스만에 맞선 신성 동맹이 결성되었고, 1686년에는 러시아도 가담했다. 이로써 제국은 16년 동안 이어질 다전선 전쟁에 들어섰다.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["제1차 부다 방어전", "ccc43630"], "d": ["신성 동맹군의 첫 번째 부다 포위는 넉 달 동안 이어진 요새의 완강한 방어로 격퇴되었다. 그러나 헝가리의 요새들은 계속해서 하나씩 함락되고 있었다.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["우이바르 상실", "689ab78c"], "d": ["22년 동안 오스만의 수중에 있었고 유럽에서 속담이 되었던 우이바르(노베잠키) 요새가 함락되었으며, 상부 헝가리에서의 오스만의 존재가 와해되었다.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["바라드에서의 퇴쾨이 체포 — 중부 헝가리 왕국의 해체와 상부 헝가리 요새들의 항복", "1741aaaf"], "d": ["빈 패전 이후 오스만은 퇴쾨이도 전쟁과 패배를 초래한 자들 가운데 하나로 보기 시작했다. 1685년 10월 15일 총사령관(세르다르) 멜레크 이브라힘 파샤의 명령으로 바라드 베일레르베이 아흐메드 파샤는 원군으로 온 퇴쾨이를 붙잡게 했는데, 그를 합스부르크에 넘겨 더 나은 강화 조건을 얻어 내려는 기대가 있었다. 체포 소식이 퍼지자 그의 아내 즈리니 일로너가 지키던 문카치를 제외한 중부 헝가리 왕국의 모든 요새와 도시가 합스부르크에 항복했고, 쿠루츠 병사의 대부분은 합스부르크군에 넘어갔다. 퇴쾨이가 1686년 1월 2일 베오그라드에서 풀려났을 때 왕국은 이미 사라진 뒤였다.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["부다 상실 — 145년간의 헝가리 수도", "70800e2b"], "d": ["78일 동안 이어진 포위 끝에 부다가 함락되었으며, 마지막 베일레르베이 압두라흐만 압디 파샤는 성벽에서 순교했다. 1541년부터 오스만의 통치 아래 있던 이 도시의 상실은 헝가리 상실의 상징으로 여겨진다. 같은 날짜에 상실한 다른 정착지: 페슈트.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["제2차 모하치(허르샨) 패전 — 트란실바니아와 모하치의 상실", "a7922681"], "d": ["1526년에 대승을 거두었던 평원에서 이번에는 대패를 당했다. 군대는 흩어졌고, 반란을 일으킨 병사들은 대재상을 파면시켰다. 이 패배는 트란실바니아의 상실로도 이어졌다.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["아테네 상실과 파르테논 폭발", "b6691730"], "d": ["베네치아 포병이 쏜 포탄이 오스만이 화약고로 쓰던 파르테논을 폭파했으며, 2천 년 된 신전은 폐허가 되었다. 도시는 베네치아의 손에 넘어갔다(1688년에 되찾는다).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["메흐메드 4세의 폐위와 쉴레이만 2세의 즉위", "9f53037c"], "d": ["전선의 참사와 군대의 반란에 이어, 39년의 치세 끝에 메흐메드 4세가 폐위되고, 40년 동안 '새장(카페스)'에 갇혀 지낸 동생 쉴레이만 2세가 옹립되었다.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["베오그라드의 첫 상실 — 신성 동맹의 포위", "c6b9b19a"], "d": ["1521년 이래 오스만의 수중에 있던 베오그라드가 신성 동맹군에 항복했다. 세르비아의 문이 적에게 열렸고 위험은 니시-소피아 선까지 닥쳤다. 지도상 같은 날짜에 오스만에서 합스부르크로 넘어간 다른 정착지: 히사르즈크(그로츠카) — 베오그라드의 상위 중심지 연쇄를 따른다(TDV belgrad; 명시된 근사치).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["바덴, 포자레바츠 앞에서 모라바강 도하 — 포자레바츠가 오스트리아에 함락", "bcf3fc59"], "d": ["바덴 변경백 루트비히는 1689년 8월 포자레바츠에서 모라바강을 건너 니시 방면으로 진격했으며, 이 도시는 1690년 여름까지 오스트리아의 수중에 남았다(TDV suleyman-ii는 1690년에 포자레바츠를 되찾았다고 말한다). 날짜와 뢰더의 해독은 재검증되지 않았다.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["니시 상실 — 합스부르크(헝가리 왕관)의 진격, 가장 위태로운 해", "c5e27b3f"], "d": ["합스부르크(헝가리 왕국 왕관)의 진격은 니시마저 오스만의 통치에서 빼앗았으며, 습격은 스코페와 프리슈티나까지 이르렀다. 비딘은 그 뒤인 1689년 10월에 함락되었다(별도 항목). 전쟁의 가장 어두운 해에 국가는 수도마저 위협받고 있다고 느꼈다.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["오르쇼바와 페튈이슬람에 오스트리아 수비대 주둔", "ee8dd875"], "d": ["비딘이 전투 없이 점령된(1689년 10월, TDV vidin) 뒤, 바덴은 1689년 10월 25일 오르쇼바와 페튈이슬람을 보수하고 수비대를 두었으며, 오르쇼바는 1690년 가을까지 오스트리아에 남았다. 날짜는 Bánlaky/Röder에 근거하며 재검증되지 않았다.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["니시가 다시 오스만의 손에", "0c4f44eb"], "d": ["파즐 무스타파 파샤는 1690년 7월에 원정에 나섰다. 셰히르쾨이(피로트), 포자레바츠, 귀베르진리크를 점령한 뒤 포위한 니시는 1690년 9월 27일 오스만의 손에 들어왔다(TDV semendire). 같은 시기에 비딘도 되찾아졌다. 지도상 같은 날짜에 합스부르크에서 오스만으로 돌아온 다른 정착지: 야고디나와 위르퀴프(프로쿠플레) — 지점 단위의 날짜를 찾지 못해 니시의 날짜를 취했다(TDV semendire; 명시된 근사치. 뢰더 1842는 재상이 9월 8-24일에 야고디나를 지났다고 적고 있으며, 이 모순은 해결되지 않았다).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["스메데레보에서 오스트리아 부대 항복", "90da20c4"], "d": ["1690년 9월 27일 니시를 점령한 뒤, 나흘간의 포위로 스메데레보의 오스트리아 부대가 항복했다(TDV semendire). Bánlaky/Röder는 9월 24일이라고 한다. 사료가 서로 어긋나며 TDV를 기준으로 삼았다.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["베오그라드 탈환", "ab435838"], "d": ["대재상 쾨프륄뤼자데 파즐 무스타파 파샤는 1690년 10월 8일 오스트리아에게서 베오그라드를 되찾았으며, 1688년에 잃은 도시는 이렇게 오스만에 돌아왔다(TDV suleyman-ii). 지도상 같은 날짜에 합스부르크에서 오스만으로 돌아온 다른 정착지: 히사르즈크(그로츠카) — 베오그라드의 상위 중심지 연쇄를 따른다(TDV suleyman-ii; 명시된 근사치).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["슬란카멘의 패주 — 파즐 무스타파 파샤 순교", "10d626f1"], "d": ["세기의 가장 참혹한 회전 가운데 하나에서 대재상은 이마에 총을 맞고 순교했으며, 군대는 흩어졌다. 재기의 희망은 이 전투와 함께 꺼졌다.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["키오스섬 상실", "07c084f8"], "d": ["베네치아 함대가 키오스를 점령했으며, 에게해에서의 오스만 지배가 위협받게 되었다. 섬은 이듬해에 되찾아진다.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["무스타파 2세의 친정 결정", "61c3ba9c"], "d": ["새 술탄은 선조들의 길을 따라 군대의 선두에 서서 원정에 나서겠다고 선언했다. 이 결정은 군대의 사기를 높였고 2년 동안 이어질 술탄 친정의 시기를 열었다.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["키오스 탈환", "6b496fca"], "d": ["오이누세스 제도(코윤 아달라르) 해전에서 베네치아 함대를 격파한 메조모르토 휘세인 파샤가 키오스를 되찾았다. 이는 오스만 해양 활동의 짧은 부활을 알리는 신호였다.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["루고지 전투의 승리 — 무스타파 2세의 제1차 오스트리아 원정", "d5ee9b34"], "d": ["술탄이 직접 참가한 첫 원정에서 리포바를 되찾았고 루고지에서 오스트리아군을 격파했다. 여러 해 이어진 패배의 사슬에서 처음으로 단절이 일어났다. 지도는 카란세베슈도 이 원정에서 합스부르크에서 오스만으로 돌아온 것으로 본다. 사료는 1695년 9월만 제시하며(TDV mustafa-ii), 지도의 날짜는 루고지 기록에서 취했다(명시된 근사치).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["아조프 요새 상실", "2b78b5cd"], "d": ["흑해로 나아가려던 표트르 1세는 두 번째 포위에서 아조프를 점령했다. 러시아는 처음으로 오스만의 요새에 영구적으로 자리 잡았으며 해군국으로 가는 첫걸음을 내디뎠다.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["울라슈(올라신) 전투의 승리", "02ac9ca8"], "d": ["술탄의 두 번째 원정에서 도나우강 변에서 거둔 승리는 테메슈바르를 점령하려던 오스트리아의 계획을 무산시켰다. 그러나 전쟁의 전반적인 균형은 바꾸지 못했다.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["젠타의 패주 — 전쟁의 운명이 결정되다", "475c4a7b"], "d": ["군대는 티서강을 건너던 중 오이겐 공의 기습을 받았다. 강의 양안에 갈라진 병력은 몇 시간 만에 섬멸되었으며, 대재상 엘마스 메흐메드 파샤를 비롯한 수천 명의 병사와 관료가 죽었다. 오스만 역사상 가장 참혹한 패배 가운데 하나인 젠타 전투는 강화 협상을 피할 수 없게 만들었다.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["카를로비츠 강화 회담 시작", "1f395cf3"], "d": ["영국과 네덜란드의 중재로 시작된 회담에서 오스만 대표단은 처음으로 '우티 포시데티스'(현재 점유하고 있는 것을 그대로 보유한다) 원칙을 받아들여야 했다. 72차례의 회기에 걸친 협상은 근대 오스만 외교의 탄생으로 여겨진다.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["카발랄르 메흐메드 알리의 이집트 상륙", "514c943f"], "d": ["프랑스 점령하의 이집트를 되찾기 위해 파견된 오스만군에는 카발라에서 모집한 의용 부대도 있었다. 30대의 메흐메드 알리는 이 부대의 부지휘관이었으며, 총독이 아닌 중대 장교로서 이집트에 발을 디뎠다.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["알바니아 병사들이 이집트 총독을 축출", "c76a0ec2"], "d": ["급료(울루페)를 받지 못한 알바니아 부대가 반란을 일으켜 총독 휘스레브 파샤를 성채에서 달아나게 했다. 프랑스군의 철수로 생긴 공백 속에서 맘루크 베이들, 알바니아 군단, 바브알리가 임명한 총독들이 삼각 투쟁에 들어갔고, 메흐메트 알리는 이 삼각 구도에서 균형을 만들어 내며 두각을 나타냈다. 같은 날짜에 상실한 다른 정착지: 타이프.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["카이로의 울레마가 메흐메트 알리를 총독으로 선포", "a16752f2"], "d": ["과중한 세금에 시달리던 카이로의 상인·수공업자와 울레마는 나키브 알아슈라프 우마르 마크람의 지도 아래 봉기하여 총독 후르시드 파샤를 인정하지 않겠다고 선언하고, 메흐메트 알리를 총독 자리에 앉혔다. 총독이 백성에 의해 선출된 것은 오스만 역사에서 보기 드문 사건이다.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["바브알리가 기정사실을 수용: 이집트 총독 임명 칙령", "b86736a3"], "d": ["이집트에서 자기 후보를 지켜 낼 힘이 없던 바브알리는 메흐메트 알리에게 베지르 직위와 함께 이집트 총독 임명 칙령을 보냈다. 지도에서 이집트는 이 날짜부터 종속(옅은 색조) 층으로 넘어간다. 법적으로는 오스만 영토이지만 사실상 카발라 가문의 나라이다. 같은 날짜에 종속 층으로 넘어간 다른 정착지: 카이로, 알렉산드리아, 다미에타, 아시우트, 아스완, 이브림, 수에즈, 라시드(로제타).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["영국의 프레이저 원정대가 알렉산드리아에 상륙", "4d6c31be"], "d": ["오스만 제국이 프랑스에 접근하자 영국은 이에 대응해 이집트에 상륙 부대를 보냈다. 메흐메트 알리는 당시 상이집트에서 맘루크와 싸우고 있었으나, 급히 돌아와 방어를 조직했다.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["라시드(로제타)의 패주 — 영국군 격퇴", "3636004c"], "d": ["라시드 읍에 진입한 영국군 종대는 시가전에서 큰 손실을 입었고, 9월에 병력은 이집트에서 완전히 철수했다. 이 승리는 이집트와 이스탄불 양쪽에서 메흐메트 알리의 위신을 확고히 했다.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["성채 사건: 맘루크 베이들의 숙청", "84030b97"], "d": ["헤자즈 원정을 위해 마련된 의식 행렬에 초청된 맘루크 베이들은 카이로 성채의 좁은 통로에 갇혀 제거되었다. 이로써 5세기에 걸친 맘루크의 세력은 끝났고, 이집트에서 메흐메트 알리에게는 더 이상 경쟁자가 남지 않았다.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["헤자즈 원정 개시 — 군대가 수에즈에서 해로로, 순례길을 따라 육로로 얀부를 향해 진군", "1c05c159"], "d": ["1803년부터 사우드-와하브 세력의 지배를 받던 두 성지(하라마인)를 되찾는 것은 마흐무드 2세의 가장 큰 정통성 문제였다. 바브알리의 힘으로는 부족했기에 이 임무는 이집트 총독에게 맡겨졌다. 메흐메트 알리는 열여섯 살 아들 투순을 군대의 선두에 세워 보냈다.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["얀부 접수 — 헤자즈 원정의 첫 해안 거점", "179bc78d"], "d": ["새로 건조한 배를 타고 수에즈를 출발한 알바니아 보병 약 2천 명이 1811년 10월 얀부 부근에 상륙했고, 읍은 이틀간의 미약한 저항 끝에 항복했다. 투순이 지휘하는 기병은 육로로 순례길을 따라 아카바와 알와즈를 거쳐 2주 뒤에야 얀부에 도착했다. 얀부는 메디나와 메카로 진군할 이집트군의 헤자즈 내 첫 거점이 되었다.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["사프라-자디다 협곡에서의 첫 패주", "99ef804d"], "d": ["좁은 산길에서 매복을 당한 이집트 선봉대는 흩어졌다. 이 패배는 원정의 전술적 교훈이 되었다. 베두인 부족들의 지원 없이는 헤자즈에서 진군할 수 없다는 것이 분명해졌다.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["메디나 탈환", "6f6a5d55"], "d": ["긴 포위 끝에 메디나가 항복했다. 예언자의 도시를 되찾은 일은 이스탄불에서 축포 행사로 기념되었고, 메흐메트 알리에게는 포상으로 제다 총독직도 주어졌다.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["메카 탈환 — 순례길이 열리다", "3d6d66a0"], "d": ["메카에 입성한 이집트군은 카바에서 다시 오스만 술탄의 이름으로 후트바를 낭독하게 했다. 10년 동안 끊겼던 순례 대상이 다시 길을 떠날 수 있게 되었다. 지도에서 헤자즈는 오스만의 지배로 돌아가지만, 그 통치가 카이로에 있으므로 종속 색조로 표시된다. 같은 날짜에 종속 통치로 넘어간 다른 곳: 제다.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["타이프 탈환 — 헤자즈 원정의 완료", "6315fb31"], "d": ["메디나(1812년 12월)와 메카(1813년 1월)에 이어, 투순 파샤가 지휘하는 이집트군은 마지막으로 타이프를 와하브파로부터 되찾았다. 10년에 걸친 사우드의 지배가 끝났고, 헤자즈의 세 성스러운 중심지는 모두 다시 오스만-이집트의 통제 아래 들어왔다.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["메흐메트 알리가 직접 헤자즈로 건너감", "fda0ea2d"], "d": ["원정이 지지부진하게 진행되는 것을 본 총독은 지휘를 직접 장악했고, 부족장들과 협상하여 사우드 전선을 내부에서 무너뜨리려 했다. 이 원정을 통해 홍해 무역에서 이집트의 몫도 커졌다.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["비살 전투: 사우드군의 패주", "9c9ab91f"], "d": ["회전에서 큰 패배를 당한 사우드군은 내륙으로 물러났다. 이때 맺은 휴전은 오래가지 못했고, 2년 뒤 작전은 나지드의 심장부로 옮겨지게 된다. 본 아틀라스는 이 승리 이후 타이프 동쪽의 투라바와 후르마가 사우드의 손에서 벗어난 것으로 간주한다(사건의 출처는 로리머의 『지명사전(Gazetteer)』이며, 각 정착지에 특정된 증거와 1월 13일이라는 날짜는 명시해 둔 근사치이다).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["이브라힘 파샤가 나지드 원정에 나섬", "d5ed80d1"], "d": ["동생 투순이 죽자 지휘권을 넘겨받은 이브라힘 파샤는 사막에서 2년에 걸친 고된 행군에 들어갔다. 우물에서 우물로 전진한 군대는 부족들을 하나씩 제압하며 사우드의 수도에 육박했다.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["디리야 함락 — 제1차 사우드 왕국의 종말", "aa96206d"], "d": ["6개월에 걸친 포위 끝에 디리야는 항복했고 파괴되었다. 아미르 압둘라 이븐 사우드는 이스탄불로 압송되어 처형되었다. 오스만의 깃발이 아라비아 내륙 이처럼 깊숙한 곳까지 이른 것은 처음이었으며, 나지드 수비대는 1824년까지 주둔했다. 같은 날짜에 편입된 다른 곳: 디리야(나지드).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["수단 원정 개시", "b1fc6905"], "d": ["메흐메트 알리의 목적은 세 가지였다. 자신의 군대에 병사를 모으고, 센나르의 금을 손에 넣으며, 도망친 맘루크 잔당을 없애는 것이었다. 그의 아들 이스마일 파샤가 지휘하는 부대는 나일강을 따라 남쪽으로 내려갔다.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["동골라가 무력 충돌 없이 이집트군에게 넘어감(맘루크는 1820년 6월에 이미 떠났다)", "bc5942c0"], "d": ["나일강의 큰 굽이에 있는 동골라는 맘루크가 1820년 6월에 버리고 떠난 뒤, 무력 충돌 없이 이스마일 파샤의 이집트군 손에 넘어갔다. 지도에서 수단은 이 날짜부터 종속 층에 나타난다. 정복한 것도 카이로이고 다스리게 될 것도 카이로이다.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["자발 알다이카 전투 — 샤이키야 연맹이 이집트군에게 결정적으로 패배", "befc9539"], "d": ["무함마드 알리 파샤의 아들 이스마일 파샤의 군대는 쿠르티에서의 첫 교전 한 달 뒤, 자발 알다이카 부근에서 벌어진 두 번째이자 결정적인 전투에서 샤이키야를 격파했다. 샤이키야의 수장 마크 수바이르는 항복했고, 마크 샤위시는 저항을 계속했다. 이후 나일강 굽이에 대한 이집트의 지배는 확고해졌다.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["센나르(푼지) 술탄국의 항복", "3cac7dd2"], "d": ["300년 역사의 푼지 왕조는 싸우지 않고 항복했다. 같은 해 나일강의 두 지류가 합류하는 지점에 세워진 진영은 곧 수단의 행정 중심지 하르툼으로 바뀌었다. 같은 날짜에 편입된 다른 곳: 센나르.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["코르도판 점령", "06440602"], "d": ["서쪽으로 파견된 제2종대는 바라(Bâra)에서 다르푸르군을 격파하고 누후드 일대와 함께 코르도판을 차지했다. 이로써 수단에 대한 이집트의 지배는 나일 계곡에서 서쪽 초원 지대까지 확대되었다.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["이집트군이 크레타에 상륙", "835aee90"], "d": ["그리스인의 반란이 크레타로 번지자 바브알리는 섬에 이집트군을 보내 달라고 요청했다. 섬에서 메흐메트 알리의 영향력은 이 개입으로 시작되었고, 8년 뒤 그에게 크레타 총독직이 주어지는 것으로 귀결되었다.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["셴디에서 이스마일 파샤 피살", "223860c9"], "d": ["과중한 세금과 병력 요구에 격분한 현지 아미르 니므르는 이스마일 파샤가 묵던 집에 불을 질러 그와 수행원들을 불태워 죽였다. 보복 원정은 이 지역을 피바다로 만들었고, 이후 수단의 통치는 강압 위에 세워졌다.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["마흐무드 2세가 모레아 문제로 메흐메트 알리에게 지원을 요청", "03594a42"], "d": ["예니체리 군대로는 3년이 지나도 진압하지 못한 모레아 반란 때문에, 술탄은 유럽식으로 훈련된 이집트군에 도움을 청했다. 그 대가로 모레아 총독직과 크레타가 약속되었다. 이 요청은 제국이 자기 속주에 의존하게 되었다는 최초의 공개적인 시인이었다.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["이브라힘 파샤가 모돈에 상륙", "9c993dba"], "d": ["이집트 함대의 엄호를 받은 상륙 부대가 모레아의 남서쪽 끝에 발을 디뎠다. 니자미 정규 보병과 야전 포병을 갖춘 이 군대는 반란 무장대를 상대로 단기간에 우위를 차지했다.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["트리폴리차 탈환 — 모레아의 중심지 함락", "8a478c11"], "d": ["반란의 행정 중심지였던 트리폴리차가 함락되면서 모레아의 대부분이 다시 통제 아래 들어왔다. 지도에서 이 반도는 이집트군의 수중에 있으므로 종속 색조로 나타난다.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["미솔롱기(메솔롱기) 함락", "07257f87"], "d": ["1년에 걸친 포위 끝에 도시가 점령되었다. 그러나 이 방어전이 유럽 언론에 불러일으킨 반향은 그리스의 대의에 대한 동정을 절정에 이르게 했고, 열강이 개입할 토대를 마련했다.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["아테네 아크로폴리스 접수", "3b19f946"], "d": ["아크로폴리스가 함락되면서 그리스 반란은 군사적으로 거의 끝난 상태였다. 바로 이 시점에 문제는 국내 반란을 넘어 유럽 외교의 의제가 되었다.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["런던 조약: 세 열강이 그리스의 자치를 강요", "7ce46fd8"], "d": ["영국, 프랑스, 러시아는 오스만과 그리스인에게 휴전과 자치 조건을 받아들이게 하기 위해 공동 행동을 결정했고, 거부할 경우 자국 함대가 개입할 것이라고 통고했다. 바브알리는 이 제안을 거절했다.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["알렉산드리아 협정: 이집트의 모레아 철수 결정", "cc978f37"], "d": ["나바리노에서 함대를 잃은 메흐메트 알리는 이스탄불과 상의하지 않고 영국 제독과 직접 합의하여 모레아에서 병력을 철수하기로 했다. 총독이 열강과 독자적으로 협정을 맺은 것은 다가올 위기의 전조였다.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["이집트군의 모레아 철수", "8fb742dd"], "d": ["마지막 부대가 배에 올랐다. 반도는 사실상 상실되었고, 1830년 런던 의정서와 함께 독립 그리스의 핵심 지역이 되었다. 한편 메흐메트 알리는 약속받은 모레아 총독직을 얻지 못했을 뿐 아니라 그 대가로 대규모의 함대와 군대를 잃었다. 같은 날짜에 상실한 다른 정착지: 모돈, 코론.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["크레타의 통치가 메흐메트 알리에게 맡겨짐", "7f76396d"], "d": ["모레아 상실에 대한 보상으로 크레타 총독직이 메흐메트 알리에게 주어졌다. 섬은 10년 동안 카이로에서 통치되었고, 지도에서는 이 기간 내내 종속 색조로 보인다. 같은 날짜에 편입된 다른 곳: 칸디아(크레타).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["이브라힘 파샤가 시리아에 진입 — 제1차 위기 시작", "1a5cc386"], "d": ["구실은 이집트에서 도망친 펠라(농민)들을 돌려보내지 않은 아크레 총독이었고, 진짜 이유는 시리아의 목재, 항구, 인력에 대한 메흐메트 알리의 필요였다. 군대는 시나이를 건너 팔레스타인 해안을 신속히 장악했다.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["아크레 포위전 개시", "b211d96d"], "d": ["1799년 나폴레옹을 저지했던 이 요새는 6개월 동안 버텼다. 이 포위전은 이집트군의 근대식 포병이 맞은 첫 번째 큰 시험이었다.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["아크레 함락", "0f47917b"], "d": ["성벽을 두드리던 포대가 돌파구를 열자 요새가 점령되었다. 시리아로 가는 문이 열린 것이다. 같은 시기에 바브알리는 메흐메트 알리를 반역자로 선포하고 그의 총독직을 박탈했다.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["다마스쿠스 항복", "48da3b62"], "d": ["도시는 싸우지 않고 항복했다. 이브라힘 파샤는 조세 제도와 비무슬림에게 부여하는 평등을 선포하여 현지의 지지를 얻으려 했다. 그러나 바로 이 정책들이 몇 년 뒤 그에 대한 반란의 원인이 된다. 같은 시기에 편입된 다른 곳: 베이루트, 시리아의 트리폴리, 시돈.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["홈스 전투", "867810ee"], "d": ["시리아를 구하기 위해 파견된 오스만군은 평지에서 패주했다. 예니체리가 폐지된 지 6년 뒤에 창설된 신식 군대가 아직 준비되지 않았음이 드러났다.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["알레포 점령", "9c0ead76"], "d": ["북부 시리아의 상업과 행정의 중심지도 함락되었다. 이로써 이집트군은 토로스산맥 기슭에 이르렀고 아나톨리아의 관문에 있는 고갯길들로 향했다.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["벨렌(베일란) 고개의 패주 — 추쿠로바가 열리다", "4bae872b"], "d": ["아마누스산맥의 좁은 고개에서 방어선이 돌파되었다. 안타키아, 아다나, 타르수스가 이집트군에게 넘어갔으며(TDV에 따르면 마라시 점령은 1833년이며, 별도 항목이다), 지도에서 추쿠로바는 종속 색조로 바뀐다. 아나톨리아 내륙으로 가는 길은 이제 무방비 상태였다.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["귈레크 협곡 함락 — 이첼 해안(메르신, 실리프케)이 이집트의 통제 아래 들어감", "d9049b5b"], "d": ["토로스산맥에서 추쿠로바로 통하는 관문인 귈레크 협곡이 이집트군의 손에 들어갔다. 이브라힘 파샤는 이첼 산자크에 자신의 뮈테셀림(대리 행정관)을 임명했고, 해안의 모든 부두가 이집트의 통제 아래 들어갔다. 지도에서 메르신과 실리프케는 이날부터(하한이며, 임명 날짜는 출처에 없다) 이집트에 속한 것으로 표시된다. 퀴타히아 결정에서 이양된 것은 아다나의 무하스륵(징세관직)뿐이었으므로, 이 통제는 아나톨리아 철수와 함께 끝난다.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["코니아의 에렐리가 이집트 점령하에 — 코니아–아다나 도로의 토로스 어귀", "fb908900"], "d": ["귈레크 협곡을 넘은 이집트군이 코니아로 가는 길목에 있던 에렐리는 1832년 이브라힘 파샤에게 점령되었고, 1833년 퀴타히아 합의에 따라 비워지면서 다시 카라만 주에 속하게 되었다. 지도에서 이곳은 아다나와 코니아 사이 점령선의, 출처가 있는 중간 지점이다. 울루크슐라와 카라프나르에 대해서는 도시 차원의 증거를 찾지 못했다.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["이집트군의 코니아 입성", "13952a2d"], "d": ["토로스산맥을 넘은 군대는 중부 아나톨리아에 이르렀다. 오스만 총독의 병력이 제국의 핵심 영토에서 진격한 것은 처음이었다. 같은 날짜에 편입된 다른 곳: 카라만.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["코니아 회전: 대재상이 포로가 됨", "ec82cc9a"], "d": ["안개 낀 날씨 속에 흩어진 오스만군은 큰 패배를 당했고, 대재상 레시드 메흐메드 파샤는 포로가 되었다. 국가의 중앙군은 더 이상 존재하지 않았고, 이스탄불과 이집트군 사이를 가로막을 힘은 남아 있지 않았다.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["마라시가 이집트에 점령됨", "f558e383"], "d": ["TDV에 따르면 마라시는 1833년에 카발라 가문의 이브라힘 파샤에게 점령되어 19개월 가까이 그의 통치 아래 있었다. 마라시는 퀴타히아 합의가 정한 주(州) 경계 밖에 남았으므로, 이 통치는 법적인 것이 아니라 사실상의 것이다.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["카라히사르 이 사히브(아피온)가 이집트에 점령됨 — 코니아–퀴타히아 도로", "ae0c2c78"], "d": ["코니아 회전 이후 퀴타히아로 진격하던 이집트군의 경로에 있던 카라히사르 이 사히브는 1833년 한동안 이브라힘 파샤의 수중에 있었다. 지도에서 이곳은 코니아와 퀴타히아 사이 점령선의, 출처가 있는 중간 지점이다. 아크셰히르, 으르근, 이스하클르에 대해서는 도시 차원의 증거를 찾지 못했으므로 이들은 오스만의 색으로 표시된다.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["이집트군이 퀴타히아에 도달", "214f8df6"], "d": ["이브라힘 파샤는 이스탄불에서 사흘 행정(行程) 거리에 있는 퀴타히아에서 멈췄다. 더 전진하지 않은 것은 군사적 이유가 아니라 정치적 이유 때문이었다. 러시아의 개입과 유럽의 반응을 계산에 넣었던 것이다.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["러시아 함대가 뷔위크데레 앞바다에 나타남", "6f836d61"], "d": ["영국과 프랑스에서 도움을 얻지 못한 마흐무드 2세는 어제의 적 러시아에 손을 내밀었다. 술탄이 남긴 \"물에 빠진 자는 뱀이라도 붙잡는다\"라는 말로 기억되는 이 결정은 러시아 병사들이 보스포루스·다르다넬스 해협 지대에 상륙하는 결과를 낳았고, 유럽에 경보를 울렸다.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["퀴타히아 타협(구두) — 시리아와 아다나가 카발라 가문에게", "25fe9985"], "d": ["바브알리는 이집트, 크레타, 헤자즈에 더해 다마스쿠스, 알레포, 시리아의 트리폴리, 시돈의 총독직을 메흐메트 알리에게, 아다나의 무하스륵을 이브라힘 파샤에게 넘겼다. 그 대가로 군대는 토로스산맥 남쪽으로 물러났다. 이것은 조약이 아니라 술탄이 총독에게 내린 칙령의 형식이었다. 문제는 해결된 것이 아니라 미루어졌을 뿐이었다.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["이집트군의 아나톨리아 철수가 귈레크를 통해 완료됨", "a53ac2a3"], "d": ["퀴타히아 합의 이후 이집트군은 아나톨리아에서 철수했고, 6월 중순 무렵 전군이 귈레크 협곡을 거쳐 추쿠로바로 넘어갔다. 이첼 해안(메르신, 실리프케)은 다시 오스만의 통치로 돌아가며, 아다나의 무하스륵과 시리아는 이집트에 남는다.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["휜캬르 이스켈레시 조약", "da741d5c"], "d": ["러시아와 8년 기한의 상호 방위 동맹이 체결되었다. 비밀 조항에 따르면 러시아가 공격을 받으면 오스만은 해협을 군함에 대해 폐쇄하기로 했다. 이는 오스만 외교에서 가장 논란이 많은 결정 가운데 하나가 되었고, 영국이 이집트 문제에 적극 나서게 만들었다.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["이집트 통치에 맞선 팔레스타인-나블루스 반란", "4fe43e27"], "d": ["강제 징병, 무기 압수, 새로운 세금은 팔레스타인에서 광범위한 봉기를 불러일으켰다. 반란은 가혹하게 진압되었고, 현지 주민들 사이에서 이집트 통치에 대한 지지는 급속히 사라졌다.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["마라시의 이집트 통치 종료(대략)", "bb46ca42"], "d": ["TDV의 '19개월 가까이'라는 기간 표현을 1833년의 점령부터 계산하면, 이집트의 통치는 1834년 여름 무렵에 끝난다. 1834년 퀴취크알리오을루 가문의 무스타파 베이가 이집트군에 저항하지 못하고 마라시 쪽으로 물러난 것도, 당시 마라시가 이집트의 통제 밖에 있는 피난처였음을 보여 준다.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["자발 알드루즈 봉기", "12e74626"], "d": ["드루즈 지역에서 일어난 저항은 2년 동안 이어졌다. 시리아에 쌓인 불만은 1840년 연합 함대가 해안에 상륙했을 때 이집트군의 후방을 무방비로 만들게 된다.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["메흐메트 알리가 독립 의사를 표명", "48633bbd"], "d": ["총독은 열강의 영사들에게 이집트와 시리아의 독립을 선포할 생각이 있다고 밝혔다. 영국은 이에 단호히 반대했다. 지중해에 프랑스와 가까운 강국이 등장하면 인도로 가는 길이 위협받을 것이기 때문이었다.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["오스만군이 유프라테스강을 건넘", "9af1ea69"], "d": ["마흐무드 2세는 퀴타히아에서 잃은 것을 되찾기 위해 군대를 시리아 국경으로 내몰았다. 군에 고문으로 있던 프로이센 장교 몰트케는 진지 선정과 조기 공격에 반대했으나, 그의 반대는 받아들여지지 않았다.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["니지프 전투 — 오스만군의 붕괴", "156b3cdf"], "d": ["배치가 잘못된 오스만군은 몇 시간 만에 패주했다. 패전 소식이 이스탄불에 닿기도 전에 술탄이 세상을 떠났고, 국가는 며칠 사이에 군대와 군주, 이어서 함대까지 잃게 된다.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["마흐무드 2세의 죽음", "07eccfff"], "d": ["31년의 재위 동안 예니체리를 폐지하고 중앙 행정을 다시 세운 술탄은 가장 큰 적수를 꺾지 못한 채 세상을 떠났다. 그의 병은 정확히 진단되지 못했다. 예니체리적 사고방식이 준동할지 모른다는 우려 때문에, 도시에 군사적 조치가 취해질 때까지 그의 죽음은 6월 30일까지 비밀에 부쳐졌다.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["압뒬메지드의 즉위와 마흐무드 2세의 장례", "d0f3d2cc"], "d": ["아버지가 죽자 열여섯 살의 압뒬메지드가 왕위에 올랐다. 같은 날 마흐무드 2세의 운구가 토프카프 궁전으로 들어왔다. 우려했던 혼란은 일어나지 않았고, 무슬림과 비무슬림의 광범위한 군중이 장례 행렬에 참여했다.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["함대를 알렉산드리아에 넘김", "a53e6103"], "d": ["카푸단 파샤(해군 총사령관) 아흐메드 페브지 파샤는 대재상 코자 휘스레브 파샤가 함대를 러시아에 넘길 것이라고 의심하여, 함대를 알렉산드리아로 끌고 가 메흐메트 알리에게 넘겼다. 오스만 국가는 같은 달 안에 군대도, 술탄도, 함대도 없는 처지가 되었다.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["열강의 공동 각서", "2a3b8316"], "d": ["다섯 열강은 바브알리에 각서를 보내 이집트 문제에서 단독으로 합의하지 말 것을 요구했다. 이로써 국내 문제는 공식적으로 \"유럽 문제\"가 되었고, 오스만 국가는 자기 속주에 관해 결정할 권한을 사실상 잃었다.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["런던 조약: 네 열강이 오스만의 편에 서다", "a517f775"], "d": ["프랑스를 배제한 채 체결된 이 조약은 메흐메트 알리에게 최후통첩을 보냈다. 10일 이내에 수락하면 이집트의 세습 총독직과 종신 조건의 아크레를, 20일 이내에 수락하면 이집트만을, 거부하면 아무것도 주지 않는다는 것이었다. 총독은 거부했다.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["베이루트 포격과 연합군 상륙", "0905ce92"], "d": ["영국-오스트리아 함대가 베이루트를 포격했고, 레바논 산지에서 이집트 통치에 맞서 봉기한 주민들에게 무기가 분배되었다. 시리아에 대한 이브라힘 파샤의 지배는 내부 반란과 외부 개입 사이에서 무너졌다.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["베이루트와 해안 도시들의 상실", "09bdaf23"], "d": ["바알베크 방면에서 벌어진 교전 뒤 이집트군은 해안에서 철수했다. 지도에서 레바논 해안은 종속 색조를 벗고 오스만의 직접 통치로 돌아간다.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["아크레가 두 시간 만에 함락", "5aec21f0"], "d": ["연합 함대의 포격으로 요새의 탄약고가 폭발했고, 아크레는 몇 시간 만에 항복했다. 8년 전 이브라힘 파샤가 6개월 걸려서야 점령할 수 있었던 이 요새의 함락은 함포의 우세를 보여 주었다.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["알렉산드리아 협약", "85cb47b0"], "d": ["메흐메트 알리는 시리아, 아다나, 크레타, 헤자즈를 포기하고, 오스만 함대를 돌려주며, 술탄의 주권을 인정하는 데 동의했다. 그 대가로 이집트의 세습 총독직이 보장되었다.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["이집트군의 시리아·추쿠로바 철수", "719a28dc"], "d": ["9년에 걸친 점령이 끝났고, 이브라힘 파샤의 군대는 시나이를 거쳐 이집트로 돌아갔다. 지도에서 알레포에서 가자까지, 아다나에서 크레타까지 뻗은 넓은 지대는 다시 오스만의 직접 통치로 넘어간다. 같은 날짜에 상실한 다른 정착지: 우르파, 마라시, 타르수스, 안타키아, 칸디아(크레타), 하마, 다마스쿠스, 예루살렘, 야파, 나블루스.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["칙령: 이집트 총독직이 카발라 가문에 세습됨", "87b89ff8"], "d": ["술탄의 칙령은 총독직이 가문 안에서 아버지에게서 아들로 이어지는 것을 인정했다. 그 대신 군대 병력은 1만 8천 명으로 축소되었고, 조세는 이스탄불에 연계되었으며, 화폐 주조권과 조약 체결권은 폐지되었다. 이집트는 여전히 하나의 주로 남았지만, 이제는 별개 왕조의 나라였다. 헤자즈와 두 성지(하라마인)의 통치는 바브알리에 반환되었다. 같은 날짜에 종속 층에서 직접 통치 층으로 돌아간 다른 정착지: 메카, 메디나, 제다, 얀부.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["런던 해협 협약", "0e95a1ea"], "d": ["휜캬르 이스켈레시 조약을 대체한 이 협약은 평시에 해협이 모든 군함에 대해 폐쇄된다고 규정했다. 이로써 러시아가 홀로 얻었던 특권은 유럽의 공동 보장으로 바뀌었고, 해협 문제는 국제적 지위를 얻었다.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["이브라힘 파샤가 사실상 이집트 총독이 됨", "9e14f5d9"], "d": ["노쇠하여 정신 능력을 잃어 가던 메흐메트 알리를 대신하여 그의 아들 이브라힘 파샤가 총독직에 올랐다. 그러나 몇 달 뒤인 1848년 11월, 그는 아버지보다 먼저 세상을 떠났다.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["카발라 출신 메흐메트 알리 파샤의 죽음", "871310e0"], "d": ["카발라에서 태어나 이집트에 왕조를 세우고 제국을 두 차례나 벼랑 끝으로 몰아간 총독이 여든 살에 세상을 떠났다. 그가 세운 왕조는 1953년까지 이집트를 다스렸다. 국가는 그가 낸 상처를 유럽의 개입으로써만 아물게 할 수 있었음을 깨닫고, 탄지마트의 길로 나아갔다.", "c0877894"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["에르투으룰 가지의 죽음과 오스만 베이의 베이국 계승 — 쇠위트와 도마니치의 유산", "395fb9fa"], "d": ["TDV에 따르면 에르투으룰 가지는 680년(1281-82년)에 세상을 떠났다. 해당 항목은 1288년과 1289년이라는 날짜도 전해진다고 기록한다. 오스만 베이가 아버지에게서 물려받은 것은 정복한 도시가 아니라, 셀주크 술탄이 자기 변경 지대의 가장 전방에 정착시킨 에르투으룰에게 내려 준 두 곳의 할당지였다. 쇠위트의 겨울 목영지(유르틀루크)와 도마니치의 여름 목초지(야일라크)였다. 즉 이 베이국은 정복의 유산이 아니라 두 곳의 목초지 할당으로 출발한 것이며, 지도에서 이 두 곳은 '정복'이 아니라 '상속'으로 표시된다.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["시칠리아의 만종 — 앙주 가문이 시칠리아섬을 상실", "547db635"], "d": ["부활절 월요일 저녁 기도 시간에 팔레르모에서 앙주의 카를로 1세의 통치에 맞서 터진 봉기는 시칠리아섬을 앙주 가문에게서 떼어 냈다. 시칠리아 왕국은 둘로 갈라졌다. 섬은 아라곤으로 향했고, 앙주 가문은 나폴리를 중심으로 한 본토 왕국을 지켜 냈다. 아드리아해와 지중해에 있던 이 가문의 해외 영지도 이 왕국에 계속 속했다. 1267년부터 보유한 코르푸와 1270년대부터 장악한 두러스(두라초)는 나폴리 왕국의 일부로 존속했고, 알바니아 해안의 발로나, 카니나, 히마라 요새도 나폴리 중심의 왕국에 남았다(발로나의 사령관 존 오브 택시스는 1282년 내내 비잔티움에 저항했으며, 두러스, 발로나, 카니나는 아마도 1285년 초에 비잔티움으로 넘어갔을 것이다). 반면 몰타는 1284년에야 아라곤 세력의 손에 들어갔다.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["쿨라자히사르 습격 — 오스만 베이의 첫 군사 작전", "79b00b14"], "d": ["TDV 「오스만 1세」 항목: '이네괼 부근의 작은 쿨라자 성채를 약탈하고 불태웠다(684/1285).' 이것은 사료에서 연대를 확정할 수 있는 오스만 베이의 첫 군사 행동이다. 영구적인 정착지는 점령되지 않았고 성채는 약탈되고 불태워졌으므로, 정복이라기보다는 전형적인 변경 습격이다. 베이국 군사 활동의 출발점으로 간주된다.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["카라자히사르 정복 — 첫 도시 획득과 에스키셰히르 지배", "178ae619"], "d": ["TDV 「오스만 1세」 항목: 오스만 베이는 687년(1288년)에 '카라자히사르를 정복하여 에스키셰히르의 주인이 되었다'. 이것은 베이국의 첫 번째 실질적인 도시 획득이며, 전승에 따르면 오스만 베이는 이 성공으로 변경에서 산자크 베이 지위에 올랐다. 그의 이름으로 된 첫 금요 후트바가 카라자히사르에서 낭독되었고 이곳에 첫 카디가 임명되었다고 전해진다. TDV 「에스키셰히르」 항목은 오스만 전승이 1291년이라는 연도를 전하지만 그 정확성은 의심스럽다고 밝힌다.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["아크레가 맘루크에게 함락 — 시리아 해안에서 십자군의 일소: 시돈과 베이루트", "3ca7a464"], "d": ["오랫동안 예루살렘 십자군 왕국의 중심지였던 아크레는 맘루크의 술탄 알말리크 알아슈라프 칼릴에게 정복되었고, 팔레스타인에서 십자군의 지배는 끝났다. 아크레에서 철수한 성전 기사들은 시돈으로 피신했으나, 맘루크군이 접근하자 해상 성채를 버리고 키프로스로 달아났고, 도시는 같은 해 여름 맘루크에게 넘어갔다. 1197년부터 십자군의 수중에 있던 베이루트도 1291년 다마스쿠스 총독 산자르 알슈자이에게 점령되었다. 이로써 2세기에 걸친 십자군의 존재는 시리아-팔레스타인 해안에서 지워졌다.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["야간 습격으로 빌레지크와 야르히사르 정복", "f461b0af"], "d": ["TDV 「빌레지크」 항목: '빌레지크의 텍푸르를 포함한 이 지역의 다른 텍푸르들이 오스만 가지에 대한 암살을 꾸몄으나, 이 음모가 알려지자 오스만군은 기습으로 야르히사르와 빌레지크를 정복했다(1299).' 두 요새는 하나의 작전, 같은 야간 습격에서 점령되었다. 이 해는 오스만 국가의 건국 연도로 받아들여지는 전환점이다. 같은 날짜에 편입된 다른 곳: 이네괼.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["코윤히사르(바페우스) 전투 — 비잔티움군에 대한 첫 대승", "584a9512"], "d": ["TDV 「오스만 1세」 항목: 오스만 베이는 1302년 7월 27일 바페우스(코윤히사르)에서 비잔티움군과 싸워 이겼다. 이 승리는 오스만 베이를 한 지역의 변경 영주에서 왕조 창건자의 지위로 끌어올린 전환점이다. 전투 뒤 부르사 평원이 오스만의 통제 아래 들어갔고 이즈니크(니케아) 봉쇄가 시작되었다.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["딤보스 승리와 이어진 키테·울루바트 점령", "e168ab64"], "d": ["TDV 「오스만 1세」 항목: 702년(1303년)에 부르사, 케스텔, 키테, 아드라노스의 텍푸르들이 결성한 동맹이 딤보스 협곡에서 격파되었다. 적은 싸우면서 좁은 협곡까지 밀려났고, 케스텔의 텍푸르는 전장에서 죽었다. 승리 직후 키테와 울루바트 요새를 점령함으로써 부르사의 육상 연결이 끊기고 봉쇄가 강화되었다. 젊은 오르한도 이 전투에 참가했다.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["사카리아 원정: 레블레비지히사르, 레프케, 메케제, 게이베 점령", "a51ba4d3"], "d": ["TDV 「오스만 1세」 항목은 704년(1304년) 사카리아 원정의 순서를 이렇게 전한다. '레블레뷔지 성채에 이르자 텍푸르가 복종했다... 레프케에 도착했다... 메케제에 이르렀다... 게이베로 가서 비어 있는 성채를 차지했다.' 레프케는 사카리아 계곡에서 빌레지크로 열리는 관문이다. 이 한 번의 원정으로 계곡을 따라 늘어선 요새의 사슬이 오스만의 통제 아래 들어감으로써 이즈니크 분지의 동쪽 측면이 막혔다.", "ae2866c2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["게이베 협곡 요새 정복: 카라체퓌시, 카라티긴, 압수", "76907c78"], "d": ["TDV 「오르한」 항목: 오르한은 705년(1305년) 사카리아 원정에서 '카라체퓌시(카토이키아), 이즈니크 앞의 카라티긴, 압수(힙수: 게이베 협곡에 있음) 요새를 정복했다'. 이 세 요새는 사카리아 계곡과 이즈니크 분지 사이의 통로를 막아 이즈니크로 오는 육상 지원을 완전히 끊었다. 게이베 협곡의 카라체퓌시와 압수에는 가지 압두라흐만이 배치되었고, 이제 도시는 굶주림으로써만 함락시킬 수 있게 되었다.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["아드라노스(오르하넬리) 원정 — 오스만 베이의 마지막 원정", "4811546c"], "d": ["TDV 「오르한」 항목은 1323년 가을의 아드라노스 요새 원정을 오스만 베이의 마지막 원정으로 기록한다. 아드라노스의 텍푸르는 20년 전 딤보스에서 오스만에 맞서 결성된 텍푸르 동맹의 일원이었으므로, 이번 원정은 그 빚을 청산하는 것이었다. 요새가 정복된 정확한 날짜는 알려져 있지 않으며, 작전은 오르한 베이가 이어서 수행했다.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["오스만 가지의 죽음과 오르한 베이의 베이국 계승", "021487cd"], "d": ["베이국에 이름을 준 오스만 가지는 아스포르차 하툰과 메케제의 와크프(기증 재산) 문서가 증언하듯이 724년(1324년)에 세상을 떠났다. 1305년부터 원정에서 군대를 이끌어 온 아들 오르한은 아버지가 죽자 어떤 왕위 다툼도 없이 베이국의 수장이 되었다. 창건 세대가 깃발을 동요 없이 넘겨준 것은, 변경 베이국에서 국가로 나아가는 길에서 왕조가 첫 번째 큰 시험을 평온하게 통과했음을 보여 준다.", "6f95e64a"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["펠레카논(말테페) 전투와 코자엘리 전역의 점령", "389e7bd4"], "d": ["TDV 「오르한」 항목: 전투 첫날 오르한 가지는 비잔티움군을 자기 쪽으로 끌어들이기 위해 300명의 부대를 보냈다. 둘째 날 파자를루가 지휘하는 부대가 평지로 내려오면서 전투가 확대되었고, 황제가 화살에 맞아 부상하자 비잔티움군은 공황에 빠졌다. 결과는 결정적이었다. '오르한은 코자엘리 전역을 장악했고, 이 승리 이후 이즈니크 주민에게는 아무런 희망도 남지 않았다.' 헤레케에서 위스퀴다르에 이르는 해안 읍들이 오스만의 지배 아래 들어갔고, 게브제가 이 지역의 중심지가 되었다. 이것은 콘스탄티노폴리스를 구하러 온 마지막 비잔티움 제국 군대였다.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["이즈니크(니케아)에 최초의 오스만 마드라사 설립", "c85fb625"], "d": ["오르한 베이는 이즈니크(니케아)를 점령한 직후 찬다를르 카라 할릴을 이곳의 카디로 임명했고, 바실리카 하나를 모스크로 바꾸고 그 곁에 이마레트(구휼 시설)와 마드라사를 지어 도시 정비를 시작했다. TDV의 「다부드 카이세리」 항목에 따르면 마드라사의 공사는 1336년에 완료되었고, 오르한 가지는 하루 30악체의 급료로 다부드 카이세리를 교수로 초빙했다. 이 마드라사는 오스만 학문 생활의 첫 제도적 발걸음이었다. 이로써 베이국은 정복의 힘에 더해 학문 전통까지 갖추게 되었다. 정복으로 얻은 비잔티움의 한 수도가 이슬람 학문의 중심지로 바뀐 것은, 정착 국가가 되려는 오스만의 포부를 보여 주는 첫 번째 구체적 징표였다.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["비잔티움이 조공국이 되다 — 이즈미트 포위와 조약", "0c1ec8d3"], "d": ["TDV 「오르한」 항목: 733년(1333년) 여름 오르한은 대군과 투석기로 이즈미트를 포위했고, 황제는 조약에 동의했다. 포위를 푸는 대가로 비잔티움은 오르한에게 매년 금화(히페르피론) 1만 2천 닢을 바치기로 했다. '이로써 오스만 아미르의 눈에 비잔티움은 조공을 바치는 나라의 처지로 떨어졌다.' 그 대신 오르한은 황제의 친구가 되고 비잔티움에 속한 도시들을 공격하지 않기로 했다. 한 변경 베이국이 동로마에 공납을 부과한 것은 세력 균형이 얼마나 뒤바뀌었는지를 선언한 것이었다.", "e2e3eeb4"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["카레시 베이국 병합: 발르케시르, 페르가몬, 비가, 에드레미트, 에르데크", "c7cb0511"], "d": ["TDV 「오르한」 항목(이날즉)은 병합을 735년(1334-35년)으로 본다. 데미르한 베이가 죽자 카레시의 가지들과 하즈 일베이는 두르순 베이를 왕위에 초청하고 오르한에게 도움을 청했다. 오르한은 먼저 발르케시르로 진군했다. 평화 협상에 나선 두르순 베이가 페르가몬 요새에서 날아온 화살에 맞아 죽자, 베이국 전체가 오스만 영토에 편입되었다. 같은 작전에서 키르마스티와 미할리치가 복종했고, 괼랴즈가 점령되었으며, 이전에 안전 보장(에만) 조건으로 남겨 두었던 울루바트가 완전히 장악되었다. 오르한은 카레시 산자크에 쉴레이만 파샤를 임명하고 비가를 변경 거점으로 삼았다. 이로써 루멜리아로 건너가기 위한 해양 인력이 확보되었다. 주: TDV의 「카레시오울라르」 항목은 같은 사건을 746년(1345년)으로 적고 있어, 이 백과사전은 내부적으로 서로 모순된다. 같은 날짜에 편입된 다른 곳: 차나칼레.", "f5ed82c2"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["오르한 가지가 제노바인에게 부여한 첫 카피툴레이션", "e64cb196"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["갈리폴리 점령 — 루멜리아의 영구 교두보", "ba51a160"], "d": ["1349-1352년 사이에 칸타쿠지노스의 동맹으로서 그 주변을 알게 된 오스만은 1354년 갈리폴리를 점령했다. 도시의 성벽을 무너뜨린 대지진이 기회를 만들어 주었다. 이로써 침페의 좁은 교두보는 해협의 루멜리아 쪽에 있는 진정한 거점으로 바뀌었고, 트라키아로 통하는 문이 활짝 열렸다. 갈리폴리는 1366년 사보이 십자군에게 빼앗기게 되지만, 1376년의 두 번째 정복으로 확정적으로 오스만의 지배 아래 들어간다. 같은 날짜에 편입된 다른 곳: 킬리트바히르.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["루멜리아의 정복자 쉴레이만 파샤의 죽음", "2dc98228"], "d": ["오르한 베이의 장남이자 루멜리아 정복의 설계자인 쉴레이만 파샤는 사료에 758년(1357년), 759년, 760년(1359년)으로 전해지는 날짜 가운데 가장 널리 받아들여지는 1357년 가을에 사냥 중 말에서 떨어져 세상을 떠났다. 1352-1354년의 도해를 통해 루멜리아에 오스만의 영구적인 존재를 세운 왕자의 죽음으로, 후계 순위는 동생 무라드에게 넘어갔다. 볼라이르에 묻힌 쉴레이만 파샤의 영묘는 유럽에서 가장 오래된 오스만 왕조의 기념물로 남았다.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["펜치크 법 — 예니체리 군단의 기초가 놓임", "e5877c2d"], "d": ["루멜리아 정복 이후 울레마였던 카라만 출신 카라 뤼스템의 건의로, 전쟁 포로의 5분의 1 또는 그에 해당하는 금액을 국가 몫으로 떼어 놓는 펜치크 제도가 시행되었다. 이 포로 중에서 선발된 이들을 튀르크 가정에서 길러 군에 편입시킴으로써, 술탄에게 직접 속한 상비 보병 부대, 즉 예니체리 군단의 핵심이 만들어졌다. 부족 기병에 의존하던 변경 베이국이 중앙군을 가진 국가로 바뀌는 과정은 이 제도에서 시작되었다.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["서트라키아로의 남하: 귀뮐지네 정복", "9ef69221"], "d": ["에디르네 점령 이후 마리차강 서쪽으로 향한 변경 부대는 가지 에브레노스 베이의 지휘 아래 서트라키아의 중심지 귀뮐지네(코모티니)를 점령했다. 이 도시는 에브레노스 베이가 마케도니아로 습격을 이어 가는 전진 사령부가 되었다. 이로써 에게해 연안에 이르는 트라키아 지역이 오스만의 통제 아래 들어갔고 테살로니키로 가는 길이 열렸다.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["바르나가 도브루자 공국에 넘어가 수도가 됨", "2bfe73f9"], "d": ["불가리아 차르국이 해체되어 가는 과정에서 흑해 연안의 바르나는 도브로티차가 세운 도브루자 공국에 편입되어 이 작은 국가의 수도가 되었다.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["플로브디프 서쪽: 타타르파자르즈으와 이흐티만의 편입", "1664d0e1"], "d": ["1372년 플로브디프(필리베)를 점령한 뒤, 마리차 계곡 상류 끝의 타타르파자르즈으와 소피아로 통하는 고개를 장악한 이흐티만이 오스만의 통치에 편입되었다. 치르멘 전투 이후 봉신이 된 현지 영주들의 수중에 있던 이 선은 직접 통치로 넘어감으로써 플로브디프-소피아 노선이 끊김 없이 이어졌다. 이 진출은 12년 뒤 소피아 정복에 이르는 길을 준비한 것이었다.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["사브즈 베이의 반란 — 왕자와 비잔티움 황태자의 공동 봉기", "75198c33"], "d": ["무라드 1세의 아들 사브즈 베이와 비잔티움 황제 요안니스 5세의 아들 안드로니코스 팔레올로고스는 1373년 5월 초 부르사와 콘스탄티노폴리스에서 동시에 각자의 아버지에 맞서 봉기했다. 두 왕조의 후계자를 결합한 이 동맹은 신속히 진압되었고, 사브즈 베이는 붙잡혀 눈이 멀게 된 뒤 처형되었다. 오스만 전승이 이 반란의 연도로 제시하는 787년(1385년)은 오류이다. 이 사건은 비잔티움이 오스만의 봉신이 된 시기 직후에 해당하며, 두 궁정이 얼마나 깊이 얽혀 있었는지를 보여 준다.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["스트리몬·메스타 계곡: 큐스텐딜, 페트리치, 네브로코프, 드라마의 편입", "8c0980c4"], "d": ["치르멘 승리 이후 오스만에 조공을 바치기 시작한 세르비아·불가리아 현지 영주들이 장악하고 있던 스트리몬과 메스타 계곡은 변경 베이들의 진출로 오스만의 직접 통치 아래 들어갔다. 큐스텐딜, 페트리치, 네브로코프, 드라마가 편입되면서 마케도니아의 동쪽 절반이 열렸고, 테살로니키와 세레스는 포위망 안에 들어갔다. 지도에서 루멜리아가 남서쪽으로 확장된 것은 이 작전의 결과이다.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["에레트나 베이국의 종말과 카디 부르하네딘의 국가의 건립", "60dcaf57"], "d": ["1335년 일 칸국의 총독직에서 생겨나 시바스와 카이세리를 중심으로 한 중부 아나톨리아를 46년간 다스린 에레트나 왕조는 궁정 내분으로 와해되었다. 1378년 5월 재상이 된 카디 부르하네딘은 경쟁자 클르차르슬란과 하즈 샤드겔디를 제거한 뒤, 1381년 가을에 술탄을 칭하여 베이국을 끝내고 자기 이름으로 불리는 국가를 세웠다. 이렇게 오스만의 동쪽 이웃은 주인이 바뀌었고, 시바스-카이세리 선은 이후 17년 동안 카디 부르하네딘의 손에 남게 된다.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["티무르의 헤라트 점령: 카르트 왕조의 종말과 호라산의 티무르 제국 편입", "15f6019e"], "d": ["1380년 호라산은 사르바다르, 카르트, 무자파르 왕조 사이의 투쟁으로 분열되어 있었다. 티무르는 아들 미란 샤를 이 지역에 보낸 뒤 자신은 헤라트로 진군하여 한동안 포위한 끝에, 카르트의 말릭 기야스 앗딘 피르 알리에게서 도시를 넘겨받았다. 그가 떠난 뒤 일어난 반란은 미란 샤에 의해 피로 진압되었고, 1255년부터 헤라트를 다스려 온 카르트 왕조는 끝을 맞았다. 이때 마슈하드에서 니샤푸르에 이르는 호라산 전역이 티무르의 통치 아래 들어갔다.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["마케도니아 내륙으로의 진출: 모나스티르와 오흐리드 정복", "63bb7838"], "d": ["에그나티아 가도에 있는 모나스티르(비톨라)와 호숫가의 오흐리드는 알바니아 방면으로의 습격 중에 오스만의 통치 아래 들어갔다. 두 곳 모두 아드리아해로 뻗은 길의 요충지였고, 오흐리드는 또한 발칸에서 가장 오래된 정교회 대주교구의 중심지였다. TDV는 오흐리드의 정복 연도에 대해 확실한 정보가 없으며, 787년(1385년)과 크랄례비치 마르코가 죽은 뒤인 797년(1395년)이 제시되었다고 기록한다. 여기서는 1385년을 기준으로 삼았다. 모나스티르는 이후 수 세기 동안 루멜리아에서 가장 중요한 군사 중심지 중 하나가 된다.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["사브라 전투 — 알바니아의 문이 열림", "dda6671b"], "d": ["발시치 가문에게 궁지에 몰린 알바니아 영주 카를로 토피아의 구원 요청을 받은 오스만군은 사브라 평원에서 발샤 2세의 군대를 격파했고, 발샤는 전장에서 목숨을 잃었다. 토착 영주의 초청으로 치른 이 전투는 오스만에게 아드리아해 연안까지 뻗은 알바니아 땅에서 첫 번째 지속적인 영향력을 안겨 주었다. 지역 영주들의 반목을 기회로 삼는 이 정책은 다음 한 세기 내내 발칸 정복의 변함없는 방식이 된다.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["티무르의 '3년 원정': 아제르바이잔과 북부 이란의 정복", "2a98ec51"], "d": ["호라산 원정 중에 이란의 분열된 상태를 가까이에서 본 티무르는 788년(1386년)에 서쪽으로 진군했다. '3년 원정'이라 불리는 1386-1388년의 작전에서 그는 마잔다란, 로레스탄, 조지아를 거쳐 아제르바이잔으로 넘어가 카라바흐에 이르렀다. 타브리즈, 아르다빌, 우르미아, 나흐츠반이 티무르의 통치 아래 들어갔다. 북부 이란과 아제르바이잔을 장악한 것은, 일찍이 주치 울루스와 일 칸국 사이에서 그랬던 것처럼, 금장 칸국(킵차크 칸국)과의 긴 대립이 시작되는 계기이기도 했다.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["프렌크야즈스 전투와 코니아 포위 — 첫 번째 카라만 원정", "af4e5d77"], "d": ["자신의 사위임에도 불구하고 서부 아나톨리아에서의 오스만 확장을 못마땅해하던 카라만 가문의 알라에딘 알리 베이를 치러 무라드 1세가 직접 원정에 나섰다. 프렌크 야즈스라고 불리는 곳에서 벌어진 전투에서 훈련되고 경험 많은 오스만군은 카라만 병력을 격파했다. 이어 코니아 성채가 포위되었으나, 알라에딘 베이가 용서를 받으면서 베이국은 완전히 폐지되지 않았다. 이 원정은 한 세기 동안 이어지다가 1468년의 최종 병합으로 끝나는, 오스만과 카라만 사이 긴 대결의 서막이다.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["갈리폴리 조선소 설립 — 오스만 해군의 탄생", "47546241"], "d": ["오스만 국가 최초의 체계를 갖춘 조선소는 1390년 이을드름 바예지드가 갈리폴리에, 비잔티움이 남긴 조선소 자리에 세웠다. 서부 아나톨리아 베이국들의 해양 유산을 이어받은 오스만은 이로써 처음으로 자기 배를 스스로 건조하는 해양 세력이 되었다. 다르다넬스 해협의 요충지에 자리한 이 조선소는 콘스탄티노폴리스 포위에서 에게해 원정에 이르기까지 한 세기 반 동안 오스만 해군의 주 기지 역할을 했다.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["하미드 지방이 오스만에 편입: 이스파르타, 부르두르, 울루보를루, 에이르디르", "e3da7de5"], "d": ["카라만오을루 알라에딘 베이가 하미드 지방을 공격하고 주민들이 탄원하자 원정에 나선 이을드름 바예지드는 하미드 왕조의 남은 영토를 모두 장악하고 그 통치를 아들 이사 첼레비에게 맡겼다.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["무자파르 왕조의 종말: 샤 만수르가 시라즈 앞에서 패배", "5fd14eb8"], "d": ["1318년부터 야즈드, 파르스, 이스파한, 케르만을 다스려 온 무자파르 왕조의 마지막 강력한 군주 샤 만수르는 친족들과 손잡고 티무르에 맞서 일어섰다. 시라즈 부근의 전투에서 아미르 한 명이 적편으로 넘어가면서 병력 대부분을 잃었고, 패배하여 살해되었다. 이후 티무르가 왕조 구성원 전원도 처형하게 함으로써 무자파르의 지배는 끝났고, 파르스와 케르만은 티무르의 통치에 편입되었다.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["아마시아가 오스만 영토에 편입", "fe2860cf"], "d": ["이을드름 바예지드의 중부 아나톨리아 작전 중에 포위된 아마시아의 아미르는 도시를 오스만에게 넘겼고, 바예지드는 1393년 도시에 입성했다. 술탄은 이곳의 통치를 아들 메흐메드 첼레비에게 맡겼고, 왕자의 산자크가 된 아마시아는 이후 오스만 왕조의 가장 중요한 수련장 가운데 하나가 되었다. 같은 날짜에 상실한 다른 정착지: 라디크(아마시아), 메르지폰, 오스만즈크, 초룸. 이 선택은 훗날의 공위 시대에 결정적인 의미를 갖게 되며, 첼레비 메흐메드는 바로 이 아마시아를 기반으로 국가 재통일 투쟁을 벌이게 된다.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["티무르의 바그다드 점령 — 잘라이르 세력이 아나톨리아로 도주", "4d5602b3"], "d": ["티무르는 긴 포위 끝에 바그다드를 점령했다. 도시의 지배자인 잘라이르 왕조의 술탄 아흐마드는 서쪽으로 달아나 처음에는 맘루크에게, 이어서 오스만 궁정에 몸을 의탁했다. 이로써 티무르의 서방 확장은 처음으로 오스만의 세력권과 직접 맞닿았다. 두 군주 사이 적대의 첫 고리는 여기서 시작된다.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["흑해 연안의 바르나 점령", "a84b2abf"], "d": ["다뉴브강과 흑해 사이에 있는 불가리아 차르국의 영토가 압박을 받는 가운데, 해안 최대의 항구인 바르나가 오스만의 통치 아래 들어갔다. 이 항구를 점령함으로써 도브루자 방면으로의 진출로가 열렸고, 오스만은 흑해 서안에서 처음으로 큰 부두를 얻었다. 바르나는 51년 뒤인 1444년 십자군이 섬멸되는 승리의 무대가 되기도 한다.", "2e425501"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["카디 부르하네딘의 국가의 멸망", "b13391e3"], "d": ["백양 왕조의 군주 카라윌뤼크 오스만 베이에게 포로가 된 카디 부르하네딘은 시바스를 넘겨주는 대가로 풀어 달라고 제안했으나, 시민들이 저항했고 술탄은 성벽 앞에서 처형되었다. 시바스의 유력자들은 그의 아들 알라에딘 알리 첼레비를 수장에 앉혔으나, 백양 왕조의 압박에 직면하자 이을드름 바예지드에게 도움을 청했다. 쉴레이만 첼레비가 지휘하는 오스만군은 카라윌뤼크를 격파하고 도시를 장악했다. 이로써 카디 부르하네딘의 국가는 역사 속으로 사라졌고, 시바스, 토카트, 닉사르, 카이세리가 오스만 영토에 편입되었다. 같은 날짜에 편입된 다른 곳: 크르셰히르, 초룸.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["티무르와의 정면 대결: 망명자 송환 거부", "33790bc8"], "d": ["티무르의 압박에 잘라이르 왕조의 술탄 아흐마드와 흑양 왕조의 지도자 카라 유수프는 오스만 영토로 피신했다. 티무르는 이 두 망명자의 송환을 요구했으나 이을드름 바예지드는 거절했다. 그러자 두 군주 사이에 서로 심한 모욕이 담긴 서한이 오가기 시작했다. 전쟁의 이념적 토대는 병사 한 명도 움직이기 전에 이 서신 왕래로 마련되었다.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["부르사의 이을드름 다뤼쉬시파 — 최초의 오스만 병원", "5f0dc59a"], "d": ["이을드름 바예지드는 부르사에 장대한 울루 자미(대모스크)를 짓던 시기에 도시에 다뤼쉬시파(병원)도 세워 주었다. 이는 이마레트, 마드라사, 한(상인 숙소), 다리로 이루어진 광범위한 자선 사업 가운데 의학에 해당하는 부분이었다. 국가가 세운 첫 병원인 이 건물은 의사를 양성하는 의학교 역할도 하며 오스만 보건 기관의 모범을 정했다. 앙카라의 참사가 있기 불과 2년 전에 완공된 이 건축물은 부르사를 제국의 수도로 바꾸려던 이을드름의 구상의 마지막 고리 중 하나이다.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["티무르가 시바스를 초토화", "f4d79de6"], "d": ["백양 왕조의 카라윌뤼크 오스만 베이와 에르진잔의 아미르 무타하르텐의 안내를 받아 시바스로 진군한 티무르는 18일 동안 도시를 포위했고, 누구의 피도 흘리지 않겠다고 약속하여 항복을 받은 뒤 대학살을 저질렀다. 그는 방어자들을 해자에 몰아넣고 산 채로 묻게 했다. 성벽을 비롯한 도시의 주요 건축물이 파괴되었고, 시바스의 인구는 붕괴했다. 이것은 앙카라 전투 2년 전에 티무르가 오스만 영토에 가한 첫 번째 큰 타격이다.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["이을드름 바예지드가 에르진잔과 케마흐를 탈환", "7047ca08"], "d": ["티무르가 시리아 원정에 나선 틈을 타 이을드름 바예지드는 티무르에게 신종하던 에르진잔의 아미르 무타하르텐에게서 에르진잔과 케마흐를 빼앗았다. 바예지드는 시바스의 파괴 때는 개입하지 않았지만, 이 조치는 동부 아나톨리아에서 티무르의 세력권에 직접 도전하는 것이었다. 이후 두 군주의 관계는 돌이킬 수 없게 되었다.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["티무르가 타브리즈에서 보낸 최후통첩 — 네 가지 조건", "3e1ac50e"], "d": ["티무르는 타브리즈에서 보낸 사절을 통해 네 가지 조건을 통고했다. 케마흐를 무타하르텐에게 반환할 것, 아나톨리아의 베이들에게서 빼앗은 땅을 원주인에게 돌려줄 것, 오스만 왕자 한 명을 인질로 보내고 쿨라(관모)와 허리띠를 신종의 표지로 받아들일 것, 그리고 카라 유수프를 넘길 것이었다. 바예지드는 이 중 어느 것도 받아들이지 않았다. 대신들의 간청과 무타하르텐의 중재에도 불구하고 협상은 결렬되었다. 티무르는 중국 원정에 나서기 전에 아나톨리아 문제를 완전히 마무리하기로 결심하고 있었다.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["사루한 왕조의 부활 — 마니사가 오스만에서 이탈", "ac747b05"], "d": ["앙카라 패전 3주 뒤, 티무르의 지원으로 오르한 베이가 베이국의 수장이 되었고 사루한 지방은 다시 독립했다. 마니사를 중심으로 한 이 지역은 1390년 오스만에 병합된 지 12년 만에 지도상의 오스만 영역에서 빠졌다. 이것은 베이국들을 부활시키는 티무르 정책 가운데 날짜가 확실히 알려진 초기 적용 사례의 하나이다.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["에미르 쉴레이만이 국고를 가지고 루멜리아로 도주", "0a2b7363"], "d": ["에미르 쉴레이만은 부르사의 국고, 문서고, 가족과 형제들을 데리고 겜리크에서 배를 타고 귀젤제히사르(아나돌루히사르)로 건너간 뒤, 거기서 갈리폴리에 이르러 에디르네에서 자신의 통치를 선포했다. 국가의 문서고와 국고가 루멜리아로 옮겨진 것은 오스만의 무게중심이 한 세대 동안 발칸으로 옮겨 가는 시작이었다. 지도에서 루멜리아는 이 날짜부터 에미르 쉴레이만 고유의 색으로 그려진다.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["티무르가 아나톨리아 베이국들을 부활시킴 — 튀르크 통일의 해체", "15187774"], "d": ["앙카라 승리 뒤 티무르는 자기 곁에 있던 베이들에게 옛 영토를 돌려주었다. 카라만오을루 메흐메드와 알리 베이에게는 카라만 지방과 함께 카이세리, 크르셰히르, 시브리히사르, 베이셰히르가, 게르미얀오을루 야쿠브 베이 2세에게는 퀴타히아와 게르미얀 지방이, 잔다르오을루 이스펜디야르 베이에게는 카스타모누-시노프 선에 더하여 창크르와 칼레지크가 주어졌다. 아이든, 멘테셰, 테케 지방도 옛 왕조에게 돌아갔다. 이을드름 바예지드가 10년에 걸쳐 세운 아나톨리아 튀르크의 통일은 한 번의 여름 사이에 무너졌고, 지도에서 이 베이국들은 다시 각자의 색으로 나타난다. 같은 과정에서 주인이 바뀐 다른 정착지: 악사라이, 데니즐리, 에렐리(코니아), 에르메네크, 으르근, 카라프나르, 카이세리, 코니아, 크르셰히르, 퀴타히아, 시브리히사르, 쇠케.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["티무르가 성 요한 기사단으로부터 이즈미르를 점령", "66dd1dd4"], "d": ["퀴타히아, 데니즐리, 아이든, 아야술루크, 티레를 거쳐 서쪽으로 내려온 티무르는 1344년부터 기독교도의 수중에 있던 해안의 이즈미르를 포위하여 점령했다. 이을드름 바예지드가 여러 해 동안 점령하지 못했던 이 요새를 단기간에 함락시킨 티무르는 주변 요새들도 차지한 뒤, 아이든 지방을 옛 주인에게 맡기고 동쪽으로 돌아갔다. 이후 도시는 아이든오을루 주네이드 베이의 통치 아래 들어갔다.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["이사 첼레비의 부르사 장악 — 아나톨리아 분할 몫의 탄생", "955128c1"], "d": ["앙카라 패전 뒤 카레시 방면으로 물러났던 이사 첼레비는 티무르가 이즈미르에 있는 동안 부르사를 장악했다. 티무르의 병사들에게 약탈당하고 불탄 옛 수도에서 그는 자신의 통치를 선포하고 자기 이름으로 화폐를 주조하게 했다. 1403년 1월 그는 아나톨리아에서 '튀르크인의 군주'라는 칭호로 인정받고 있었다. 지도에서 마르마라해의 아시아 쪽 해안을 따라 뻗은 이 몫은 이사 첼레비 고유의 색으로 보인다.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["티무르의 아나톨리아 철수", "93a98839"], "d": ["이을드름 바예지드가 아크셰히르에서 죽었다는 소식을 들은 티무르는 아나톨리아에서의 일이 끝났다고 여기고 동쪽으로 향했다. 그의 뒤에는 그에게 충성을 맹세한 베이국들과 서로 맞붙게 된 오스만 왕자들이 남았다. 시바스와 같은 몇몇 도시는 메지드 베이 같은 티무르 휘하의 아미르들 손에 맡겨졌다. 티무르는 다시는 아나톨리아로 돌아오지 않았지만, 그가 세운 이 분열된 질서는 10년 동안 지속되었다.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["에미르 쉴레이만이 아나톨리아로 건너감: 부르사가 그의 손에", "9b27aa5f"], "d": ["이사 첼레비의 패배 소식을 들은 에미르 쉴레이만은 찬다를르 알리 파샤와 함께 강력한 군대를 이끌고 아나톨리아로 건너가 부르사를 장악했다. 1404년 3월의 기록은 흑해 연안의 에렐리(카라데니즈 에렐리)도 그의 통치 아래 있었음을 보여 준다. 짧은 기간에 루멜리아와 아나톨리아 대부분을 장악한 쉴레이만에게 첼레비 메흐메드는 맞서지 못했다. 같은 과정에서 첼레비 메흐메드에게서 에미르 쉴레이만에게 넘어간 다른 정착지: 아크야즈, 아나돌루 히사르, 압수(힙수), 아드라노스(오르하넬리), 아크히사르(파무코바), 아르무틀루, 아이도스 성, 아이발륵, 발르케시르, 베흐람칼레(아소스), 페르가몬, 베이코즈, 비가. 지도에서는 이 날짜부터 첼레비 메흐메드가 부르사를 탈환할 때(1410년)까지 해협 양안이 한 가지 색, 즉 에미르 쉴레이만의 몫으로 보인다.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["예니셰히르 평원 전투 — 첼레비 메흐메드가 아마시아로 후퇴", "f1568288"], "d": ["부르사와 앙카라를 잃은 첼레비 메흐메드는 예니셰히르 평원에서 에미르 쉴레이만에게 패하여 서부 아나톨리아에서 얻은 것을 모두 잃고, 토카트-아마시아 거점으로 물러났다. 이 패배 이후 그는 직접 충돌을 피하면서 아나톨리아 내륙에서 권위를 다지는 데 힘썼다. 공위 시대(페트레트기)의 가장 긴 정적 국면은 이렇게 시작되었다.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["에미르 쉴레이만이 첼레비 메흐메드에게서 앙카라를 빼앗음", "d6a2acd6"], "d": ["티무르가 아나톨리아에서 철수한 뒤 첼레비 메흐메드의 손에 남아 있던 앙카라를 1406년 에미르 쉴레이만이 포위했다. 요새 수비대장 야쿠브 베이는 한동안 버텼으나, 대재상 찬다를르 알리 파샤의 계략에 걸려 요새를 쉴레이만에게 넘겼다. 이에 첼레비 메흐메드는 카라만 가문의 메흐메드 베이와 협정을 맺고 쉴레이만에 맞서 움직였다.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["첼레비 메흐메드가 티무르 휘하의 메지드 베이에게서 시바스를 탈환", "90079b0c"], "d": ["티무르의 침입 이후 시바스의 통치는 티무르에게 신종한 메지드 베이에게 맡겨져 있었다. 아마시아에 있던 첼레비 메흐메드는 도시를 점령하도록 사령관 바예지드 파샤를 보냈고, 격렬한 저항 끝에 시바스는 두 번째로 오스만 왕조의 손에 들어왔다. 이로써 메흐메드의 몫은 앙카라 전투 6년 뒤 동쪽에서 옛 국경에 이르렀다.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["아르투크 왕조의 종말: 마르딘이 흑양 왕조에게 넘어감", "15b06f33"], "d": ["1106년부터 마르딘을 다스려 온, 왕조에서 가장 오래 존속한 분파인 아르투크 가문은 백양 왕조의 압박을 견디지 못했다. 도시를 지킬 수 없음을 깨달은 말릭 아흐메드는 흑양 왕조의 군주 카라 유수프와 합의하여 마르딘을 그에게 넘겼다. 이로써 3세기가 넘는 아르투크의 지배가 끝났고, 마르딘과 그 주변은 한 세기 뒤 오스만에 넘어갈 때까지 흑양 왕조와 백양 왕조 간 투쟁의 무대가 되었다.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["얌볼 전투 — 무사 첼레비가 에디르네에 입성", "8f978408"], "d": ["왈라키아를 거쳐 루멜리아로 건너간 무사 첼레비는 왈라키아와 세르비아의 지원을 받아 얌볼에서 에미르 쉴레이만의 군대를 격파하고 에디르네에 입성했다. 공위 시대에 루멜리아가 에미르 쉴레이만의 손에서 벗어난 것은 이때가 처음이었다. 그러나 그의 지배는 오래가지 못했고, 4개월 뒤 코스미디온에서 패하여 발칸 내륙으로 물러나게 된다.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["인제이즈 전투 — 첼레비 메흐메드의 루멜리아 첫 패배", "3c35cd43"], "d": ["비잔티움의 배를 타고 루멜리아로 건너간 첼레비 메흐메드는 인제이즈에서 무사 첼레비와 전투를 벌였다. 무사는 휘하의 예니체리 7천 명으로 메흐메드를 격파했고, 메흐메드는 아나톨리아로 돌아갈 수밖에 없었다. 이 패배로 메흐메드는 직접 전투 대신 루멜리아의 변경 베이들과 세르비아 전제공국을 자기편으로 끌어들이는 전략으로 선회했다. 9개월 뒤 차무르루 승리의 토대는 이 외교를 통해 마련되었다.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["코니아 포위와 카라만 왕조와의 조약 — 하미드 지방, 사이드 지방, 베이셰히르, 세이디셰히르, 아크셰히르 탈환", "0996257e"], "d": ["공위 시대에 오스만 영토를 공격하고 부르사를 포위하여 불태운 카라만 왕조에 맞서 첼레비 메흐메드는 대원정을 일으켜 818년 무하람 월에 코니아를 포위했다. 카라만의 메흐메드 베이 2세는 화평을 청할 수밖에 없었다. 조약의 결과 하미드 지방(이스파르타 일대)과 사이드 지방이 다시 오스만 영토에 편입되었고, 베이셰히르, 세이디셰히르, 아크셰히르도 반환되었다. 티무르가 1402년에 카라만 왕조에게 주었던 시브리히사르도 오스만에게 돌아왔다. 앙카라 전투로 흩어진 아나톨리아의 통일이 다시 기워지기 시작한 이 원정은 첼레비 메흐메드가 '제2의 창건자'로 평가받는 구체적 근거 가운데 하나이다.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["아이든오을루 주네이드 베이에게서 이즈미르를 점령", "2377ca51"], "d": ["공위 시대 내내 왕자들 사이에서 끊임없이 편을 바꾸던 아이든오을루 주네이드 베이의 중심지 이즈미르는 열흘간의 포위 끝에 첼레비 메흐메드에게 점령되었다. 주네이드는 사면을 받고 니코폴리스 산자크 베이로 파견되었다. 티무르가 1402년 아이든 왕조에 돌려주었던 도시는 이렇게 13년 만에 오스만에게 돌아왔다. 주네이드는 1422년에 다시 도시를 장악하게 되며, 이 문제는 1424-1426년에 가서야 무라드 2세에 의해 종결된다.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["토를라크 케말의 처형 — 사루한은 확정적으로 오스만의 땅", "8a09dbf1"], "d": ["셰이크 베드레딘 운동의 서부 아나톨리아 지부를 이끌던 토를라크 케말은 마니사 지방에서 패배하여 처형되었다. 이후 사루한 지역은 확정적으로 오스만의 통제 아래 들어갔고, 1402년 티무르가 부활시킨 베이국은 역사 속으로 사라졌다. 이로써 서부 아나톨리아에 남아 있던 공위 시대의 마지막 정치적 잔재가 정리되었다.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["발로나, 베라트, 카니나 정복", "1e1949b8"], "d": ["1417년 오스만은 아드리아해 연안의 발로나(아블로냐)를 내륙의 베라트 시 및 카니나 요새와 함께 자기 지배 아래 두었다. 1년 뒤 이 도시를 되찾으려던 베네치아의 시도는 실패했고, 이곳에 산자크 조직이 세워지면서 오스만의 권위가 확고해졌다. 발로나 점령으로 오스만은 처음으로 아드리아해에 직접 항구를 갖게 되었고, 이탈리아를 마주 보는 해외 진출의 발판을 얻었다.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["중부 아나톨리아의 탈환: 카이세리와 크르셰히르", "204eacb3"], "d": ["공위 시대에 카라만 왕조의 손에 넘어갔던 중부 아나톨리아의 도시들은 첼레비 메흐메드가 국가를 다시 수습하는 원정을 벌이는 동안 오스만의 통치로 돌아왔다. 카이세리와 크르셰히르가 편입되면서 앙카라 전투에서 잃었던 크즐으르마크강 유역이 대부분 회복되었다. 이 진출은 4년 전 코니아 포위로 시작된 동방 지향 정책의 연장이다.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["맘루크가 카이세리를 둘카디르의 나시루딘 무함마드에게 줌", "aad4b00c"], "d": ["카라만오을루 메흐메드 베이를 치러 원정에 나선 맘루크 군대는 카이세리를 점령했고, 맘루크 사령관은 도시와 그 주변을 둘카디르의 나시루딘 무함마드에게 맡기고 본국으로 돌아갔다.", "8cd84dc4"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["테케 왕조의 완전한 청산: 안탈리아 점령", "e65565b2"], "d": ["앙카라 전투 이후 티무르의 부활 조치로 다시 세워졌던 테케 베이국은 함자 베이가 이끄는 오스만군이 안탈리아를 포위하면서 끝났다. 베이국의 마지막 주요 인물인 오스만 첼레비는 제거되었다. 이로써 지중해 연안의 테케 지방은 21년간의 분리 끝에 확정적으로 오스만에 편입되었다. 이 베이국은 하미드 왕조에서 갈라져 나온 분파로서 1321년부터 안탈리아를 다스려 왔다.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["투라한 베이의 모레아 원정과 헥사밀리온 성벽의 파괴", "c6c2706d"], "d": ["비잔티움이 왕위를 다투던 경쟁자 무스타파 첼레비를 지원하자 무라드 2세는 투라한 베이를 모레아로 보냈다. 투라한 베이는 코린트 지협을 끝에서 끝까지 막고 있던 헥사밀리온 성벽을 허물고 반도에 들어가 큰 파괴를 일으켰다. 평화는 성벽을 다시 쌓지 않고 연례 세금을 바친다는 조건으로 이루어졌다. 이렇게 모레아 전제공국은 군사적으로 무방비 상태가 되었고, 1460년의 최종 정복의 토대가 37년 앞서 마련되었다.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["아토스(아이나로즈) 수도원들이 오스만의 보호를 받게 됨", "562de5ea"], "d": ["테살로니키가 포위되어 있던 시기에, 할키디키의 동쪽 반도에 있는 아토스 수도원 공화국은 무라드 2세에게 보호를 요청하고 오스만의 지배를 받아들였다. 수도사들의 재산권과 예배의 권리가 보장되었고, 수도원들은 세금을 내는 대신 내정의 자유를 인정받았다. 이 체제는 오스만이 정교회 기관들과 맺은 보호 관계 가운데 가장 오래 지속된 사례가 되어 5세기 동안 이어졌다.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["타제딘 왕조 베이국 병합: 닉사르", "370ffd47"], "d": ["아마시아의 베일레르베이 요르귀치 파샤의 압박을 받은 타제딘오을루 휘사메딘 하산 베이는 830년(1427년)에 닉사르를 중심으로 한 자기 영지의 열쇠를 넘겨주었고, 그에게는 루멜리아의 산자크 하나가 주어졌다. 14세기 후반에 세워져 때로는 국경이 켈키트, 아마시아, 삼순, 오르두, 기레순까지 뻗었던 이 베이국은 이렇게 끝났다. 같은 해 하즈에미르 가문에 속한 땅도 조사·등록(타흐리르)되어 자니크 산자크에 편입되었으며, 흑해 중부의 베이국 시대는 막을 내렸다.", "06fa8222"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["마르딘이 흑양 왕조의 수비대장에게서 백양 왕조의 카라윌뤼크 오스만 베이에게 넘어감", "d82bc97f"], "d": ["카라 유수프가 1409년에 차지한 마르딘은 흑양 왕조가 총독들을 통해 다스렸다. 수비대장으로 남겨진 에미르 나시르는 835년(1432년)에 도시를 백양 왕조의 카라윌뤼크 오스만 베이에게 넘겼다. 백양 왕조의 통치는 16세기 초까지 지속되었다.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["카라만 왕조가 둘카디르에게서 카이세리를 빼앗음", "2b09e8e8"], "d": ["둘카디르에게 승리를 거둔 카라만의 베이는 카이세리, 위르귀프, 데벨리 카라히사르, 우치히사르를 자기 영토에 편입했다.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["부축테페 사건 — 최초의 예니체리 봉기와 무라드 2세의 복위", "6388dda1"], "d": ["에디르네에서 일어난 부축테페 사건은 역사상 알려진 최초의 예니체리 봉기로, 급료(울루페)를 반 악체 올려 달라는 요구로 시작되어 젊은 메흐메드 2세의 폐위로 끝났다. 무라드 2세는 850년 사파르 월 8일에 마니사에서 급히 길을 떠나 두 번째 치세를 시작했다. 이 사건은 카프쿨루(술탄 직속 상비군) 군단이 이제 왕위에 대해 발언권을 가진 세력이 되었음을 보여 주는 첫 징후였고, 정복자 술탄이 평생 예니체리를 경계하게 만들었다.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["이피로스 해안의 편입: 아르타와 프레베자", "796f7ecf"], "d": ["1430년 이오안니나가 항복한 지 19년 뒤, 이피로스 전제공국 해안부의 아르타와 프레베자도 오스만의 통치 아래 들어갔다. 이로써 이오니아해로 열린 암브라키아만이 통제 아래 놓였고 이오안니나의 해상 연결이 완성되었다. 프레베자는 90년 뒤 바르바로사의 유명한 승리에 이름을 주게 될 만의 요충지이다.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["무라드 2세의 죽음과 메흐메드 2세의 두 번째 즉위", "8f8256ad"], "d": ["아들의 결혼식 뒤에 병이 든 무라드 2세는 855년 무하람 월 1일(1451년 2월 3일)에 에디르네에서 세상을 떠났다. 열아홉 살의 메흐메드 2세는 855년 무하람 월 16일(1451년 2월 18일)에 두 번째로 오스만의 왕위에 올랐다. 이번에는 영구적이었다. 5년 전 부축테페에서 폐위되었던 젊은 군주의 복귀는, 2년 뒤 콘스탄티노폴리스 정복으로 영광을 얻고 오스만 베이국을 세계 제국으로 바꾸게 될 치세의 시작이다.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["오스만-크림 연합군의 첫 번째 카파 포위", "e346d163"], "d": ["1454년 6월 정복자 술탄 메흐메드와 합의한 크림 칸 하즈 기라이는 기병 7천 명으로 카파를 육지에서 포위했고, 50-60척의 갤리선으로 이루어진 오스만 함대도 앞바다에 진을 쳤다. 제노바령 카파는 조공을 바쳐 포위를 풀게 했고, 최종 정복은 21년 뒤인 1475년으로 미루어졌다. 이 첫 합동 작전은 훗날 카파의 최종 정복에서 반복될 오스만-크림 군사 협력의 첫 사례였다.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["북에게해 섬들의 점령: 보즈자아다(테네도스), 임브로스, 타소스", "76575895"], "d": ["콘스탄티노폴리스 정복 직후 정복자 술탄 메흐메드는 새 수도의 해로를 확보하기 위해 다르다넬스 해협의 에게해 쪽 어귀에 있는 섬들로 눈을 돌렸다. 테네도스(보즈자아다)와 임브로스는 비잔티움에게서, 타소스는 제노바계의 가틸루시오 가문에게서 빼앗았다. 해협의 양안을 잠그는 이 섬들은 이후 이스탄불의 식량 보급선과 방어선의 첫 고리가 되었다. 교황청과 베네치아 함대의 개입으로 한동안 지배권이 오락가락하다가 1459년에야 확정되었다.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["코소보 정복: 프리슈티나와 노비파자르의 점령", "d7ed2345"], "d": ["세르비아 전제공국을 향해 진군한 오스만군은 코소보 평원의 프리슈티나와 라슈카 지역의 중심지 노비파자르를 점령했다. 같은 작전에서 은광으로 유명한 노보브르도도 점령되었다. 이로써 세르비아의 남쪽 절반은 오스만의 직접 통치에 편입되었고, 스메데레보의 전제공국은 중심 영토로부터 단절되었다. 이 정복은 4년 뒤 세르비아의 완전한 병합에 이르는 길에서 결정적인 걸음이었다.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["이펙(페치)이 오스만의 통치 아래로 — 두카긴 산자크의 중심지 중 하나", "19511588"], "d": ["1455년 정복자 술탄 메흐메드의 세르비아 원정 직후, 세르비아 총대주교구의 중심지 이펙은 오스만의 통치로 넘어갔다. 오스만 사료에는 이 이행에 관한 기록이 없다. 이 읍은 시간이 지나면서 작은 무슬림 읍이 되었고, 두카긴 산자크에서 산자크 베이의 거처 가운데 하나가 되었다.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["에네즈와 사모트라키섬 정복 — 서트라키아 해안의 완성", "106e723b"], "d": ["마리차강이 바다로 흘러드는 곳에 있는 에네즈(아이노스)는 80년 동안 이곳을 장악해 온 제노바계 가틸루시오 가문에게서 빼앗았고, 여기에 속한 사모트라키섬도 같은 작전에서 점령되었다. 에네즈가 함락되면서 서트라키아의 해안 지대는 테살로니키에서 갈리폴리까지 끊김 없는 오스만 영토가 되었다. 가틸루시오 가문의 손에는 레스보스(미딜리)만 남았는데, 이 섬도 6년 뒤에 점령된다.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["베오그라드 포위의 실패", "3d53a604"], "d": ["정복자 술탄 메흐메드는 콘스탄티노폴리스 정복 이후, 중부 유럽의 관문으로 여겨지던 베오그라드를 포위했다. 그러나 야노시 후냐디가 다뉴브강을 통해 데려온 증원군과 십자군 설교자 카피스트라노가 모은 의용병이 요새의 함락을 막았다. 술탄은 포위 중에 몸소 용맹을 보였으나 부상을 입고 철수해야 했다. 이 실패로 헝가리 국경은 65년 동안 오스만의 진출에 닫히게 되었고, 베오그라드는 1521년에야 카누니 술탄 쉴레이만에게 점령된다.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["북부 모레아 정복: 발랴바드라(파트라스)", "c08a8509"], "d": ["세르비아 병합과 같은 시기에 모레아 전제공국으로 향한 정복자 술탄 메흐메드의 군대는 반도 북서부의 발랴바드라(파트라스)를 점령했다. 코린트만 어귀를 장악한 이 항구는 육로로 모레아에 들어가는 관문이었으며, 그 점령은 2년 뒤 최종 정복의 토대를 마련했다. 이 도시는 비잔티움 전제공들이 라틴 세계와 연결을 맺던 마지막 큰 부두였다.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["흑해 서부 해안의 점령: 아마스라", "f43608fc"], "d": ["흑해 서부에 있던 제노바의 요새화된 식민지 아마스라는 정복자 술탄 메흐메드의 함대와 육군의 합동 압박에 저항 없이 항복했다. 바르튼-종굴다크 해안의 이 항구는 잔다르 왕조와 오스만 영토 사이에 라틴인의 고립 지대로 남아 있었는데, 이 점령으로 해안이 하나로 이어졌다. 아마스라의 함락은 2년 뒤(1461년) 시노프와 트라브존을 겨냥한 대규모 흑해 원정의 첫걸음이었다.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["레스보스(미딜리)섬 정복", "fe17aeba"], "d": ["정복자 술탄 메흐메드가 이끄는 오스만군은 866년 둘힛자 월에, 짧지만 격렬한 포위 끝에 제노바계 가틸루시오 가문에게서 레스보스를 빼앗아 병합했다. 북에게해 최대의 섬이 함락되면서 이 지역에서 제노바의 마지막 주요 거점도 청산되었다. 이 섬은 아나톨리아 해안과 가깝다는 점에서 이후 오스만 해군의 전초 기지 역할을 했고, 바르바로사 형제가 성장한 곳으로 해양사에도 이름을 남기게 된다.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["16년에 걸친 오스만-베네치아 전쟁의 시작", "563ddb68"], "d": ["베네치아인들은 모레아와 에게해에서 오스만의 진출을 저지하기 위해 카라만 및 백양 왕조의 통치자들과 동맹을 맺고 1463년에 전쟁을 시작했다. 동쪽의 우준 하산, 서쪽의 베네치아, 그 사이의 카라만으로 짜인 이 포위 전략은 정복자 술탄이 여러 전선에서 동시에 싸우도록 강요했다. 16년 동안 이어진 이 투쟁은 오틀루크벨리에서 알바니아 원정에 이르기까지 이 시기의 모든 대규모 작전을 포괄하며, 1479년 이스탄불 조약으로야 끝난다.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["헤르체고비나 대부분의 정복: 트레비네와 모스타르", "f54c0100"], "d": ["보스니아에서 분리된 통치를 세운 헤르체고비나 공작 스테판 부크치치 코사차의 영토는 보스니아 왕국이 멸망한 지 3년 뒤에 대부분 오스만의 통치로 넘어갔다. 남쪽에서는 1466년 트레비네가 \"헤르체고비나 지역의 거의 전부와 함께\" 점령되었다. 네레트바강 다리의 작은 두 요새 주변에 형성된 모스타르도 1466-1468년에 헤르체고비나의 중심지 블라가이가 정복되기 직전에 점령되었음에 틀림없다. 1468-1469년의 보스니아 요약 조사 대장(이즈말 타흐리르)에는 \"쾨프륄뤼 히사르\"(다리 있는 성채)라는 이름으로 기록되어 있다. 공작령의 남은 요새들까지 포함한 헤르체고비나 정복은 1483년에 완료되었다.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["제2차 알바니아 원정 — 정복자 술탄의 스칸데르베그 친정", "9cdd2bfa"], "d": ["4반세기를 넘긴 스칸데르베그의 저항을 꺾기 위해 정복자 술탄 메흐메드는 1466-1467년에 직접 지휘하는 대원정을 일으켰다. 오스만군은 아크차히사르(크루야)를 포위했고, 지역을 통제하기 위해 일바산(엘바산) 요새를 건설했다. 이 원정은 알바니아 저항의 기세를 꺾었으나 요새를 함락시키는 데에는 성공하지 못했다. 이 지역의 완전한 복속은 스칸데르베그가 죽은 뒤 10년이 걸린다.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["흑양 왕조 국가의 붕괴: 자한 샤의 피살", "30bc6358"], "d": ["우준 하산을 치러 나선 원정에서 겨울이 닥쳐 돌아오던 중 기습을 당한 흑양 왕조의 군주 자한 샤는 빙괼과 크으 사이에서 달아나다 살해되었다. 이 타격 이후 국가는 회복하지 못했고, 마지막 군주 하산 알리는 1469년 우준 하산의 아들 우우를루 메흐메드에게 사로잡혀 살해되었다. 이로써 동부 아나톨리아, 아제르바이잔, 이라크에서 한 세기 가까이 이어진 흑양 왕조의 지배는 백양 왕조에게 넘어갔다.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["스칸데르베그의 죽음 — 알바니아 저항의 소멸", "9158c35f"], "d": ["오스만 궁정에서 성장했으면서도 1444년 이즐라디 패주 이후 반란을 일으켜 4반세기 이상 알바니아에서 저항한 스칸데르베그는 피신해 있던 레저(레시)에서 죽었다. 무라드 2세와 정복자 술탄의 시대에 오스만 군대를 여러 차례 묶어 두었던 이 저항은 그의 죽음으로 중심 지도력을 잃었다. 교황청과 베네치아가 지원하던 알바니아 전선이 무너지면서, 오스만은 10년 안에 아크차히사르와 슈코더르를 점령하여 이 지역을 확정적으로 영토에 편입했다.", "5c7cffad"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["몰다비아의 라코바(바슬루이) 패주", "a1a74bf7"], "d": ["몰다비아의 공(보이보다) 슈테판 대공(슈테판 첼 마레)은 루멜리아 베일레르베이인 하듬 쉴레이만 파샤가 지휘하는 오스만군을 늪지대로 끌어들여 큰 패배를 안겼다. 정복자 술탄 시대의 가장 심각한 지상 패전 중 하나인 이 패주는 유럽에 큰 반향을 일으켰고, 슈테판에게 십자군 세계의 명성을 안겨 주었다. 술탄은 이듬해 보복을 위해 직접 원정에 나선다.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["아크데레(발레아 알버) 승리 — 몰다비아 원정", "45a66791"], "d": ["한 해 전 라코바 패주를 설욕하기 위해 직접 원정에 나선 정복자 술탄 메흐메드는 아크데레라 불리는 곳에서 오스만군으로 몰다비아군에 큰 패배를 안기고 공국의 중심지 수체아바에 입성했다. 그러나 요새들은 점령하지 못했고, 식량 부족, 예니체리 사이에 발생한 흑사병, 헝가리의 군사 준비 때문에 군대는 철수해야 했다. 몰다비아의 확고한 복속은 이후 몇 해를 거쳐 1484년 킬리(킬리아)와 아크케르만(체타테아 알버)을 점령하고서야 확보된다.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["아크차히사르(크루야) 정복과 알바니아의 완성", "559a79b4"], "d": ["스칸데르베그가 죽은 지 10년 뒤인 1478년에 아크차히사르, 드리바스토, 레저, 자뱌크가 점령되면서 알바니아 정복은 대체로 완료되었다. 여러 해 동안 오스만 군대에 저항하며 스칸데르베그 저항의 상징이었던 크루야 성의 함락은 이 지역에서 베네치아-알바니아 동맹의 종말을 뜻했다. 남아 있던 슈코더르는 이듬해 체결될 이스탄불 조약에 따라 오스만에 넘겨지게 된다.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["타만반도의 편입", "4ef917b8"], "d": ["1475년 카파와 케르치를 점령한 뒤, 정복자 술탄 메흐메드가 캅카스 해안으로 보낸 함대는 아나파, 코파와 함께 타만반도의 제노바 마트레가(타마타르한)를 점령했다. 이로써 해협의 양안이 통제 아래 놓였고 아조프해의 입구는 완전히 통제할 수 있게 되었다. 북캅카스로 열리는 관문인 타만은 카파 산자크에 편입되었다.", "74a0de9f"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["로도스 포위의 실패", "35a85c28"], "d": ["정복자 술탄 메흐메드의 명령으로 메시흐 파샤가 지휘하는 160척의 함대가 885년(1480년) 봄에 로도스를 포위했고, 섬은 석 달 동안 봉쇄되었다. 기사단장 피에르 도뷔송이 이끄는 성 요한 기사단은 큰 손실에도 불구하고 격렬히 저항했고, 885년 주마다 알울라 월 20일에 감행한 마지막 대공세마저 격퇴되자 함대는 8월 3일에 철수했다. 이 실패 이후 도시의 성벽은 처음부터 다시 쌓아 유럽에서 가장 강력한 방어 시설이 되었고, 섬은 1522년에야 카누니 술탄 쉴레이만에게 점령된다.", "23334bd0"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["예니셰히르 전투 — 젬 술탄의 패배", "c35abee2"], "d": ["정복자 술탄이 죽은 뒤 왕위를 놓고 움직인 두 형제는 예니셰히르 평원에서 맞섰고, 젬 술탄은 결정적인 패배를 당했다. 부르사에서 18일 동안 통치하며 자기 이름으로 후트바를 낭독하게 했던 왕자는 패배 후 먼저 코니아로, 거기서 다시 맘루크 영토로 피신해야 했다. 예니셰히르는 오스만 역사상 가장 오래 이어진 왕조 위기의 시작이었다. 젬 문제는 14년 동안 유럽에 대한 오스만의 대외 정책을 마비시키게 된다.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["헤르체고비나 병합", "bf247891"], "d": ["1463년 보스니아 정복 이후에도 존속하던 헤르체고비나 공작령의 영토는 단계적으로 오스만의 통치로 넘어갔다. 트레비네와 모스타르는 1466년에 점령되었고, 헤르체고비나 산자크는 1470년에 설치되었으며, 아드리아해 연안에 남은 공작령의 마지막 영토도 헤르체그노비와 함께 1482년 초에 정복되어 산자크에 편입되었다. 이로써 아드리아해 배후의 산악 지대는 전부 오스만의 것이 되었고, 보스니아와 헤르체고비나는 하나의 행정 지리권이 되었다. 마지막 공작의 아들로 오스만 궁정에 들어간 이가 훗날 대재상에까지 오르는 헤르체크자데 아흐메드 파샤이다.", "0522e47f"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["젬 술탄의 로도스 망명", "2228d6da"], "d": ["코니아를 포위하려는 시도마저 무위로 끝난 젬 술탄은 30명가량의 부하와 함께 아나톨리아를 빠져나와 로도스에 이르렀고, 성 요한 기사단의 성대한 환영을 받았다. 그러나 손님 대접은 곧 억류로 바뀌었다. 왕자는 먼저 프랑스로, 이어 교황청으로 넘겨져 유럽 정치의 카드가 되었다. 바예지드 2세는 동생이 억류되는 대가로 매년 돈을 지불해야 했고, 서방을 향한 오스만의 군사 행동은 젬이 죽을 때까지 보류되었다.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["오스만-맘루크 전쟁의 시작(추쿠로바 전선)", "3fe3f0c7"], "d": ["둘카디르 왕조에 대한 영향력 다툼과 젬 술탄의 맘루크 영토 망명이 남긴 적대감은 1485년 두 수니파 강국 사이에 6년 동안 이어질 전쟁을 일으켰다. 추쿠로바의 아다나와 타르수스 일대에서 벌어진 교전에서 양측은 서로 우위를 점하지 못했고, 오스만 군대는 몇 차례 큰 타격을 입었다. 이 전쟁은 오스만-맘루크 관계 파탄의 첫 단계이며, 30년 뒤 야부즈 셀림의 마르지 다비크와 리다니야 원정으로 마무리될 과정의 시작이었다.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["오스만-맘루크 강화 — 튀니스의 중재", "60dd6719"], "d": ["1485년에 시작된 오스만-맘루크 전쟁에서 양측은 결정적인 승리를 거두지 못했고, 튀니스의 하프스 왕조 군주 우스만의 중재로 1491년에 합의가 이루어졌다. 조약은 국경을 대체로 전쟁 전의 상태로 되돌렸고, 두 이슬람 국가 간의 결판은 한 세대 동안 미루어졌다. 6년에 걸친 소모적인 투쟁은 바예지드 2세의 신중한 대외 정책과, 동쪽으로 향하기보다 국내 정비에 무게를 둔 주요 원인 중 하나이다.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["스페인에서 추방된 세파르디 유대인의 오스만 수용", "5c2b5c24"], "d": ["그라나다가 함락된 뒤 스페인에서 종교재판의 박해를 피해 달아난 유대인 중 일부는 오스만 영토로 피신하여 여러 도시에 정착했다. 오스만의 통치 아래에서 이 세파르디 공동체들은 원하는 곳에 정착하고, 신앙생활을 하며, 교육 기관을 열고, 새 시나고그(회당)를 짓는 등 그때까지 누리지 못했던 자유를 얻었다. 이들이 가져온 인쇄술, 의학, 재정 지식으로 테살로니키와 이스탄불의 경제생활을 바꾼 이 이주는 오스만의 관용 질서를 보여 주는, 유럽에서 가장 많이 거론된 사례가 되었다.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["젬 술탄의 죽음 — 14년 인질 생활의 끝", "f6588b70"], "d": ["교황청에서 프랑스 국왕 샤를 8세에게 넘겨진 젬 술탄은 1495년 1월 27일 로마를 떠난 뒤 카스텔 카푸아나라는 곳에서 세상을 떠났다. 사료는 그가 교황청 측에 의해 독살되었을 수 있다고 기록한다. 14년 동안 유럽 국가들의 손에서 오스만을 위협하는 카드로 쓰였던 왕자의 죽음은 마침내 바예지드 2세의 손을 자유롭게 했다. 실제로 술탄은 이후 베네치아에 전쟁을 선포하고 함대를 첫 번째 대승으로 이끌게 된다.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["사피엔차(존키오) 해전 승리 — 지중해에서의 첫 해군 대승", "9754aaef"], "d": ["젬 문제가 끝나면서 손이 자유로워진 바예지드 2세는 1499년 베네치아에 전쟁을 선포했다. 오스만 함대는 사피엔차(존키오) 앞바다에서 베네치아 함대를 격파하고 지중해에서 첫 번째 큰 해전 승리를 거두었다. 이 승리로 오스만 해군은 이제 바다에서 베네치아에 맞설 수 있음을 선언한 셈이었다.", "5fa6989c"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["금장 칸국(킵차크 칸국)의 멸망과 크림의 부상", "0d1dc515"], "d": ["마지막 군주 셰이크 아흐마드 칸(1481-1502)은 나라를 위기에서 구해 내지 못했고, 금장 칸국은 1502년 크림 칸 멩글리 기라이의 일격으로 역사 속으로 사라졌다. 왕위 다툼과 분열의 결과, 옛 금장 칸국의 영토에는 크림, 카잔, 노가이, 아스트라한, 시비르 칸국이 나타났다. 오스만의 보호 아래 있던 크림의 이 승리는 흑해 북쪽에서 오스만의 영향력을 확고부동한 것으로 만들었으나, 이 지역에 생긴 공백은 다음 세기에 모스크바가 메우게 된다.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["오스만-베네치아 전쟁의 종결과 강화", "125b1526"], "d": ["1499년에 시작되어 사피엔차, 레판토(이네바흐트), 모돈, 코론의 상실로 베네치아를 뒤흔든 전쟁은 1502년 강화로 끝났다. 모레아의 가장 중요한 거점들을 잃은 베네치아는 동지중해에서의 상업 특권을 유지하는 대가로 오스만의 우위를 인정해야 했다. 신중하다고 평가받던 바예지드 2세의 치세는 이 전쟁을 통해 오스만을 처음으로 지중해의 본격적인 해양 강국의 지위에 올려놓았다.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["샤흐쿨루 반란 — 테케 지방에서 시바스까지 번진 크즐바시 봉기", "3beadca7"], "d": ["아나톨리아에 퍼진 사파비 선전의 영향 아래 1510년에 반란을 드러낸 샤흐쿨루 바바 테켈리는 1511년 3월 안탈리아의 시장을 습격했고, 4월에는 퀴타히아와 그 주변에서 오스만군을 격파했다. 시바스 부근에서 대재상 하듬 알리 파샤와 벌인 마지막 전투에서 양측은 큰 손실을 입었고, 대재상과 반란 지도자 모두 목숨을 잃었다. 아나톨리아에서 국가의 권위를 뒤흔든 이 봉기는 바예지드 2세 말년의 권력 공백을 드러냈고, 셀림 왕자가 왕위를 향해 나아가는 가장 강력한 명분이 되었다.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["바예지드 2세의 퇴위와 야부즈 술탄 셀림의 즉위", "c4cfab69"], "d": ["형제들과의 왕위 다툼에서 예니체리의 지지를 등에 업은 셀림 왕자의 압박으로 바예지드 2세는 1512년 4월 24일 퇴위했고, 셀림 1세는 같은 날 오스만의 아홉 번째 군주로 즉위했다. 연로한 술탄은 자신이 태어난 디메토카로 가던 길에 초를루 부근의 아발라르 마을에서 918년 라비 알아우왈 월 25일(1512년 6월 10일)에 세상을 떠났다. 31년에 걸친 신중하고 내향적인 치세는, 8년 만에 제국의 국경을 두 배로 넓히게 될 야부즈의 시대로 바뀌었다.", "7194b8c2"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["예니셰히르 전투와 아흐메드 왕자의 제거", "e2ed15dd"], "d": ["야부즈 술탄 셀림은 왕위의 가장 강력한 경쟁자였던 형 아흐메드 왕자를 부르사 부근의 예니셰히르 평원에서 격파하고, 포로로 잡아 제거했다. 이로써 1511년부터 이어진 형제간의 다툼이 막을 내렸고 아나톨리아의 내부 분열도 끝났다. 셀림은 후방을 안정시켜 사파비 문제에 전념할 수 있는 여유를 얻었다.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["야부즈 술탄 셀림의 타브리즈 입성", "dad2e227"], "d": ["찰디란 승리 이후 오스만군은 사파비의 수도 타브리즈에 입성했고, 시내에서 술탄의 이름으로 후트바가 낭독되었다. 셀림은 이곳에 일주일 머물며 타브리즈의 장인과 울레마 일부를 이스탄불로 이주시켰는데, 이 이주는 오스만 궁정 예술에 깊은 영향을 주게 된다. 겨울이 다가오고 예니체리의 불만이 커져 도시는 버려졌으나, 동방에서 사파비의 우위는 이미 꺾였다. 지도에서 이날 오스만에게 넘어가는 곳들은 서로 이어져 있지 않으며, 이는 올바른 것이다. 타브리즈는 9일간의 군사 점령이었고, 에르진잔 평원은 원정 중에 싸우지 않고 항복했으나 그 한가운데의 케마흐 요새는 1515년 5월 19일까지 사파비 편에서 저항했다. 시이르트는 타브리즈에서 샤 이스마일의 감금에서 풀려난 하산케이프의 말릭(군주) 할릴 베이가 오스만에 복종하면서 사파비에게서 되찾은 것이며, 그 주변의 디야르바키르는 1515년까지, 하산케이프는 1517년까지 사파비의 땅으로 남았다.", "3f65211e"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["사파비로부터 케마흐 성 정복", "73fd8671"], "d": ["찰디란에서 돌아와 아마시아에서 겨울을 보낸 야부즈 술탄 셀림은 유프라테스강의 도하 지점을 장악한 견고한 케마흐 성의 정복을 브이으클르 메흐메드 파샤에게 맡겼다. 술탄도 직접 참가한 포위 끝에 요새는 사파비의 손에서 빼앗겼고, 동부 아나톨리아의 문이 열렸다. 이 정복은 찰디란의 승리를 영구적인 영토 획득으로 바꾼 첫 번째 구체적 걸음이다.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["투르나다으 승리 — 둘카디르 베이국이 오스만의 봉신이 됨", "fd879145"], "d": ["오스만군은 찰디란 원정 때 애매한 태도를 취했던 둘카디르의 베이 알라우다울레 보즈쿠르트를 괴크순과 안드른 사이의 외르데클리라는 곳에서 격파했고, 알라우다울레는 이 전투에서 전사했다. 베이국은 이때 병합되지 않았다. 알라우다울레의 뒤를 이어 야부즈 술탄 셀림이 셰흐수바르오을루 알리 베이를 둘카디르 베이국의 수장으로 앉혔고, 마라시-엘비스탄을 중심으로 한 나라는 오스만의 봉신 베이국으로 존속했다. 이로써 맘루크 국경의 완충 지대가 오스만의 통제 아래 들어갔고 2년 뒤 이집트 원정의 길이 열렸다. 병합은 알리 베이가 살해된 뒤에야 이루어진다.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["아미드(디야르베키르) 정복과 디야르베키르 베일레르베이 관구의 설치", "a6867d5b"], "d": ["이드리스 비틀리시가 이 지역의 수니파 쿠르드 영주들을 오스만 편으로 끌어들인 뒤, 사파비군은 긴 포위를 견디지 못했고 아미드의 열쇠는 브이으클르 메흐메드 파샤에게 넘어갔다. 도시는 새로 설치된 디야르베키르 베일레르베이 관구의 중심지가 되었다. 이로써 상부 메소포타미아의 행정 핵심이 오스만의 손에 넘어갔다.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["하르푸트 정복 — 디야르베키르 길이 열림", "564eb269"], "d": ["찰디란 이후 점령한 디야르베키르를 사파비의 포위에서 구하기 위해 출발한 카라만 베일레르베이 휘스레브 파샤는, 앞서 체르케즈 휘세인 베이가 그 주변을 장악해 둔 하르푸트 성을 사흘간의 포위 끝에 점령했다. 이로써 유프라테스강 동쪽에서 디야르베키르로 이어지는 길이 확보되었다.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["코치히사르(크즐테페) 전투 — 카라 한의 패배", "9ea9e843"], "d": ["브이으클르 메흐메드 파샤가 이끄는 오스만군은 코치히사르 부근 데데 가르큰 평원의 코루크라는 곳에서 하루 종일 이어진 회전 끝에 사파비 총독 카라 한을 격파했고, 카라 한의 잘린 머리는 술탄의 진영으로 보내졌다. 이어 오스만군은 마르딘 시에 들어갔으나 며칠 머문 뒤 떠났고, 사파비 수비대가 지키던 마르딘 성은 1년 뒤에야 접수할 수 있었다. 이 승리는 셀림이 남쪽 국경을 확보하고 이집트 원정으로 향할 수 있게 해 주었다. 같은 날짜에 편입된 다른 곳: 팔루, 체미슈게제크, 시베레크.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["야부즈 술탄 셀림이 이집트 원정을 위해 이스탄불에서 출발", "ac258b4b"], "d": ["야부즈 술탄 셀림은 겉으로는 사파비에 대한 새 동방 원정을 준비하는 모양새로 이스탄불을 출발하여 아크셰히르를 거쳐 남쪽으로 향했다. 맘루크 술탄 칸수 알가우리가 샤 이스마일과 접촉하고 오스만의 동쪽 측면을 위협하면서 목표는 곧 바뀌게 된다. 이 원정은 2년간 이어져 오스만을 중동 제국으로 바꾸게 될 대작전의 시작이다.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["자비드 점령: 오스만 선원들의 홍해 첫 진출", "38740e0c"], "d": ["인도양에서의 포르투갈의 압박에 직면한 맘루크 술탄 칸수 알가우리의 요청으로 홍해에 파견된 오스만 출신 선원 휘세인 베이와 셀만 레이스는 함대를 이끌고 자비드를 점령했다. 아직 맘루크를 섬기는 가운데 수행된 이 작전은 홍해-인도 항로에서 오스만 해군이 실제로 존재한 첫 사례이다. 1년 뒤 이집트가 오스만에 넘어가면 이 함대는 이스탄불에 직속하게 된다.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["원정의 목표가 맘루크와 알레포임을 공식 선포", "689e310d"], "d": ["칸수 알가우리가 사파비와 합의하고 군대를 알레포로 진격시키자, 야부즈 술탄 셀림은 원정의 목표가 맘루크 술탄과 알레포임을 공개적으로 선포했다. 이로써 두 수니파 국가 사이에 여러 해 이어진 은밀한 경쟁이 공공연한 전쟁으로 바뀌었다. 이 선포로 마르지 다비크까지 4주의 초읽기가 시작되었다.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["아덴 포위 실패: 포르투갈에 맞선 첫 홍해 시도", "8ffd46f2"], "d": ["셀만 레이스와 휘세인 베이는 홍해에서 인도양으로 나가는 관문인 아덴을 점령하기 위해 8일에 걸친 포위전을 벌였으나, 도시의 강력한 방어 시설 앞에서 물러나야 했다. 아덴을 점령하지 못한 것은 포르투갈에 맞서 펼칠 남방 전략을 여러 해 동안 가로막게 된다. 이 시도는 오스만의 대양 정책이 맞은 첫 시험이었다.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["라마잔 왕조 베이국이 오스만에 편입", "cfaa3754"], "d": ["마르지 다비크 승리 이후 행해진 임명(테브지흐) 가운데, 아다나를 중심으로 한 라마잔 왕조 베이국은 마흐무드 베이에게 맡겨져 오스만의 주권 아래 놓였다. 맘루크의 신종에서 벗어난 이 베이국은 폐지되지 않고 '오자클르크'(가문 세습령) 지위로 가문에 남겨졌고, 라마잔 가문은 오스만의 산자크 베이 자격으로 추쿠로바의 통치를 이어 갔다. 이 특권적 체제는 피르 만수르가 베이국을 내놓은 1608년까지 계속되었다. 같은 날짜에 편입된 다른 곳: 말라티아, 타르수스, 모술, 안테프.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["알레포, 라카, 데이르에조르가 오스만의 지배 아래로", "2088eb6a"], "d": ["마르지 다비크 전투 나흘 뒤, 야부즈 술탄 셀림은 저항을 받지 않고 알레포에 입성했고, 시내 모스크에서 그의 이름으로 후트바가 낭독되었다. 시리아의 상업·행정 수도로 여겨지던 알레포가 그토록 빨리 함락된 것은 이 지역에서 맘루크의 권위가 무너졌음을 보여 준다. 이 도시의 점령으로 다마스쿠스와 거기서 이집트에 이르는 길이 단번에 열렸다. 같은 날짜에 편입된 다른 곳: 안타키아, 라카, 데이르에조르.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["알레포의 괵메이단에서 압바스 칼리파 알무타왁킬 3세와 면담", "22979f42"], "d": ["마르지 다비크에서 맘루크군과 함께 포로가 된 카이로의 압바스 칼리파 알무타왁킬 3세는 알레포의 괵메이단에서 술탄 앞에 인도되었고, 야부즈 술탄 셀림은 그를 크게 예우했다. 1261년부터 맘루크 술탄의 그늘에서 상징적 직위에 머물던 카이로의 칼리파위는 이 면담으로 사실상 오스만의 보호 아래로 넘어갔다. 칼리파는 이후 술탄과 함께 이스탄불로 옮겨지게 된다.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["시리아의 트리폴리와 하마가 오스만의 통치 아래로", "a1e19a79"], "d": ["알레포와 하마에 이어 시리아 해안의 트리폴리도 저항 없이 오스만의 통치로 넘어갔다. 동지중해에서 가장 붐비는 항구 중 하나인 이 도시는 다마스쿠스가 바다로 나가는 관문이자 비단과 설탕 무역의 중심지였다. 이 도시의 점령으로 빌라드 알샴(대시리아)의 해안 지대는 통째로 주인이 바뀌었다.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["다마스쿠스(디마슈크)가 오스만의 지배 아래로", "2b844d91"], "d": ["알레포에 이어 하마와 홈스가 항복하면서 길이 열린 야부즈 술탄 셀림은 9월 27일 다마스쿠스 앞에 이르렀다. 그는 곧장 도시에 들어가지 않고 바깥의 마스타바라는 곳에 천막을 쳤으며, 도착한 지 열이틀째에 성대한 의식과 함께 입성했다. 다마스쿠스에 한동안 머물며 시리아의 행정 체제를 정비했고, 무히이딘 이븐 알아라비의 묘를 세우게 했다. 이로써 빌라드 알샴 전체가 맘루크의 통치에서 벗어났다. 같은 날짜에 편입된 다른 곳: 베이루트.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["투만바이가 카이로에서 맘루크 술탄으로 선포됨", "6020d90d"], "d": ["마르지 다비크에서 전사한 칸수 알가우리의 뒤를 이어, 맘루크 아미르들은 국가의 마지막 술탄이 될 투만바이를 왕위에 올렸다. 체르케스 출신의 새 술탄은 시리아를 잃고 국고가 바닥났으며 화기도 갖추지 못한 국가를 물려받았다. 그럼에도 그는 카이로 앞에 방어선을 구축하여 오스만의 진격에 맞서는 마지막 저항을 조직하게 된다.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["가자(칸 유니스) 전투: 잔비르디 알가잘리의 패배", "9f1eb8cb"], "d": ["야부즈 술탄 셀림은 4천 명의 선봉대와 함께 대재상 하듬 시난 파샤를 가자로 보냈다. 투만바이가 다마스쿠스 총독에 임명한 잔비르디 알가잘리는 가자-칸 유니스 선에서 오스만 선봉대를 저지하려 했으나 큰 패배를 당하고 이집트로 달아났다. 팔레스타인에 남아 있던 맘루크의 마지막 완충 병력이 흩어지면서 시나이 사막으로 가는 길이 완전히 열렸다.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["요르단강 동쪽: 암만이 오스만의 통치 아래로", "9db62667"], "d": ["가자 전투 이후 이집트 원정을 준비하던 오스만군이 남하하면서 요르단강 동쪽의 암만도 오스만의 통치 아래 들어갔다. 팔레스타인의 해안 및 내륙 도시들(야파, 나블루스, 시돈, 아크레, 예루살렘)은 마르지 다비크 전투 이후인 1516년 가을에 이미 주인이 바뀌어 있었다. 이 도시들은 4세기 동안 다마스쿠스 주의 산자크로 통치되었다.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["야부즈 술탄 셀림의 예루살렘 도착", "66d7bfad"], "d": ["마르지 다비크 이후 저항 없이 오스만의 통치로 넘어와 있던 예루살렘에, 야부즈 술탄 셀림은 가자 전투 뒤 국가의 고관들과 군대를 이끌고 도착했다. 술탄은 바위의 돔과 알아크사 모스크를 방문하여 이 도시의 성스러운 지위를 확인했다. 예루살렘은 이때부터 1917년 12월까지 꼬박 4세기 동안 오스만의 통치 아래 남게 된다.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["야부즈 술탄 셀림의 가자 입성과 시나이 사막으로의 진로 전환", "2106bfc7"], "d": ["칸 유니스에서 잔비르디 알가잘리가 패배한(1516년 12월 21일) 뒤 가자는 선봉대의 수중에 있었다. 술탄은 1517년 1월 2일 가자에 들어가 선봉대를 이끄는 시난 파샤와 합류했고, 군대는 이집트로 건너가기 위한 마지막 준비를 했다. 가자에서 살리히야까지 뻗은 물 없는 카트야(시나이) 사막을 여덟 행정에 걸쳐 걸어야 했고, 물은 낙타로 운반해야 했다. 이 횡단은 원정에서 가장 위험하고 병참상 가장 어려운 단계였다.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["수에즈 점령 — 홍해로 열리는 관문", "05f3324e"], "d": ["리다니야 승리 이후 오스만 부대가 카이로에 입성하면서, 홍해 북쪽 끝의 수에즈도 오스만의 통치로 넘어갔다. 맘루크가 인도양으로 함대를 보내던 이 조선소 겸 항구는 포르투갈에 맞서 펼칠 남방 정책의 거점이 되었다. 수에즈는 3세기 뒤 운하가 개통될 노선의 북쪽 입구이다.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["오스만 부대의 첫 카이로 입성", "0a3f4f4d"], "d": ["리다니야 승리 이튿날 오스만군의 카이로 입성이 허락되었고, 1월 24일에 부대가 도시에 주둔했다. 그러나 이 입성이 도시를 완전히 장악했다는 뜻은 아니었다. 투만바이는 상이집트로 물러났고, 맘루크의 저항은 아직 꺾이지 않았다. 카이로 정복은 하루가 아니라 여러 주에 걸친 유혈의 과정 속에서 완성된다.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["투만바이의 카이로 기습과 사흘간의 시가전", "b83b6ce6"], "d": ["상이집트로 물러났던 투만바이는 약 7천 명의 병력과 함께 1월 27-28일 밤에 불시에 카이로에 들어와 시내에서 저항을 시작했고, 오스만 부대를 극도로 어려운 처지로 몰아넣었다. 사흘간의 격렬한 시가전에서 맘루크는 일시적으로 도시의 대부분을 장악했다. 저항은 오스만의 포병과 증원군이 투입되고서야 꺾을 수 있었다.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["잔비르디 알가잘리가 오스만을 섬기게 됨", "a94ea459"], "d": ["리다니야 이후 살리히야로 물러났던 옛 맘루크 아미르 잔비르디 알가잘리는 술탄에게 안전 보장(아만)을 청했다. 야부즈 술탄 셀림은 그가 이집트와 시리아의 질서 확립에 쓸모가 있으리라 여겨 자기 휘하에 받아들였다. 이 선택은 맘루크 인사들을 숙청하지 않고 체제에 편입하는 오스만 정책의 첫 번째 큰 사례이다.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["야부즈 술탄 셀림의 의식을 갖춘 카이로 입성과 후트바 낭독", "6d98080c"], "d": ["시가전이 진압된 뒤 술탄은 1517년 2월 15일 매우 화려한 의식과 함께 카이로에 입성했고, 모스크에서 그의 이름으로 후트바가 낭독되었다. 카이로에서 오스만 술탄의 이름으로 후트바가 낭독된 것은 1250년부터 이어진 맘루크의 지배가 법적으로 끝났음을 선포하는 것이었다. 이 날짜는 이집트의 실질적 정복이 상징적으로 완성된 순간으로 여겨진다.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["마지막 맘루크 술탄 투만바이가 테루자에서 체포됨", "7058e6ad"], "d": ["카이로를 떠난 뒤 나일 삼각주에 숨어 있던 투만바이는, 자신에게 은신처를 제공한 베두인의 밀고로 테루자 지역에서 붙잡혔다. 그의 체포로 맘루크 저항의 조직적 중심이 사라졌다. 마지막 술탄은 이후 열나흘 동안 오스만의 수중에 억류된다.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["투만바이의 바브 주웨일라 처형과 맘루크 왕조의 종말", "ad9820be"], "d": ["체포된 지 열나흘 뒤, 투만바이는 카이로의 유명한 성문 바브 주웨일라에서 교수형에 처해졌고, 그의 시신은 뒤에 숙부가 세운 마드라사에 묻혔다. 이로써 1250년부터 이집트와 시리아를 지배해 온 맘루크 왕조는 공식적으로 역사 속으로 사라졌다. 저항이 꺾이면서 상이집트(사이드)의 아시우트, 아스완 같은 도시들도 오스만의 통치에 편입되었다.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["포르투갈 함대의 제다 공격과 셀만 레이스의 방어", "52322cf5"], "d": ["약 30척의 갤리선과 갤리언으로 이루어진 포르투갈 함대가 제다를 공격했다. 셀만 레이스는 도시의 방어를 지휘하여 적의 상륙을 막고 포르투갈 선박 몇 척을 격침했다. 이 방어는 메카의 항구, 따라서 순례길이 기독교 국가의 손에 넘어가는 것을 막았다. 몇 달 뒤 제다는 헤자즈의 충성 서약과 함께 공식적으로 오스만의 통치에 편입된다.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["함대에 의한 알렉산드리아 접수 — 이집트 정복의 완성", "386878fe"], "d": ["리다니야 전투에서 꼭 넉 달 뒤, 투만바이가 처형된 지 36일 뒤에, 자페르 베이가 이끄는 오스만 함대가 항구에 도착하면서 알렉산드리아는 오스만의 통치로 넘어갔다. 로제타(라시드)와 다미에타 같은 삼각주 항구들도 같은 과정에서 편입되었다. 지중해로 열린 이집트의 이 큰 항구가 카이로 함락 몇 달 뒤에, 그것도 육로가 아닌 바다를 통해 접수되었다는 사실은, 정복이 한 번의 전투가 아니라 지역별로 완성되었음을 분명히 보여 준다. 알렉산드리아는 이후 이스탄불과 카이로를 잇는 핵심 항구가 된다. 같은 날짜에 편입된 다른 곳: 라시드(로제타).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["헤자즈의 무혈 편입: 메카 샤리프의 아들 아부 누마이의 충성 서약", "c13b98c7"], "d": ["야부즈 술탄 셀림은 처음에 메카와 그 주변을 점령하기 위해 병력을 보낼 생각이었으나, 메카의 아미르 샤리프 바라카트가 복종의 뜻을 알려 오자 이를 단념했다. 바라카트의 열두 살 아들 아부 누마이는 아버지의 선물과 메카의 열쇠를 가지고 카이로에 와서 술탄을 알현했다. 이로써 헤자즈는 리다니야 전투의 자동적인 결과가 아니라, 다섯 달 반이 지난 뒤 총 한 방 쏘지 않고, 평화적으로 충성 서약을 통해 오스만에 편입되었다. 같은 날짜에 편입된 다른 곳: 타이프. 같은 날짜에 상실한 다른 정착지: 후르마(타이프 동쪽), 라비그, 바드르.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["하디물 하라마인 칭호의 수용과 메디나의 후트바", "63b32b59"], "d": ["메카 사절단을 두 번째로 접견한 뒤, 야부즈 술탄 셀림은 두 성지(하라마인)의 보호를 공식적으로 맡고 '하디물 하라마이니 샤리파인'(두 성스러운 성소의 종)이라는 칭호를 쓰기 시작했다. 샤리프 바라카트는 자신에게 보내진 하사 예복(힐아트)을 입고 술탄의 이름으로 후트바를 낭독하게 했으며, 메디나 사절단도 이스탄불에 가면서 바라카트의 아미르직은 임명장(베라트)으로 승인되었다. 술탄은 두 성지의 주민에게 금화 20만 닢과 풍족한 식량을 보내어, 해마다 반복될 수르레(성지 하사품) 전통을 시작했다. 같은 날짜에 편입된 다른 곳: 얀부, 타부크.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["셀만 레이스의 오스만 봉직과 홍해 정책의 계승", "771da99a"], "d": ["포르투갈에 맞서 제다를 방어한 셀만 레이스는 카이로에 와서 야부즈 술탄 셀림을 알현했다. 한동안 억류되기도 했으나 1519년 이스탄불로 불려 가, 포르투갈의 위협에 대비해 갤리선 30척과 갈리엇 몇 척을 준비하겠다고 약속했다. 이 만남은 홍해와 인도양 정책이 맘루크의 유산으로부터 계승되어 이스탄불에 직접 연결되기 시작한 출발점이다. 오스만은 이제 지중해 국가일 뿐 아니라 대양 정책도 펼치는 강국이었다.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["야부즈 술탄 셀림의 카이로 출발과 하이으르 베이의 베일레르베이 취임", "8cd4fb23"], "d": ["이집트에 약 여덟 달 머물며 행정·재정·군사 체제를 세운 야부즈 술탄 셀림은 카이로를 떠났다. 마르지 다비크에서 좌익을 철수시켜 맘루크의 패배를 앞당긴 전 알레포 총독 하이으르 베이가 오스만 최초의 이집트 베일레르베이로서 칼라트 알자발(카이로 성채)에서 통치를 시작했다. 맘루크 출신 총독을 고른 것은 새 통치가 현지 주민에게 낯설게 느껴지지 않도록 하는 의도적인 이행 정책이었다. 술탄은 귀로에 마지막 압바스 칼리파 알무타왁킬 3세와 이집트의 뛰어난 장인과 학자들을 이스탄불로 데려갔다.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["카이로 압바스 칼리파위의 종말 — '이양 의식' 전승", "1d357640"], "d": ["야부즈 술탄 셀림은 이집트를 점령하자, 마르지 다비크에서 포로가 된 마지막 칼리파 알무타왁킬 알랄라 3세를 자신과 함께 이스탄불로 데려갔다. 이로써 1261년부터 맘루크 술탄의 그늘에서 권한 없이 이어져 온 카이로의 압바스 칼리파위는 끝났다. 반면 칼리파위가 아야 소피아에서 공식 의식을 통해 셀림에게 이양되었다는 유명한 전승은 18세기 말 도송(d'Ohsson)의 저작에 처음 나타나며, 셀림 시대의 사료 어디에도 없다. TDV 이슬람 백과사전은 이 의식을 입증하는 원사료가 없으므로 그 전승을 지어낸 것으로 본다. 다만 칼리파위의 이전에는 샤리아상 그러한 이양 의식이 필요하지 않았다는 점도 함께 기록한다.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["에르주룸이 오스만의 통치에 편입 — 동부 아나톨리아에서 사파비의 영향력이 꺾임", "78d1be02"], "d": ["찰디란 승리(1514) 이후 이 지역에서 오스만의 영향력은 커졌으나, 에르주룸의 완전한 장악은 이란의 영향력이 꺾일 때까지 늦어졌다. 이 도시는 이집트 원정이 끝난 뒤인 1518-19년에야 오스만의 통치에 편입되었다. 에르주룸은 1502년 샤 이스마일이 백양 왕조 베이국을 끝내면서 사파비의 지배 아래 들어갔는데, 16년에 걸친 이 시기가 이렇게 막을 내렸다. 1534년 양(兩) 이라크 원정 때 에르주룸 베일레르베이 관구가 설치된다. 1518-1519년 사이에 에르주룸 지역과 함께 아슈칼레도 오스만의 통치에 편입되었다(날짜 미확인).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["젤랄리 반란의 시작: 보조크의 셰이크 젤랄 봉기", "99bd8a99"], "d": ["보조크 지방에서 셰이크 젤랄이라는 사람이 스스로 마흐디라 선언하고 토카트 일대에서 봉기했다. 반란은 진압되었으나 그의 이름은 한 세기 동안 아나톨리아의 모든 도적 및 봉기 운동을 일컫는 이름이 되었다. 젤랄리 반란은 16세기 말 티마르 제도의 해체와 인구 압박이 겹치면서 제국에서 가장 오래 지속된 국내 치안 문제가 되었다. 이 봉기들은 아나톨리아에서 '대도피'라 불리는 대규모 이주를 낳았다.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["알제의 오스만 제국 편입", "b8eba4c1"], "d": ["북아프리카에서 스페인의 압박에 맞서 저항하던 하이레딘 레이스는 버티기 위해 이스탄불에 도움을 청하여 알제를 술탄에게 바쳤고, 야부즈 술탄 셀림의 이름으로 후트바가 낭독되었다. 이로써 알제는 공식적으로 오스만 영토에 편입되었고, 하이레딘에게는 베일레르베이 칭호와 함께 병사와 대포가 보내졌다. 이 편입은 서지중해에서 수 세기 동안 이어질 오스만 해상 지배의 토대를 놓았다. 같은 날짜에 편입된 다른 곳: 콘스탄틴, 셰르셸, 메데아(티테리), 세티프.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["야부즈 술탄 셀림의 초를루 서거", "9fe83744"], "d": ["8년 만에 국가의 영토를 두 배 이상 늘린 셀림 1세는 1520년 7월 18일 새 원정을 위해 이스탄불을 떠났으나, 등에 생긴 큰 종기 때문에 초를루에서 더 나아가지 못했다. 의사들의 치료에도 병은 악화되었고, 두 달에 걸친 가망 없는 치료 끝에 926년 샤왈 월 8-9일(1520년 9월 21-22일)에 그곳에서 세상을 떠났다. 그는 찰디란, 마르지 다비크, 리다니야를 통해 이란을 저지하고 맘루크 왕조를 없앴으며, 칼리파위와 두 성지의 수호자 지위를 오스만에 가져왔다. 그는 아들을 단 한 명 남겼으니, 그가 쉴레이만이다.", "39cccc63"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["이집트에서의 '반역자' 아흐메드 파샤 반란", "b18bb805"], "d": ["대재상직을 기대하다가 이집트 총독으로 파견된 아흐메드 파샤는 카이로에서 스스로를 '알말리크 알만수르 술탄 아흐메드'라 선언하며 독립을 선포했다. 반란은 단기간에 진압되고 파샤는 살해되었으나, 이 사건은 제국에서 가장 부유한 주에서 중앙의 통제가 얼마나 취약한지를 드러냈다. 이에 이브라힘 파샤는 이집트로 가서 주의 행정을 재편한 유명한 이집트 법전(카눈나메)을 편찬하게 했다.", "35eb542c"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["부다 점령과 서포여이에게의 양도", "fba4f89b"], "d": ["빈 원정길에 오스만군은 페르디난트의 손에 넘어가 있던 부다를 포위하여 되찾고, 이 도시를 오스만의 보호를 받던 헝가리 왕 서포여이 야노시에게 넘겼다. 이로써 합스부르크와 오스만이 경쟁하는 헝가리에 완충 봉신 왕국이라는 모델이 세워졌다. 이 체제는 1541년까지 이어지며, 서포여이가 죽은 뒤 부다는 오스만의 직할 주가 된다.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["카누니 술탄 쉴레이만이 독일 원정에 나섬 — 카를 5세에 대한 도전", "7c3d7055"], "d": ["빈 포위가 성과 없이 끝나고 페르디난트가 부다를 다시 포위하자, 술탄은 이번에는 황제 카를 5세를 직접 회전으로 끌어내기 위해 이스탄불을 출발했다. 군대는 8월 작은 귄스 요새의 저항에 발이 묶이게 되고, 황제가 전투에 나서지 않아 원정은 습격에 그치게 된다. 이 원정은 이듬해 합스부르크와 맺는 첫 강화의 토대를 마련했다.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["독일 원정과 귄스(쾨세그) 포위", "8aec937a"], "d": ["카누니 술탄 쉴레이만은 카를 5세를 회전으로 끌어내기 위해 군대를 이끌고 오스트리아로 진군했다. 작은 귄스 요새는 25일 동안 저항하여 군대의 전진을 지연시켰다. 황제가 전투에 나서지 않자 아큰즈(기습 기병)들은 빈 일대를 습격했고, 계절이 깊어지자 군대는 회군했다. 원정은 영토를 얻지 못했으나 합스부르크를 협상장으로 불러내어 이듬해 강화의 토대를 마련했다.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["이스탄불 조약 — 합스부르크와의 첫 강화", "b085767a"], "d": ["페르디난트의 사절 코르넬리우스를 접견한 술탄은 휴전에 동의했고, 오스만과 오스트리아 사이의 첫 공식 강화 문서가 생겨났다. 조약에 따라 페르디난트는 자신이 보유한 헝가리 영토에 대해 연례 공납을 바치기로 했고, 오스트리아 대공은 의전상 대재상과 동급으로 간주되었다. 이 불평등한 지위는 16세기 오스만 외교의 우위 주장을 분명히 표현한 것이었다.", "e51c434d"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["바르바로사의 튀니스 정복", "d8754216"], "d": ["카푸단 파샤(해군 총사령관) 바르바로사 하이레딘 파샤는 함대로 이탈리아 해안을 공격한 뒤 튀니스로 방향을 돌려, 하프스 왕조의 군주 물레이 하산을 몰아내고 도시에 입성했다. 시칠리아 해협을 통제하는 위치에 있는 튀니스의 점령은 서지중해의 세력 균형을 단번에 오스만에게 유리하게 바꾸었다. 그러나 이 지배는 오래가지 못했고, 카를 5세는 이듬해 대함대로 응수하게 된다.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["튀니스를 카를 5세에게 빼앗김", "a691f0f8"], "d": ["카를 5세는 제노바와 교황청 함대의 지원을 받은 대원정으로 라 굴레트(할쿨바드)를 함락시킨 뒤 튀니스를 점령하고, 물레이 하산을 스페인의 보호 아래 왕위에 복위시켰다. 도시에는 스페인 수비대가 배치되어 중부 지중해에서 오스만의 진출은 일시적으로 저지되었다. 튀니스의 최종 정복은 40년 뒤인 1574년에야 가능해진다.", "cbb995cd"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["총신 이브라힘 파샤의 처형", "348aa7b8"], "d": ["13년 동안 대재상을 지냈으며 카누니 술탄 쉴레이만의 가장 가까운 벗이자 국가의 실질적인 이인자였던 이브라힘 파샤는, 이프타르에 초대받은 궁전에서 아무런 이유도 제시받지 않은 채 교살당해 처형되었다. 양(兩) 이라크 원정에서 그가 보인 태도, '세라스케르 술탄'이라는 칭호의 사용, 궁정 내의 세력 관계가 그의 죽음에 영향을 미친 것으로 여겨진다. 이 처형은 오스만 중앙 정부에서 대재상에게 절대적인 신변 안전이 없었음을 보여 주는 전환점이다.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["클리스 요새 정복과 달마티아 산자크의 설치", "6ffd4ebf"], "d": ["가지 휘스레브 베이의 케트휘다(대리관)이자 크로아티아 출신의 개종자인 무라드 베이는 스플리트 바로 북쪽의 전략적 클리스 요새를 베네치아에게서 빼앗았다. 정복 직후 클리스는 주변을 포괄하는 새 산자크와 카자의 중심지가 되었으며, 이 산자크의 경계는 대체로 오스만령 크로아티아의 윤곽을 그렸다. 크닌보다 15년 뒤에 이루어진 이 정복은 달마티아 내륙의 행정 골격을 완성했다.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["코르푸 포위와 베네치아와의 전쟁", "11af95bd"], "d": ["풀리아(아풀리아) 원정 이후 오스만군은 코르푸에 병력을 상륙시켜 섬의 강력한 베네치아 요새를 포위했다. 요새의 험준한 구조, 큰 손실, 계절적 조건 때문에 9월 6일 봉쇄를 풀고 철수했다. 포위는 성과 없이 끝났으나, 베네치아와 시작된 전쟁은 에게해와 아드리아해의 많은 섬이 오스만에 편입되고 이듬해 프레베자 승리로 이어지는 결과를 낳았다.", "f023c2b9"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["몰다비아 원정과 부자크(벤데르) 지역의 병합", "90a88a56"], "d": ["오스만에 대한 의무를 이행하지 않은 몰다비아의 공 페트루 라레슈를 겨냥한 원정에서 수체아바가 점령되었고, 이아시는 크림 칸 사히브 기라이에게 약탈당했다. 술탄은 메뚜기 슈테판(체키르게 슈테판)을 공위에 앉히고, 벤데르와 함께 부자크(남베사라비아) 지역을 직접 오스만 영토에 편입했다. 이 병합은 흑해 북서 해안을 오스만의 내해로 만든 고리 가운데 하나가 되었다. 몰다비아는 이미 오스만의 봉신 공국이었다. 이번 원정은 외국으로부터 땅을 빼앗은 것이 아니라, 벤데르와 부자크의 내정만을 공에게서 거두어 술탄에게 직속시킨 것이며, 공국의 나머지 지역은 봉신 지위를 유지했다. 같은 구조가 1484년 킬리아와 아케르만에서, 1713년 호틴에서도 반복된다. 즉 국경 요새는 직할, 내륙은 봉신이었다.", "96376de1"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["에스테르곰과 세케슈페헤르바르 정복", "efca9e05"], "d": ["카누니 술탄 쉴레이만이 직접 나선 헝가리 원정에서, 2주 반의 포위 끝에 헝가리 왕국의 종교적 중심지이자 대주교 도시인 에스테르곰이 오스만의 통치 아래 들어갔다. 이어 헝가리 왕들의 대관식 도시인 세케슈페헤르바르도 점령되어 부다 주의 방어선이 완성되었다. 에스테르곰은 1595년까지 다뉴브 방어선의 핵심 요새로서 오스만의 수중에 남게 된다.", "93577806"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["이스탄불 조약 — 합스부르크와의 5년 강화", "41f81773"], "d": ["오스만과 합스부르크 사이에 5년 기한의 강화가 체결되었다. 페르디난트는 자신이 보유한 헝가리 영토에 대해 매년 3만 두카트를 바치기로 했다. 조약은 헝가리가 셋으로 나뉜 사실상의 상태를 법적으로 확인했다. 이렇게 서부 전선이 안정됨으로써 카누니 술탄 쉴레이만은 이란에 대한 새 원정을 벌일 기회를 얻었다.", "36cfadaa"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["테메슈바르에서 파견된 병력이 남부 바나트의 목책 요새들을 장악 — 베르셰츠, 하람, 케베", "edca0921"], "d": ["테메슈바르가 오스만군에 항복한 뒤, 포위군에서 분리된 부대들은 바나트의 작은 목책 요새들로 향했다. 반라키의 서술에 따르면 베르셰츠, 파체트, 메하디아, 차코바르, 하람바르, 케베의 목책 요새들이 이 병력에 장악되었다. 이로써 도나우강변의 하람도 오스만의 손에 들어갔다.", "a5906d21"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["오스만-프랑스 동맹 — 프랑스 함대가 오스만의 지휘 아래로", "a8e01b22"], "d": ["1553년 2월 1일자 조약에 따라 프랑스 함대는 오스만 함대의 지휘 아래 놓였고, 서지중해에서 스페인에 맞선 합동 작전이 예정되었다. 조약 이후 투르구트 레이스는 1553년 6월 15일 프랑스를 지원하기 위해 갤리선 45척을 이끌고 출정했다. 이것은 1536년 카피툴레이션의 상업적 토대를 군사 협력으로 확장한 첫 공식 동맹 조약이었다.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["코니아 에렐리에서의 무스타파 왕자 처형", "dec36858"], "d": ["나흐츠반 원정을 위해 소집된 군대에 합류하고자 아버지의 천막에 들어간 무스타파 왕자는, 술탄을 알현하려는 순간 사형 집행인들과 마주쳤고 교살당해 죽었다. 군대에서 큰 사랑을 받던 후계 후보의 살해는 예니체리들 사이에 깊은 분노를 일으켰고, 뤼스템 파샤는 대재상직에서 해임되었다. 이 사건은 오스만의 왕자 정책에서 가장 논란이 많은 전환점의 하나로 문학과 민중의 기억에 남았다.", "ce2742ae"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["코니아의 왕자 간 전투", "1c8de387"], "d": ["왕위 다툼에 뛰어든 바예지드 왕자는 약 3만 명의 병력을 이끌고 코니아 앞에 이르렀으나, 이틀간의 전투에서 동생 셀림 왕자에게 패했다. 패주한 바예지드는 아마시아를 거쳐 이란의 샤 타흐마스프에게 몸을 의탁했다. 이 전투는 카누니 술탄 쉴레이만 말년의 왕위 계승 위기를 외교 문제로 바꾸어 놓았다.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["제르바 해전 승리", "c7b905c1"], "d": ["피얄레 파샤가 이끄는 오스만 함대는 트리폴리를 되찾기 위해 모인 스페인-제노바-몰타 연합 함대를 제르바 앞바다에서 두 갈래로 갈라지는 기동으로 흩어 놓았다. 연합군은 함대의 대부분을 잃었고, 섬의 요새도 곧 함락되었다. 제르바 해전은 프레베자에 이어 지중해에서 오스만의 우위를 굳힌 두 번째 큰 해전 승리로 여겨진다.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["카즈빈에서의 바예지드 왕자 처형", "a759de14"], "d": ["이란에 망명한 바예지드 왕자는 긴 협상 끝에 샤 타흐마스프에 의해 오스만 사절단에 인도되었고, 네 아들과 함께 교살당했다. 인도의 대가로 사파비는 상당한 물질적 양보와 국경 보장을 얻었다. 이 처형으로 셀림 2세의 즉위를 가로막는 마지막 장애가 제거되었고, 아마시아 조약의 평화 질서는 유지되었다.", "cf625eb3"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["예멘 반란과 코자 시난 파샤의 예멘 원정", "c8218d8e"], "d": ["자이드파 이맘 알무타하르는 세금이 강제로 거두어진다는 이유로 봉기하여 예멘의 대부분에서 오스만의 통치를 몰아냈다. 이스탄불에서 파견된 코자 시난 파샤는 1568-1570년의 작전에서 긴 포위 끝에 카우카반을 점령함으로써 이 지역에 오스만의 지배를 다시 세웠다. 이 원정은 홍해의 남쪽 관문과 인도양 무역로의 통제를 지키는 데 사활적으로 중요했다.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["아체 술탄국과의 방위 동맹과 인도양 원조", "8e835f24"], "d": ["포르투갈의 공격에 맞서 카누니 술탄 쉴레이만에게 도움을 청하러 온 아체 사절들은, 술탄이 시게트바르에서 세상을 떠나자 셀림 2세에게 충성을 바쳤고, 그와 방위 협정이 체결되었다. 술탄은 알렉산드리아에서 대포, 소총, 탄약, 장인들을 보내도록 명령했고, 인도 해역으로 파견할 전함 17척이 준비되었다. 예멘 반란이 커지면서 함대의 출항은 막혔으나, 아체에 도착한 오스만 포수와 장인들은 그 지역에 지속적인 자취를 남겼다.", "65c41562"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["니코시아 정복", "413d866b"], "d": ["1570년 7월 25일에 시작되어 45일 동안 이어진 포위 끝에, 베네치아 통치하 키프로스의 수도 니코시아는 오스만군에 항복했다. 섬의 중심지가 함락되면서 베네치아의 저항은 파마구스타 요새로 좁혀졌다. 이 정복은 서방에 큰 반향을 일으켰고, 교황이 주도하는 신성 동맹 함대의 결성에 이르는 과정을 가속화했다.", "1ef832d4"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["레판토 해전 이후의 함대 재건", "db51fe44"], "d": ["레판토 패전 뒤 카푸단 파샤에 임명된 클르치 알리 파샤의 첫 과업은 큰 손실을 입은 함대를 재건하는 것이었다. 조선소들은 1571-1572년 겨울 내내 쉬지 않고 가동되었다. 1572년 6월, 약 250척의 갤리선과 300척의 의용 선장(레이스) 갤리선으로 이루어진 새 함대가 지중해로 나아갔다. 이 신속한 회복은 레판토가 오스만의 해군력을 영구히 꺾지 못했음을 보여 주었다.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["베네치아와의 이스탄불 조약 — 키프로스의 인정", "4d08ef50"], "d": ["신성 동맹이 해체되어 홀로 남은 베네치아는 오스만과 단독 강화를 맺고, 키프로스가 오스만의 것임을 공식적으로 인정하며 전쟁 배상금 지불을 받아들였다. 이 조약은 레판토의 승리가 기독교 세계에 아무런 정치적 이득도 가져다주지 못했음을 분명히 드러냈다. 이후 베네치아는 70년 동안 오스만과의 직접 전쟁을 피하게 된다.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["셀림 2세의 죽음", "c289f5ee"], "d": ["넘어진 뒤 약 두 달 동안 국정 회의(디반)에 나오지 못하던 셀림 2세가 세상을 떠났다. 그의 죽음은 장남 무라드가 마니사에서 이스탄불에 올 때까지 열이틀 동안 궁정에서 비밀에 부쳐졌다. 사망일에 대해서는 사료가 엇갈린다. 셀라니키는 12월 15일이라 하고, 게를라흐, 메흐메드 빈 메흐메드, 제나비는 12월 13일이라 한다.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["셀림 2세의 죽음 공표와 무라드 3세의 즉위", "84334d70"], "d": ["셀림 2세의 죽음과 마니사에서 불려 온 무라드 3세의 즉위가 1574년 12월 22일에 공식 발표되었다. 새 술탄은 21년 동안 왕위를 지키게 되며, 그의 치세는 동방에서의 긴 이란 전쟁, 서방에서의 '장기전' 전야, 그리고 국내에서의 악체 화폐 변조로 기억되게 된다. 1579년 소콜루 메흐메드 파샤가 죽을 때까지 국정에서는 옛 질서가 이어졌다.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["와디 알마하진(알카세르키비르) 전투 — 오스만의 지원을 받은 압드 알말리크가 포르투갈군을 섬멸", "21280dac"], "d": ["오스만의 지원으로 모로코 왕위에 오른 압드 알말리크는 와디 알마하진에서 포르투갈 국왕 세바스티앙의 대군을 섬멸했다. 전투에서 세 군주가 한꺼번에 죽었기 때문에 서방 사료에서는 '세 왕의 전투'라고 불린다. 포르투갈의 군사력은 무너졌고, 나라는 얼마 뒤 스페인의 손에 넘어갔다. 압드 알말리크도 전투에서 죽었으며, 뒤를 이은 동생 아흐마드 알만수르는 사절단을 보내 이스탄불에 승전을 알렸다. 두 국가의 관계는 조공이나 신종이 아니라 사절과 선물을 주고받는 수준에 머물렀고, 얼마 뒤 선물 문제로 긴장되었다.", "0ddf3962"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["비하치 정복", "651a7275"], "d": ["보스니아 베일레르베이 텔리 하산 파샤는 1591년 11월 비하치의 전초 요새인 리파치를 점령한 뒤, 1592년에 도시와 요새 자체도 장악했다. 열흘간의 포위 끝에 사령관 람베르크가 항복했다. 이 정복은 보스니아 국경을 우나강을 따라 앞으로 밀어냈고, 1년 뒤 텔리 하산 파샤가 쿨파 앞에서 전사하면서 터질 '장기전' 전야에 오스만이 거둔 마지막 큰 성과였다.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["오스만-오스트리아 '장기전'의 시작", "bd22c392"], "d": ["보스니아 베일레르베이 텔리 하산 파샤가 쿨파(시사크) 앞에서 패하여 전사하자 오스만 국가는 오스트리아에 선전포고했고, 13년 동안 이어질 '장기전'이 시작되었다. 화기를 갖춘 보병이 결정적 역할을 한 이 전쟁은 오스만의 군제에서 세크반과 총병의 고용을 가속화했고, 티마르를 보유한 시파히의 쇠퇴를 심화시켰다. 전쟁은 1606년 지트바토로크 조약으로 끝나게 된다.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["코자 시난 파샤의 오스트리아 원정 출정 — 장기전의 첫 원정", "d4a2f46d"], "d": ["보스니아 베일레르베이 하산 파샤가 시사크 앞에서 패하여 전사한 뒤, 대재상 코자 시난 파샤는 화려한 말과 약속으로 술탄에게 전쟁을 승낙하게 했고, 예니체리 1만 2천 명과 다른 부대를 이끌고 출정했다. 이로써 13년 동안 이어질 오스만-오스트리아 전쟁의 첫 원정이 시작되었다.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["야느크칼레(죄르) 정복", "14b75207"], "d": ["대재상 코자 시난 파샤는 한 달 넘는 포위 끝에 빈으로 가는 길의 관문으로 여겨지던 야느크칼레의 항복을 받았다. 요새의 함락은 유럽에 큰 공포를 불러일으켰고, 장기전에서 오스만이 거둔 가장 빛나는 성과였다. 그러나 요새는 4년밖에 유지할 수 없었다.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["무라드 3세의 죽음", "1b62e886"], "d": ["21년의 치세 끝에 무라드 3세는 왈라키아군이 브러일라를 불태우고 실리스트라까지 진출하던 시기에 세상을 떠났고, 아야 소피아의 묘역에 묻혔다. 마니사에서 불려 온 그의 아들 메흐메드 3세는 열흘 뒤 이스탄불에 도착하여 즉위했다(1595년 1월 27일).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["에스테르곰을 오스트리아에 빼앗김", "f420d333"], "d": ["카를 폰 만스펠트가 지휘한 포위에서 충분한 지원을 받지 못한 에스테르곰 수비대는 요새를 마티아스 대공에게 넘겼다. 52년에 걸친 오스만의 지배가 끝나면서 다뉴브 방어선의 방어 사슬이 끊겼고, 부다가 직접적인 위협에 놓였다. 요새는 10년 뒤인 1605년에야 되찾을 수 있었다.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["에게르 요새 정복", "3e511629"], "d": ["3주에 걸친 격전 끝에, 오스만이 이전에 도저히 점령하지 못했던 강력한 에게르 요새가 수비대의 항복으로 함락되었다. 술탄이 직접 참석한 이 정복은 에스테르곰 상실로 꺾인 사기를 어느 정도 회복시켰고, 에게르 주가 설치되었다. 2주 뒤 거둔 메죄케레스테시 승리와 함께, 1596년은 장기전에서 오스만에게 가장 성공적인 해가 되었다.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["야느크칼레(죄르)의 상실", "b4ccc679"], "d": ["팔피 미클로시와 아돌프 폰 슈바르첸베르크가 지휘하는 부대는 기습으로 요새의 성문을 폭파하고 야느크칼레를 되찾았다. 4년 전 코자 시난 파샤가 큰 노력을 들여 얻은 요새의 상실은 헝가리에서 오스만의 전방선을 무너뜨렸다. 같은 해 부다를 포위한 적군은 격퇴되었으나, 전쟁의 양상은 점차 소모전으로 바뀌어 갔다.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["카라야즈즈 압뒬할림의 봉기", "30493b0d"], "d": ["장기전에서 군대를 탈영한 세크반과 레벤드를 모은 카라야즈즈 압뒬할림은 중부 아나톨리아의 넓은 지역을 장악하고 우르파 요새를 점령했으며(1599년 11월), '할림 샤'라는 칭호로 스스로 군주임을 선포하고 자기 투그라(서명 문양)가 찍힌 칙령을 내려보냈다. 대규모 젤랄리 물결의 첫 지도자로 여겨지는 카라야즈즈는 1602년에 죽었고, 그의 운동은 동생 델리 하산이 이어 갔다. 이 봉기는 아나톨리아 농민들이 집단적으로 땅을 버린 '대도피' 시대의 시작이다.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["티랴키 하산 파샤의 카니제 방어", "d56a5e6a"], "d": ["1년 전에 정복된 카니제를 되찾으려는 페르디난트 대공과 그 동맹군은 두 달 넘게 요새를 포위했으나, 티랴키 하산 파샤는 9천 명의 병력으로 저항했다. 외부의 도움을 받지 못했음에도 그는 총공격을 격퇴했고, 출격 작전으로 적에게 큰 손실을 안겨 철수하게 만들었다. 이 방어전은 오스만 역사 서술에서 서사시처럼 칭송되었고, '카니제 포위전'은 그 자체로 하나의 문학 장르가 되었다.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["메흐메드 3세의 죽음과 아흐메드 1세의 즉위", "da735fde"], "d": ["12월 20일 메흐메드 3세가 죽자 열네 살의 아들 아흐메드 1세가 왕위에 올랐다. 어린 나이에, 지방 산자크에 부임한 적 없이 왕위에 오른 첫 번째 술탄이었다는 점은 왕자를 지방에서 양육하던 관행이 사실상 끝났음을 보여 준다. 아흐메드 1세의 치세에는 형제 살해가 폐기되고 '에크베리예트'(왕족 남성 중 최연장자가 왕위를 잇는 원칙)로 이행하게 된다.", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["에스테르곰의 탈환", "7330f273"], "d": ["대재상 랄라 메흐메드 파샤는 10년 전에 잃은 에스테르곰을 포위하여 다시 오스만의 통치에 편입했다. 같은 원정에서 페스트와 바츠도 되찾아, 오스만은 헝가리의 전선을 정비했다. 이 성공 덕분에 이듬해 지트바토로크에서는 비교적 유리한 입장으로 협상 테이블에 앉을 수 있었으며, 에스테르곰은 1683년까지 오스만의 수중에 남게 된다.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["오루치 평원 승리와 잔볼라드 반란의 진압", "30f93532"], "d": ["알레포에 독립 베이국을 세우고 토스카나와의 동맹을 모색한 잔볼라드오을루 알리 파샤는 대재상 쿠유주 무라드 파샤에게 오루치 평원에서 큰 패배를 당했다. 시리아에서 중앙 권위가 다시 세워지면서 젤랄리 물결의 가장 위험한 갈래가 꺾였다. 쿠유주 무라드 파샤의 2년에 걸친 무자비한 숙청은 일시적이나마 아나톨리아의 치안을 확보했다.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["알라차이으르 승리와 칼렌데르오을루 반란의 진압", "55db0485"], "d": ["마니사와 부르사 일대에서 공납을 갈취하던 젤랄리 지도자 칼렌데르오을루는 쿠유주 무라드 파샤에게 알라차이으르에서 패하여 이란으로 달아나야 했다. 이 승리로 아나톨리아의 대규모 젤랄리 군대 가운데 마지막 것이 해산되었다. 처형한 반란자들을 파 놓은 우물에 채워 넣었다고 전해지는 쿠유주 무라드 파샤의 가혹한 숙청은 단기적으로 질서를 확보했으나, 아나톨리아의 인구와 생산의 손실은 메우지 못했다.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["네덜란드에 첫 아흐드나메 부여", "5d9d117e"], "d": ["네덜란드 연합 공화국의 사절 코르넬리스 하가는 아흐메드 1세로부터 프랑스와 영국에 주어진 것과 같은 범위의 아흐드나메(특혜 문서)를 얻는 데 성공했다. 이로써 네덜란드는 이스탄불에 대사관을 두고, 오스만의 항구에 영사관을 열며, 자국 깃발을 달고 교역할 권리를 얻었다. 이 아흐드나메는 지중해 무역에서 베네치아를 대신한 북방 해양 세력의 오스만 시장 진출을 상징한다.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["아흐메드 1세의 죽음과 무스타파 1세의 즉위 — 에크베리예트 관행", "9901c09e"], "d": ["51일간의 위장병 끝에 스물여덟 살의 아흐메드 1세가 세상을 떠나고, 그의 아들이 아닌 동생 무스타파 1세가 왕위에 올랐다. 이로써 아버지에게서 아들로 이어지는 계승 방식이 폐기되고, 왕조 남성 중 최연장자가 즉위하는 '에크베리예트' 제도로 사실상 이행했다. 96일간 이어진 이 첫 번째 치세는 왕자들이 '카페스'(새장, 궁중 유폐 거처)에서 자라는 시대의 시작이기도 했다.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["무스타파 1세의 폐위와 청년 오스만(오스만 2세)의 즉위", "e0f552f2"], "d": ["정신 상태가 온전하지 않다는 이유로 무스타파 1세는 96일 만에 폐위되었고, 아흐메드 1세의 열네 살 아들 오스만 2세가 술탄이 되었다. 하산베이자데에 근거한 전언에 따르면 이 폐위 결정에는 크즐라르 아아(흑인 환관장) 무스타파 아아가 영향을 끼쳤다. 청년 오스만은 예니체리 군단을 폐지하고 새 군대를 만들려는 구상으로 오스만 개혁 논쟁의 첫 번째 급진적 인물로 평가받는다. 이 구상은 4년 뒤 그의 목숨을 앗아 가게 된다.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["세라브 조약 — 이란과의 강화 갱신", "e778aca8"], "d": ["풀 이 시카스타 패전 뒤 이란과 맺은 세라브 조약은 1612년 나수흐 파샤 조약의 조건을 대체로 확인했으며, 사파비가 매년 보낼 비단의 양은 200짐에서 100짐으로 줄었다. 이로써 1603년부터 이어진 동방 전쟁의 두 번째 단계가 끝났다. 평화는 오래가지 못했고, 1623년 바그다드를 잃으면서 전쟁이 다시 타오르게 된다.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["호틴 원정과 호틴 조약", "bc4c823c"], "d": ["오스만 2세가 직접 지휘한 대군은 호드키에비치가 호틴 앞에 세운 요새화된 진영을 돌파하지 못했고, 여러 달에 걸친 공격에서 아무 성과도 얻지 못했다. 10월 9일에 체결된 조약으로 드니스테르강이 국경으로 인정되었고, 폴란드인들은 카자크의 습격을 막겠다고 약속했다. 승리로 선전되었으나 성과를 내지 못한 이 원정은 젊은 술탄이 예니체리에 품은 불신과 군단을 숙청하려는 의지를 굳혔다.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["무스타파 1세의 두 번째 폐위와 무라드 4세의 즉위", "1b3a9e74"], "d": ["오스만 2세가 살해된 뒤 두 번째로 왕위에 오른 무스타파 1세는 1년 3개월 만에 다시 폐위되었고, 열한 살의 무라드 4세가 술탄으로 선포되었다. 처음 9년 동안 국가는 사실상 그의 어머니 쾨셈 술탄과 궁정 중신들이 다스렸다. 무라드 4세는 1632년부터 직접 국정을 장악하여 강압적인 중앙 집권의 시대를 열게 된다.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["바그다드를 사파비에게 빼앗김", "db81be0c"], "d": ["바그다드에서 반란을 일으킨 베키르 수바시가 사파비와 벌인 협상의 결과, 내성을 지키던 그의 아들 데르비시 메흐메드는 도시를 샤 압바스의 군대에 넘겼다. 칼리파위 유산의 상징 도시 가운데 하나와 이라크의 대부분을 잃은 것은 이스탄불에 큰 분노를 일으켰다. 바그다드를 되찾는 것은 15년 동안 오스만 동방 정책의 유일한 목표가 된다.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["에르주룸을 거점으로 한 아바자 메흐메드 파샤 반란의 진압", "e6da2729"], "d": ["오스만 2세 살해에 대한 복수를 내세워 예니체리에 맞서 봉기한 에르주룸 베일레르베이 아바자 메흐메드 파샤는 여러 해 동안 동부 아나톨리아를 장악하고 중앙에 저항했다. 그는 대재상 휘스레브 파샤의 에르주룸 포위로 항복할 수밖에 없었고, 사면을 받아 보스니아에 임명되었다. 반란의 종결은 무라드 4세가 이란 원정에 나설 수 있는 전제 조건이었다.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["최초의 셰이휠이슬람 처형: 아히자데 휘세인 에펜디", "a60a58c5"], "d": ["셰이휠이슬람 아히자데 휘세인 에펜디는 군사 소요에서 중재를 하고 술탄에게 재판 절차에 관한 서면 경고를 보냈다는 이유로 뷔위크체크메제 부근에서 처형되었다. 오스만 최초로 처형된 셰이휠이슬람이라는 점에서, 울레마 계층(일미예)에게 가장 무거운 형벌은 유배라는 뿌리 깊은 전통이 깨졌다. 이 사건은 무라드 4세의 강경해진 권위와 국가-울레마 간 균형의 붕괴를 상징하는 것으로 여겨진다.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["무라드 4세의 예레반(레반) 정복", "b65a9b73"], "d": ["1635년 3월 28일 이스탄불을 출발한 무라드 4세는 7월 28-29일에 예레반을 포위하여 8월 8일 요새의 항복을 받았다. 이어 비워진 타브리즈에 들어가 도시를 파괴하게 했다. 술탄은 승리를 기념하여 토프카프 궁전에 레반 정자(쾨슈크)를 지었다. 이 원정은 30년 만에 처음으로 술탄이 직접 군대를 지휘한 대규모 동방 작전이었다.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["예레반을 사파비에게 빼앗김", "fbb8dd25"], "d": ["오스만군이 철수한 뒤 샤 사피의 군대는 예레반을 포위하여 8개월 만에 되찾았다. 요새를 그렇게 빨리 잃은 것은 캅카스에서의 지속적인 지배가 병참상 얼마나 어려운지를 보여 주었다. 예레반은 1639년 카스르 이 시린 조약에서도 이란에 남게 되며, 오스만은 아제르바이잔에 대한 주장을 포기하게 된다.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["바그다드 재정복", "4d2f27f3"], "d": ["1638년 5월 8일 이스탄불을 떠난 무라드 4세는 40일간의 격렬한 포위 끝에 15년 동안 사파비의 수중에 있던 바그다드를 되찾았다. 이 포위에서 베지르 타이야르 메흐메드 파샤가 전사했다. 도시의 정복으로 이라크에서 오스만의 통치가 다시 세워졌고, 술탄은 '바그다드의 정복자'라는 칭호를 얻었다. 이 정복은 이듬해 카스르 이 시린 조약으로 영구화되어 오늘날 튀르키예-이란 국경의 토대를 놓았다.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["무라드 4세의 죽음과 술탄 이브라힘의 즉위", "e2ca1ca0"], "d": ["스물일곱 살(히즈라력으로는 스물여덟 살)에 죽은 무라드 4세의 뒤를 이어, 왕조의 유일하게 살아남은 남성이던 동생 이브라힘이 왕위에 올랐다. 여러 해를 카페스에서 살았던 새 술탄의 치세에는 궁정의 지출과 궁정 내 권력 다툼이 국가 질서를 흔들었다. 8년 뒤 그가 폐위되고 살해되면서 오스만 역사에서 두 번째 술탄 살해가 벌어지게 된다.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["아조프 요새를 카자크로부터 탈환", "e5fcf160"], "d": ["1637년 돈 카자크가 점령한 아조프 요새는 술탄자데 메흐메드 파샤와 크림 칸 메흐메드 기라이 4세의 합동 작전 앞에서 비워졌으며, 카자크는 요새에 불을 지르고 물러났다. 흑해의 북쪽 관문을 되찾으면서, 카자크의 습격이 이스탄불의 보스포루스 해협까지 미치던 위험한 시기가 끝났다. 이 요새는 1696년에는 러시아의 차르 표트르 1세에게 빼앗기게 된다.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["크레타 원정의 시작과 하니아 정복", "a1b0c77f"], "d": ["몰타 해적이 오스만의 순례선을 공격하고 크레타로 피신한 것을 구실로 베네치아에 선전포고했고, 유수프 파샤가 지휘하는 함대가 섬에 병력을 상륙시켰다. 54일의 포위 끝에 하니아 요새가 점령되어 크레타에 오스만의 첫 번째 지속적인 거점이 세워졌다. 이로써 오스만 역사상 가장 긴 전쟁이 시작되었고, 섬은 24년 뒤인 1669년에야 완전히 정복할 수 있었다.", "2809708a"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["클리스를 베네치아에 빼앗김", "5473c22c"], "d": ["크레타(칸디아) 전쟁의 달마티아 전선에서 베네치아 사령관 레오나르도 포스콜로의 반격은 1537년부터 산자크의 중심지였던 클리스에도 미쳤고, 요새는 베네치아에 넘어갔다. 오스만이 전력을 크레타에 집중한 탓에 달마티아 국경에서의 이 상실은 되찾을 수 없었다. 클리스는 다시는 오스만의 통치로 돌아오지 않았고, 산자크의 중심지는 리브노로 옮겨졌다.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["칸디아 포위의 시작", "13016b10"], "d": ["하니아와 레팀노를 점령한 뒤 오스만군은 섬에 남은 베네치아의 마지막 큰 거점인 칸디아를 포위했다. 21년 동안 이어지게 될 이 봉쇄는 세계 전쟁사에서 가장 긴 포위전 가운데 하나로 기록되었다. 포위 기간 내내 다르다넬스 해협을 봉쇄하려는 베네치아 함대의 시도는 전쟁을 에게해 한복판으로 옮겨 가게 된다.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["대(大)발리데 쾨셈 술탄의 피살", "9d763f79"], "d": ["약 예순두 살의 쾨셈 술탄은 메흐메드 4세의 어머니 투르한 술탄의 명령에 따라 움직인 바슬랄라 우준 쉴레이만 아아와 그 부하들에게 하렘의 한 방에서 발견되어 살해되었다. 세 술탄의 시대에 국가 정치를 좌우한 이 강력한 왕실 여성의 죽음은 '여인들의 술탄 시대'라 불리는 시기의 사실상의 종말로 여겨진다. 그 빈자리의 권위는 5년 뒤 쾨프륄뤼 메흐메드 파샤가 비상한 권한을 가진 대재상이 되는 길을 열었다.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["다르다넬스 패전과 보즈자아다·림노스의 상실", "e01a1f7e"], "d": ["베네치아 제독 모체니고가 1656년 6월 다르다넬스 해협 앞에서 거둔 대해전 승리는 오스만 함대를 거의 완전히 괴멸시켰다. 이어 보즈자아다, 림노스, 사모트라키가 점령되었다. 해협이 베네치아의 봉쇄에 놓이면서 이스탄불의 식량 가격이 폭등했고 수도가 공격당할 것이라는 공포가 퍼졌다. 이 참사는 1656년 9월 쾨프륄뤼 메흐메드 파샤가 조건부의 비상한 권한을 가진 대재상에 임명되는 직접적인 원인이 되었다.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["다르다넬스 승리와 보즈자아다의 탈환", "603da863"], "d": ["쾨프륄뤼 메흐메드 파샤가 동원한 함대는 1657년 7월 19일 해협 앞에서 베네치아 함대를 격파했다. 이어 쿠르드 파샤가 지휘하는 병력이 8월 25일 보즈자아다를 되찾았고, 8월 30일 베네치아인들은 섬에서 완전히 철수했다. 11월에는 림노스도 되찾아 다르다넬스 봉쇄가 풀리고 이스탄불의 보급로가 다시 열렸다. 쾨프륄뤼는 직접 섬에 건너가 방어 시설을 수리하게 했다. 이 성공은 쾨프륄뤼 시대의 첫 번째 큰 군사적 성과이다.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["야노바(이네우) 정복과 트란실바니아 원정", "d1089616"], "d": ["허가 없이 폴란드 원정에 나서 오스만의 보호 관계를 어긴 트란실바니아 공 라코치 죄르지 2세를 응징하기 위해 원정에 나선 쾨프륄뤼 메흐메드 파샤는 베오그라드를 거쳐 진군하여 전략 요새 야노바를 점령했다. 트란실바니아에는 새 공을 임명하여 봉신 관계를 강력히 상기시켰다. 이 원정은 중부 유럽에서 권위를 다시 세우려는 오스만의 시도의 첫 고리였다. 트란실바니아는 이미 오스만의 봉신 공국이었다. 야노바 점령은 외국으로부터의 정복이 아니라, 봉신 트란실바니아의 이 요새를 공국의 통치에서 떼어 내 오스만의 산자크에 직접 편입한 것이다. 공국의 나머지는 봉신 지위로 남았다.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["아바자 하산 파샤 반란의 진압", "4ba74321"], "d": ["쾨프륄뤼 메흐메드 파샤의 가혹한 숙청에 맞서 아나톨리아의 베일레르베이들과 세크반 아아들을 규합한 아바자 하산 파샤는 대재상의 파면을 요구하며 대규모 봉기를 일으켰다. 반란은 알레포에서 진압되고 주모자들은 제거되었다. 이는 지방 파샤들이 중앙에 맞선 마지막 집단 저항이었다. 이로써 쾨프륄뤼의 권위는 확고부동해졌고, 대재상직은 다시 국가의 실질적인 행정 중심의 지위로 올라섰다.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["바라드(오라데아) 정복", "0e6ad300"], "d": ["오스만에 전쟁을 선포한 트란실바니아 공 라코치 죄르지 2세에 맞선 원정의 일환으로 바라드 요새와 도시가 점령되었다. 트란실바니아의 핵심 요새 중 하나가 함락되면서 이 지역에 새 오스만 주(바라드 주)가 설치되었다. 이 정복은 합스부르크를 경계하게 만들었고, 3년 뒤 시작될 오스만-오스트리아 전쟁의 직접적인 원인 가운데 하나가 되었다. 같은 날짜에 편입된 다른 곳: 바라트. 여기에서도 영토는 외국으로부터 빼앗은 것이 아니었다. 트란실바니아는 이미 오스만의 봉신 공국이었고, 바라드를 주로 만든 것은 2년 전 야노바에서처럼 이 도시의 통치를 봉신 공국에서 거두어 술탄에게 직속시킨 것일 뿐이었다.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["장크트고트하르트 전투", "61ebc1f2"], "d": ["라브강을 건넌 오스만군은 몬테쿠콜리가 지휘하는 유럽 연합군에 저지당해 큰 손실을 입었다. 이 전투는 규율 잡힌 화기 보병의 소총 사격이 오스만 기병 돌격보다 우위에 있음을 처음으로 분명히 보여 주었다는 점에서 군사사의 전환점으로 여겨진다. 패배에도 불구하고 오스만은 9일 뒤 체결된 바슈바르 조약에서 유리한 조건을 얻어 내는 데 성공했다.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["바슈바르 조약", "089c978c"], "d": ["장크트고트하르트 패전에도 불구하고 체결된 이 조약은 우이바르와 바라드가 오스만에 남고, 트란실바니아는 오스만의 보호 아래 중립으로 두며, 오스트리아가 20만 쿠루시를 '선물'로 지불한다고 규정했다. 20년 기한의 이 강화는 전쟁에서 진 쪽이 협상 테이블에서 이긴 드문 사례 가운데 하나이다. 이 조약이 합스부르크 여론에 불러일으킨 불만은 중부 헝가리 운동을, 간접적으로는 1683년 빈 원정을 키우게 된다.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["알제에서 데이 통치의 시작", "e99faa51"], "d": ["알제의 오자크(군단)와 타이페 이 레이스(해적 선장 집단)는 마지막 아가를 폐위하고 하즈 메흐메드를 종신 데이로 선출했다. 이때부터 알제는 이스탄불이 임명한 베일레르베이가 아니라, 현지 오자크가 자기 구성원 중에서 선출한 데이가 다스렸다. 오스만과의 유대는 후트바에서 술탄의 이름을 부르는 것과 깃발 및 원정 참가 의무에 그쳤다. 이로써 알제는 주(에얄레트)에서 오자클르크로 바뀌었다. 튀니스는 1705년 후사인 왕조 아래에서, 트리폴리타니아는 1711년 카라만리 가문 아래에서 같은 변화를 겪었다.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["폴란드 원정의 시작 — 메흐메드 4세와 파즐 아흐메드 파샤가 군대를 이끌다", "75e15a39"], "d": ["오스만의 보호를 받게 된 우크라이나의 헤트만 페트로 도로셴코에 대한 폴란드의 공격이 계속되자, 이스탄불은 폴란드 국왕에게 공격을 중단하라고 요구했다. 긍정적인 답이 오지 않자 폴란드 원정이 결정되었다. 대재상 파즐 아흐메드 파샤는 술탄도 함께한 군대를 이끌고 1672년 6월 4일 폴란드를 향해 출발했다. 이 원정은 카메네츠(카마니체) 정복과 부차치 조약으로 마무리된다.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["카메네츠(카마니체) 정복과 포돌리아 주의 설치", "c3f4f6d0"], "d": ["9일간의 포위 끝에 폴란드 동부에서 가장 강력한 요새로 여겨지던 카메네츠가 함락되었다. 메흐메드 4세는 9월 2일 대성당을 개조한 모스크에서 첫 금요 예배를 드렸다. 이 요새를 중심으로 포돌리아 주가 설치되었고, 오스만의 깃발은 오늘날 우크라이나 땅에서 가장 북쪽까지 이르렀다. 카메네츠는 1699년 카를로비츠 조약까지 제국의 북서쪽 끝으로 남게 된다.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["카라 무스타파 파샤가 폴란드로부터 우만을 접수", "0d3543a0"], "d": ["폴란드에 맞서 파견된 카라 무스타파 파샤는 폴란드가 보유한 요새 가운데 우만의 항복을 받았고, 도시는 카를로비츠 조약 때까지 오스만의 통치 아래 남았다.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["치히린 요새 정복", "a17cedd0"], "d": ["전년도에 멜레크 이브라힘 파샤의 작전이 성과를 거두지 못한 뒤, 대재상 메르지폰의 카라 무스타파 파샤는 직접 지휘하여 견고한 치히린 요새를 포위하고(7월 19/21일) 8월 21일에 점령했다. 우크라이나의 카자크 헤트만국을 둘러싼 오스만-러시아 경쟁의 상징이던 이 요새의 함락은 러시아를 강화로 몰아넣었다. 이 성공은 카라 무스타파 파샤가 빈으로 향하게 만든 자신감의 원천 가운데 하나이기도 했다.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["바흐치사라이 조약 — 러시아와의 첫 공식 강화", "df82bc0b"], "d": ["치히린 원정 이후 크림 칸의 중재로 진행된 협상 끝에, 드니프로(외쥐)강을 국경으로 인정하고 오스만 국가와 러시아 사이에 20년 기한의 강화가 체결되었다. 이는 두 국가 간의 첫 번째 포괄적 조약이라는 점에서 오스만-러시아 관계의 출발 문서로 여겨진다. 이 강화 덕분에 동부 전선이 안정되어 군대를 중부 유럽으로 돌릴 수 있었다.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["퇴쾨이 임레에게 중부 헝가리 왕위 임명장(베라트) 수여", "3cd8d51d"], "d": ["합스부르크의 압박에 맞서 봉기한 개신교 헝가리 귀족 퇴쾨이 임레는 1682년 4월부터 '중부 헝가리의 선출된 왕'으로 간주되기 시작했고, 9월 16일 부다 베일레르베이 이브라힘 파샤가 그에게 군주의 표장을 수여했다. 이로써 오스만의 보호 아래 새로운 헝가리 봉신 국가가 세워졌다. 이 개입은 오스트리아와의 전쟁을 불가피하게 만들어, 이듬해 제2차 빈 포위로 이어지는 연쇄를 시작시켰다.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["아야마우라(레프카다)를 베네치아에 빼앗김", "e6905fee"], "d": ["신성 동맹에 가담한 베네치아의 함대는 도시를 포격한 뒤 이오니아해의 아야마우라(레프카다)섬을 점령했다. 같은 해 프레베자도 함락되면서 아드리아해 어귀에서 오스만의 통제는 무너졌다. 이 상실들은 모로시니가 3년 안에 모레아 전체를 장악하게 되는 작전의 첫걸음이었다.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["코론을 베네치아에 빼앗김", "2ed762bc"], "d": ["모로시니가 이끄는 베네치아군은 모레아반도 남서쪽 끝의 코론 요새를 점령했고, 도시는 이후 30년 동안 베네치아의 통치 아래 남게 된다. 코론의 함락은 모레아 정복을 겨냥한 베네치아 작전의 첫 번째 큰 성과였다. 이 요새는 1715년에야 실라흐다르 알리 파샤가 이끄는 오스만군이 되찾을 수 있었다.", "506cf83e"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["베네치아의 에우보이아(네그로폰테) 포위 격퇴", "aae7e6a0"], "d": ["모레아를 장악한 뒤 에게해로 향한 모로시니는 석 달이 넘는 포위전으로 에우보이아(네그로폰테)를 점령하려 했다. 그러나 1687-1688년 겨울에 강화된 방어 시설과 수비대의 저항 앞에서 큰 손실을 입고 철수해야 했다. 이 실패는 에게해에서 베네치아의 진출을 멈추게 했고 모로시니의 군사적 명성을 흔들었다. 에우보이아는 카를로비츠 조약에서도 오스만의 수중에 남게 된다.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["카니제 요새를 오스트리아에 빼앗김", "553b45f3"], "d": ["1690년 1월부터 6만 명의 합스부르크군에게 엄중히 봉쇄당한 카니제는 몇 달 동안 지원을 받지 못한 채 버티다가, 마지막 수비대장 무스타파 파샤가 서명한 항복 협정으로 넘어갔다. 이로써 티랴키 하산 파샤의 영웅적인 방어로 기억되는 이 요새에서 90년에 걸친 오스만의 지배가 끝났다. 카니제의 상실은 서부 헝가리에서 오스만의 마지막 큰 거점이 무너진 것이었다.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["아흐메드 2세의 즉위", "52947b14"], "d": ["쉴레이만 2세가 죽자 마흔아홉 살의 동생 아흐메드 2세가 에디르네에서 왕위에 올랐다. 그의 치세는 신성 동맹 전쟁의 가장 힘든 시기와 겹쳤다. 즉위 두 달 뒤 슬란카멘에서 대재상 파즐 무스타파 파샤가 전사했다. 반면 그의 시대에 시행된 말리카네(종신 징세 청부) 제도는 오스만 재정의 장기적 구조를 바꾼 가장 중요한 조치 가운데 하나가 되었다.", "d3441b14"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["이스탄불 조약 — 아조프를 러시아에 할양", "79db4724"], "d": ["카를로비츠에서 러시아와는 2년의 휴전만 맺을 수 있었으며, 항구적인 강화는 1년 반에 걸친 힘겨운 협상 끝에 이스탄불에서 체결되었다. 오스만 국가는 1696년에 잃은 아조프 요새와 그 주변 영토를 공식적으로 러시아에 넘기고, 크림 칸이 모스크바에서 받던 연례 세금을 포기했다. 그 대가로 러시아는 이스탄불에 상주 대사를 둘 권리를 얻었다. 이로써 흑해 북안에서 러시아의 존재가 법적으로 인정되었다.", "a3a5a803"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["바그다드에서 콜레멘(맘루크) 통치의 시작", "abe52618"], "d": ["조지아 출신의 하산 파샤가 바그다드 총독에 임명되면서, 이라크에서는 중앙에서 임명한 총독 대신 자신의 노예 가운데서 길러 낸 지배 집단이 주도권을 쥐는 시대가 시작되었다. 1749년 쉴레이만 파샤가 총독이 되면서 이 체제는 확고히 자리 잡았고, 바브알리는 이제 원하는 사람이 아니라 영향력을 장악한 콜레멘 중 한 사람을 임명해야 했다. 이 반(半)자치 구조는 이란 국경을 방어하는 데에는 쓸모가 있었으나, 한 세기 반 동안 이라크에 대한 중앙 권력의 통제를 약화시켰다.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["튀니스에서 후사인 왕조의 수립", "cb1a98f9"], "d": ["알제의 군대가 튀니스를 침공하여 생긴 권력 공백 속에서, 튀르크계 시파히 아아 후사인 이븐 알리는 베이의 자리를 장악하고 오스만 술탄에 대한 충성을 밝힘으로써 정통성을 얻었다. 그가 세운 왕조는 1705-1735년과 1756-1957년에 튀니스를 다스렸으며, 오자크(군단)의 통치는 아버지에게서 아들로 이어지는 베이 체제로 대체되었다. 이로써 서방 오자크(가르프 오자클라르)에서 중앙에 속하면서도 사실상 자치적인 왕조 구조의 첫 사례가 탄생했다.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["스페인으로부터 오랑(바흐란)과 메르스엘케비르 탈환", "b67ce06a"], "d": ["알제 오자크의 베일레르베이 군대는 2세기 동안 스페인 수비대의 수중에 있던 오랑과 그 항구 메르스엘케비르를 긴 포위 끝에 점령했다. 이것은 서지중해에서 오스만의 보호를 받던 서방 오자크들이 스페인을 상대로 거둔 가장 큰 성공이었으며, 알제의 서쪽 측면을 확보했다. 도시는 1732년 다시 스페인에 점령되지만, 1792년에 확정적으로 되찾게 된다.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["프루트 조약 — 아조프와 타간로크의 회복", "bac5d2a1"], "d": ["프루트강 변에서 포위된 러시아군이 항복하면서 체결된 7개 조항의 조약은 아조프 요새를 그 토지 및 군수품과 함께 오스만에 반환한다고 규정했다. 타간로크, 카멘카, 예니칼레의 방어 시설은 허물어야 했고, 양측은 이 지역에 새 요새를 짓지 않기로 했다. 표트르 1세가 보로네시와 아조프에 16년 동안 구축한 함대와 기지 체계는 무너졌고, 러시아의 흑해 진출은 약 50년 늦어졌다.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["트리폴리타니아에서 카라만리 왕조의 수립", "e1105d4a"], "d": ["오자크 아아들의 다툼에 지친 트리폴리타니아에서 기병 장교 아흐메드 카라만리가 통치권을 장악하고, 이스탄불에서 받은 베일레르베이 임명장(베라트)으로 자신의 지위를 공식화했다. 아흐메드 파샤, 그의 아들 메흐메드 파샤, 손자 유수프 파샤를 거치며 1711-1835년에 이어지는 왕조가 생겨났고, 자체 함대를 만들고 유럽 국가들과 직접 조약을 체결하는 반(半)독립적 구조가 나타났다. 이 시대는 1835년 이 주가 중앙의 직할이 되면서야 끝난다.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["러시아와의 에디르네 조약", "14901a70"], "d": ["프루트에서 한 약속이 이행되지 않아 두 차례 더 선전포고가 이루어졌고, 마침내 러시아가 약속 사항을 받아들이면서 에디르네에서 항구적인 강화가 체결되었다. 조약은 프루트의 조건을 확인했다. 러시아는 폴란드의 일에 간섭하지 않고, 카자크 영토에서 철수하며, 스웨덴 국왕 '철두(鐵頭)' 칼 12세(데미르바시 샤를)의 귀국을 방해하지 않기로 했다. 이렇게 북부 전선이 닫힘으로써 오스만 국가는 모레아와 베네치아 전선으로 눈을 돌릴 수 있었다. 같은 날짜에 편입된 다른 곳: 호틴.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["베네치아에 대한 선전포고 — 모레아 원정의 준비", "d970b122"], "d": ["베네치아가 몬테네그로 반란자들을 지원하고, 오스만 상선을 압류하며, 카를로비츠에서 얻은 모레아를 무거운 세금으로 짓눌렀다는 것을 이유로 디반에서 전쟁이 결정되었다. 대재상 실라흐다르 다마드 알리 파샤가 준비한 원정은 이듬해 100일도 안 되어 모레아반도 전체를 되찾는 것으로 결실을 맺는다. 그러나 이 성공은 오스트리아를 움직이게 했고, 1716년 훨씬 더 힘겨운 전쟁의 문을 열게 된다.", "ef2edb5f"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["오스트리아와 베네치아의 동맹 — 1716-1718년 오스만-오스트리아 전쟁의 문", "99511ca2"], "d": ["오스만이 베네치아로부터 모레아를 되찾자, 오스트리아는 카를로비츠 조약이 위반되었다고 주장하며 베네치아와 동맹 조약을 체결했다. 오이겐 공은 대재상에게 보낸 서한에서 베네치아로부터 빼앗은 곳들을 반환하라고 요구했다. 다부트파샤 진영에서의 협의에서 대재상 알리 파샤의 압박으로 오스트리아에 선전포고가 이루어졌고, 이를 위해 셰이휠이슬람에게서 파트와를 받았다.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["대재상 알리 파샤의 오스트리아 원정 출정", "2fbdce42"], "d": ["오스트리아에 선전포고한 뒤, 총사령관(세르다르 이 에크렘) 알리 파샤는 10만 명이 넘는 군대를 이끌고 오스트리아 원정에 나섰고, 함대는 같은 해 여름 코르푸로 향했다. 군대는 베오그라드에서 페트로바라딘으로 진군하게 되며, 8월 초의 패전에서 대재상은 전사하게 된다.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["페트로바라딘(바라딘) 패전 — 다마드 알리 파샤의 전사", "265c1d81"], "d": ["베오그라드를 거쳐 다뉴브강을 건넌 오스만군은 페트로바라딘 앞에서 오이겐 공이 이끄는 오스트리아군과 맞섰다. 첫 공격에서 예니체리의 돌격이 적의 참호를 압박했으나, 기병 날개가 무너지면서 대열은 흩어졌다. 대재상 실라흐다르 다마드 알리 파샤는 이마에 총탄을 맞고 전사했으며, 진영과 포병 장비는 통째로 적의 손에 넘어갔다. 오스만 연대기가 '바라딘의 해'라고 부르는 이 패전은 테메슈바르, 그리고 이듬해 베오그라드의 상실로 이어지는 연쇄의 첫 고리였다.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["코르푸 포위의 실패", "b2aa7011"], "d": ["모레아의 세라스케르 카라 무스타파 파샤는 육지에서, 카푸단 파샤(해군 총사령관) 자늠 호자 메흐메드 파샤는 함대로 바다에서 코르푸를 압박했다. 이 섬은 아드리아해에서 베네치아의 핵심 거점이었다. 그러나 요새의 매우 강력한 방어 시설, 베네치아 함대가 데려온 증원군, 다뉴브 전선에서 전해진 패전 소식 때문에 포위는 해제되었다. 코르푸를 점령하지 못한 것은 모레아 재정복으로 고조된 분위기를 식혔고, 전쟁의 무게중심을 헝가리로 옮겨 놓았다.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["테메슈바르(티미쇼아라)를 오스트리아에 상실", "27fe1365"], "d": ["페테르바라딘 패전 뒤 오이겐 공은 곧바로 테메슈바르로 진격했고, 요새는 40일이 넘는 포위 끝에 항복 협정을 맺고 넘겨졌다. 1552년 카누니 시대에 정복되어 164년 동안 베일레르베이령의 중심지로서 헝가리 방어의 동쪽 기둥으로 여겨지던 도시는 이렇게 상실되었다. 테메슈바르의 함락으로 바나트 지역 전체가 오스트리아에 넘어갔고, 오스만 국경은 도나우강 남쪽으로 밀려났다. 같은 날짜에 본 아틀라스에서 오스만에서 합스부르크로 넘어가는 다른 정착지는 차코바르, 파체트, 카란셰베시(카란세베슈)로, 테메슈바르 주의 이양과 함께한 것이다(TDV timisvar; 지점 단위의 날짜는 사료에 없음, 상위 중심지 연쇄, 명시된 근사치).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["하람(예니 팔란카) 요새를 오스트리아에 인도 — 바나트의 도나우강변 상실", "38ee4c6d"], "d": ["테메슈바르 함락 뒤 바나트의 나머지를 점령하는 임무를 맡은 오스트리아 기병 장군 메르시는 11월 14일 도나우강변의 하람(예니 팔란카)으로 진격했다. 11월 16일 그가 요새에 도착하자 200명의 오스만 수비대는 백기를 올리고 자유 철수를 조건으로 항복했다. 이로써 1552년 이래 오스만의 수중에 있던 남부 바나트의 도나우 방어선도 오스트리아에 넘어갔다. 같은 날짜에 본 아틀라스에서 오스만에서 합스부르크로 넘어가는 다른 정착지는 베르셰츠로, 하람의 상위 중심지 연쇄를 따른다(Bánlaky 0019/1703; 명시된 근사치).", "5b54ecb0"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["동방 원정: 트빌리시 점령과 이란 전쟁의 시작", "78343dc2"], "d": ["사파비 국가가 아프간의 침입으로 무너지고 러시아가 카스피해 연안까지 남하하자, 오스만 국가는 그 공백이 전적으로 러시아의 세력권에 들어가지 않도록 동쪽으로 군대를 보냈다. 트빌리시를 점령하여 조지아를 오스만의 통치에 편입했고, 이어 간자, 예레반, 나흐치반 방향으로 진격을 계속했다. 튤립 시대의 평화로운 겉모습 뒤에서 수행된 이 원정은 13년 동안 이어지다가 결국 획득한 모든 땅을 돌려주는 것으로 끝나게 될 기나긴 동방 모험의 시작이었다.", "5c412d91"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["이스탄불 분할 협정(무카세멘나메) — 러시아와의 이란 분할", "fce8eec2"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["타브리즈 점령 — 아제르바이잔의 장악", "e502a4f7"], "d": ["1년 전의 시도가 실패한 뒤 다시 포위된 타브리즈는 거리마다 벌어진 격렬한 전투 끝에 오스만군에 항복했다. 타브리즈 주에 속한 마란드, 마라게, 소부크불라크(마하바드)도 오스만의 통치에 들어왔다. 같은 해 로리, 간자, 아르다빌, 호라마바드도 점령되어, 이스탄불 분할 협정에서 오스만의 몫으로 돌아간 지역들이 실제로 점령되었다. 동방에서 도달한 이 판도는 페르하드 파샤 조약 시대 이후 가장 앞선 국경이었으나, 이를 유지하는 일은 군대와 재정에 무거운 부담을 안겼다.", "e0953563"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["하마단 조약 — 서부 이란의 오스만 편입", "94a29dc3"], "d": ["아프간 통치자 아슈라프 샤와 체결한 조약으로 4년간 이어진 전쟁이 끝났고, 오스만 국가가 점령한 서부 이란의 영토가 법적으로 인정되었다. 아슈라프 샤는 그 대가로 오스만 술탄의 칼리프 지위를 인정하고, 이란에서 술탄의 이름으로 후트바를 낭독하게 하겠다고 약속했다. 이 외교적 승리는 오래가지 못했다. 나디르 샤가 1730년에 시작한 반격이 몇 해 안에 조약의 성과를 모두 쓸어 버리게 된다.", "fd0174b9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["아흐메드 파샤 조약 — 서부 이란 대부분의 반환", "590d839f"], "d": ["나디르 샤가 말라예르에서 거둔 승리와 잇따른 이란의 공세에 직면하여, 바그다드 총독 아흐메드 파샤는 중앙 정부와 협의하지 않고 강화 문서에 서명했다. 조약에 따라 아라스강이 국경으로 정해졌고, 하마단, 케르만샤, 아르달란, 아르다빌, 타브리즈 같은 서부 이란의 도시들은 이란에 반환되었으며, 간자와 트빌리시는 오스만에 남았다. 이스탄불에서 반발을 산 이 문서는 나디르 샤도 불충분하다고 여겼고, 1732년이 채 가기도 전에 전쟁이 다시 불붙었다. 본 아틀라스는 호이의 연쇄를 따르는 코투르도 이 날짜에 오스만에서 사파비로 넘어간 것으로 본다(TDV hoy; 코투르에 해당하는 날짜는 사료에 없음 — 명시된 근사치).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["오랑(바흐란)을 다시 스페인에 상실", "20485027"], "d": ["스페인 국왕 펠리페 5세가 보낸 대규모 상륙 함대가 몬테마르 백작의 지휘 아래 오랑 앞에 나타나, 알제 오자크의 병력을 격파하고 도시를 탈환했다. 24년 전에 정복했던 이 항구는 다시 60년 동안 스페인 수비대의 수중에 남게 된다. 서지중해에서 서방 오자크들이 지닌 힘의 한계를 보여 준 이 상실은 1792년 오랑을 최종적으로 정복하고서야 만회할 수 있었다.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["훔바라 부대(박격포·폭탄병 부대)의 유럽식 개혁과 훔바라하네 설립", "d980cf2a"], "d": ["오스만에 출사한 프랑스 출신의 훔바라즈 아흐메드 파샤는 대재상 헤키모을루 알리 파샤의 후원을 받아 훔바라 부대를 봉급을 받는 유럽식 편제의 부대로 만들었다. 보스니아에서 모집한 병사 300명에게 산술과 기하학에 바탕을 둔 정규 교육을 실시했고, 조직·장비·퇴역에 관한 새 규정을 마련했으며, 당대의 기술로 박격포 100문과 폭탄 5만 발을 제작했다. 기하학을 가르친 훔바라하네는 오스만에서 근대 군사 공학 교육의 첫 맹아로 여겨진다.", "181b7161"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["이스탄불 조약 — 남캅카스를 이란에 양도", "8c205aab"], "d": ["4년간 이어진 제2차 이란 전쟁은 아르파차이 패전과 간자·트빌리시 상실 뒤에 체결된 조약으로 끝났다. 오스만 국가는 1723년 이래 점령한 남캅카스와 서부 이란의 모든 영토에서 철수했고, 국경은 1639년의 카스르에 시린 선으로 되돌아갔다. 13년에 걸친 동방 원정이 남긴 것은 무거운 재정 부담과 텅 빈 국고였다. 그 대신 동부 전선이 닫힌 것은 러시아와 새로 시작된 전쟁을 위해 매우 중대한 이득이었다.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["외지(오차키우) 요새가 러시아에 함락", "f93e61f3"], "d": ["뮌니히 원수가 지휘하는 러시아군은 드니프로강 하구의 외지 요새를 포위했다. 화약고가 폭발하면서 방어가 무너졌고, 요새는 막대한 인명 손실을 내며 함락되었다. 흑해 북서 해안의 자물쇠로 여겨지던 외지의 상실은 러시아에 크림으로 가는 길을 열어 주었고, 이스탄불에 큰 공황을 불러일으켰다. 이듬해 러시아는 전염병과 보급난 때문에 요새를 비우게 되며, 요새는 다시 오스만에 넘어간다.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["바냐루카 승리 — 보스니아를 구하다", "f603865a"], "d": ["오스트리아군이 보스니아에 들어와 바냐루카를 포위하자, 보스니아 총독 헤키모을루 알리 파샤는 현지 주민에게서 모은 병력을 이끌고 구원에 나서 수적으로 우세한 적에게 큰 패배를 안겼다. 이 승리는 오스트리아의 보스니아 점령 계획을 첫 수에서부터 무너뜨렸고, 주의 북부는 완전히 수복되었다. 바냐루카는 1683년 이후 오스트리아 앞에서 계속 후퇴하던 오스만군의 사기를 되살린 전환점 가운데 하나가 되었다.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["히사르즈크(그로츠카) 승리 — 베오그라드로 가는 길이 열리다", "2101cdff"], "d": ["베오그라드를 지키기 위해 진군하던 오스트리아군은 도나우강변의 좁은 골짜기에서 매복에 걸려, 온종일 이어진 전투에서 큰 손실을 입었다. 발리스 원수의 병력이 무질서하게 베오그라드로 퇴각하는 동안 오스만군은 요새 앞까지 육박하여 포위를 시작했다. 히사르즈크는 카를로비츠 이래 오스트리아를 상대로 거둔 가장 결정적인 야전 승리였으며, 베오그라드 탈환을 직접 가능하게 했다.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["니시 조약 — 러시아와의 강화, 아조프의 중립화와 크림의 습격 중지", "674f974e"], "d": ["오스트리아가 베오그라드에서 강화에 동의하자 홀로 남게 된 러시아는 프랑스 대사 빌뇌브의 중재로 전쟁을 끝낼 수밖에 없었다. 아조프 요새의 방어 시설을 허물고 그 지역을 두 나라 사이의 중립 지대로 선포했으며, 러시아는 흑해에 군함과 상선을 두지 않는다는 조건을 받아들였다. 이로써 바다로 진출하려는 러시아의 목표는 한 세대 더 미루어졌고, 오스만 국가는 18세기에 마지막으로 이득을 보고 협상 테이블에서 일어섰다.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["외지가 러시아 점령에서 돌아오다: 1739년 강화에 따라 요새를 허문 뒤 인도", "7ecc2bef"], "d": ["러시아는 1737년 7월 11일 외지를 점령했다. 1739년 러시아와 맺은 강화에 따라 요새의 방어 시설을 허문 뒤 다시 오스만에 인도했다. 오스만은 이아시 조약 이전인 1788년까지 외지를 보유했다.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["모술 방어전 — 나디르 샤의 격퇴", "c03ffbc1"], "d": ["키르쿠크와 아르빌을 점령하고 모술 앞에 이른 나디르 샤는 40일 동안 도시에 포격을 가하고 잇따라 총공격을 감행했다. 총독 후세인 파샤 알잘릴리가 도시 주민까지 무장시켜 벌인 방어전은 이란군이 큰 손실을 입고 포위를 풀 수밖에 없게 만들었다. 모술이 버텨 냄으로써 이라크 전체의 상실을 막았고, 도시에서 잘릴리 가문의 영향력은 한 세기 동안 공고해졌다.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["디리야 동맹 — 나지드에서 제1차 사우드 토후국의 수립", "188751bf"], "d": ["우야이나에서 추방된 학자 무함마드 이븐 압둘와하브를 디리야에서 보호하게 된 아미르 무함마드 이븐 사우드는, 그와 함께 정치 권력을 종교적 포교에 봉사하게 하는 동맹을 맺었다. 이 협약은 사우드 가문의 새로운 역사를 열었고, 흩어져 있던 나지드의 오아시스 토후국들을 하나의 운동 아래 결집시켰다. 반세기 안에 카르발라, 메카, 메디나까지 뻗게 될 이 세력은 오스만 국가가 히자즈에 대한 지배권을 지키지 않을 수 없게 만든다.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["케르덴 조약 — 오스만·이란 전쟁의 종결", "1d3a919e"], "d": ["4년간 이어진 마지막 전쟁 뒤에 체결된 조약으로 1639년의 카스르에 시린 국경이 그대로 갱신되었고, 양측 모두 영토상의 이득을 얻지 못했다. 자파리파를 다섯 번째 법학파로 인정해 달라는 나디르 샤의 끈질긴 요구는 받아들여지지 않았으나, 그 대신 이란인 순례자들이 자유롭게 성지 순례를 하고 서로 사절을 교환하기로 결정했다. 두 세기를 넘긴 오스만·이란 전쟁은 이렇게 사실상 막을 내렸으며, 이 국경은 오늘날까지 대체로 유지되고 있다.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["마흐무드 1세의 죽음과 오스만 3세의 즉위", "30203700"], "d": ["24년의 치세 동안 베오그라드 조약으로 잃었던 땅을 되찾고 훔바라 부대의 개혁을 후원한 마흐무드 1세는 금요 예배 행차에서 돌아오던 중 세상을 떠났다. 그 뒤를 이어 58세가 될 때까지 카페스(왕자 유폐처) 생활을 한 동생 오스만 3세가 즉위했다. 짧고 불안한 치세가 시작되었고, 3년 동안 대재상을 여섯 번 갈아 치운 오스만 3세 시대에는 국정에 뚜렷한 침체가 이어졌다.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["오스만 3세의 죽음과 무스타파 3세의 즉위", "3ac10f85"], "d": ["3년의 치세 끝에 오스만 3세가 세상을 떠나자, 개혁 사상에 열려 있고 국정에 깊은 관심을 보이던 무스타파 3세가 즉위했다. 새 술탄은 대재상 코자 라그브 파샤의 경륜에 의지하여 재정을 바로잡고 군대를 쇄신하려 했으며, 드 토트 남작의 속사 포병대가 이 시기에 창설되었다. 그러나 1768년에 뛰어든 러시아 전쟁이 17년 치세의 모든 성과를 가려 버리게 된다.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["러시아에 대한 선전 포고 — 발타 사건과 1768~1774년 전쟁의 시작", "9c6aabe0"], "d": ["폴란드의 바르 연맹을 추격하던 러시아와 카자크 부대가 오스만 국경의 발타 마을을 습격해 불태우자, 디완(국무회의)은 전쟁을 결정했고 러시아 사절은 예디쿨레에 투옥되었다. 진지한 군사적 준비도 없이, 여섯 달 앞서 선포하고 뛰어든 이 전쟁은 처음부터 불리하게 흘러갔다. 6년 동안 이어질 이 싸움은 체슈메 기습, 카르탈 패전, 크림 점령을 거치며 오스만 역사에서 가장 뼈아픈 연패 가운데 하나가 된다.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["호틴 요새를 러시아에 상실", "66d43ea4"], "d": ["골리친 공이 지휘하는 러시아군의 두 차례 시도는 격퇴되었으나, 카메네츠와 호틴 사이에서 대재상이 패배하자 군대는 후퇴했고 수비대는 요새를 비웠다. 도나우강 북쪽에서 가장 강력한 오스만 요새가 저항 없이 넘어가면서 왈라키아와 몰다비아의 문이 러시아에 열렸다. 두 공국은 같은 해에 점령되었고, 호틴은 1774년 퀴취크 카이나르자 조약으로야 되찾을 수 있었다.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["카르탈(카훌) 평원의 패전", "6f408eaf"], "d": ["체슈메에서 함대가 불탄 지 3주 뒤, 도나우강 일대의 오스만 주력군은 카르탈 평원에서 수적으로는 훨씬 적지만 규율 잡힌 루먄체프 원수의 부대 앞에 와해되었다. 진영과 군수품, 수백 문의 대포가 적의 손에 넘어갔고, 도주하던 부대는 도나우강을 건너다 큰 손실을 입었다. 같은 여름에 함대와 지상군이 모두 궤멸하면서 킬리야, 아케르만, 이즈마일, 벤데르가 잇따라 함락되고 크림이 점령되기에 이르렀다.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["러시아의 크림반도 점령", "217837b0"], "d": ["1년 전 부자크를 장악한 러시아군은 돌고루코프 공의 지휘 아래 오르 카프(페레코프)를 돌파하여 크림반도 전체를 침공했다. 칸은 폐위되었고 친러파인 사히브 기라이가 그 자리에 앉혀져, 칸국을 오스만에서 떼어 내는 첫걸음이 내디뎌졌다. 3세기 동안 오스만의 북쪽 방패였던 크림의 상실은 1774년의 독립과 1783년의 직접 병합으로 이어지는 과정의 시작이었다.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["무스타파 3세의 죽음과 압뒬하미드 1세의 즉위", "42cba8e2"], "d": ["러시아 전쟁이 가장 위태롭던 때 세상을 떠난 무스타파 3세의 뒤를 이어, 43년을 궁정의 카페스(왕자 유폐처)에서 보낸 동생 압뒬하미드 1세가 49세의 나이로 즉위했다. 국가가 가장 어려운 시기 가운데 하나를 넘겨받은 새 술탄은 같은 해에 체결될 퀴취크 카이나르자 조약의 가혹한 조건과 맞서야 했다. 15년에 걸친 그의 치세는 크림의 상실과 새로운 러시아 전쟁으로 점철되었고, 1789년 외지 함락 소식을 읽다가 일으킨 뇌졸중으로 끝나게 된다.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["코즐루자 패전 — 퀴취크 카이나르자로 이어진 패배", "8e0542f9"], "d": ["슈멘 앞에 집결한 오스만군은 코즐루자에서 수보로프와 카멘스키의 연합 종대에 패했고, 군대의 대부분이 흩어졌다. 이 패전으로 발칸에서 저항할 병력은 남지 않게 되었으며, 러시아 선봉대가 슈멘을 포위하고 대재상의 사령부가 위협을 받았다. 한 달이 채 되기도 전에 퀴취크 카이나르자에서 협상에 나서 이례적으로 가혹한 조건을 받아들인 것은 이 패배의 직접적인 결과이다.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["부코비나(북부 몰다비아)를 오스트리아에 양도", "190f9caa"], "d": ["퀴취크 카이나르자가 초래한 약점을 이용하여, 오스트리아는 몰다비아와 트란실바니아를 잇는 부코비나 지역을 요구했고, 전쟁을 하지 않고 위협과 뇌물로 이 땅을 손에 넣었다. 호틴 남서쪽의 비옥하고 전략적인 이 지역을 잃으면서 몰다비아 공국은 사실상 둘로 갈라졌다. 총알 한 발 쏘지 않고 이루어진 이 양도는 오스만 국가가 이제 억지력을 잃었음을 가장 분명하게 보여 주는 징표 가운데 하나로 여겨졌다. 1775년 부코비나의 양도로 수체아바와 체르노비츠가 오스트리아에 넘어갔다(날짜 미확인).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["바스라가 이란에 점령되다", "0161e709"], "d": ["잔드 왕조의 통치자 카림 칸의 동생 사디크 칸은 1년에 걸친 포위 끝에 바스라를 점령했고, 오스만 국가는 바스라만에서 가장 중요한 항구를 잃었다. 이 점령은 인도 무역로와 대추야자·진주 수입, 이라크의 남부 방어를 직접 뒤흔들었다. 이 도시는 1779년 카림 칸의 죽음으로 이란에서 왕위 다툼이 벌어진 틈에야 되찾을 수 있었다.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["아이날르카바크 해석 협정(텐키흐나메) — 크림에 관한 잠정 타협", "9b3b0468"], "d": ["크림 칸국의 수장을 누구로 할 것인가를 두고 전쟁 직전까지 갔던 두 나라는 프랑스의 중재로 아이날르카바크 별궁에서 해석 문서에 서명했다. 러시아는 크림에서 군대를 철수하기로, 오스만 국가는 친러파 샤힌 기라이의 칸위를 인정하기로 합의했으며, 크림에 대한 술탄의 종교적 칼리프 권한이 확인되었다. 4년간 지속될 이 위태로운 균형은 1783년 러시아가 반도를 직접 병합하면서 완전히 무너지게 된다.", "8a428802"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["러시아에 대한 선전 포고 — 1787~1792년 오스만·러시아 전쟁의 시작", "3bfb870c"], "d": ["예카테리나 2세의 과시적인 크림 순행과 조지아에 대한 보호령 설정에 대해, 디완(국무회의)은 병합을 되돌릴 목적으로 전쟁을 결정했고 러시아 사절은 다시 예디쿨레에 갇혔다. 그러나 군대는 준비되어 있지 않았고 국고는 비어 있었으며 동맹국을 찾는 노력은 성과가 없었다. 5년간 이어질 이 전쟁은 외지의 학살을 동반한 함락, 이즈마일의 상실, 이아시 조약의 가혹한 조건으로 끝나게 된다.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["오스트리아의 참전 — 두 전선의 싸움", "ae912290"], "d": ["1781년 러시아와 맺은 비밀 동맹에 따라 오스트리아 황제 요제프 2세는 오스만 국가에 선전 포고를 하고 베오그라드와 보스니아 방면으로 움직였다. 오스만군은 갑자기 북쪽의 러시아와 서쪽의 오스트리아를 상대로 두 전선에서 동시에 싸워야 했다. 라자레타네, 메하디아, 셰베시에서 오스트리아군에게 거둔 승리에도 불구하고, 1789년 베오그라드를 잃으면서 서부 전선도 무너지게 된다.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["오스만·프로이센 동맹", "03b88e51"], "d": ["즉위하자마자 유럽에서 동맹국을 찾던 셀림 3세는 프로이센과 상호 원조를 규정한 동맹 조약을 체결했다. 프로이센은 러시아와 오스트리아에 선전 포고를 하기로, 오스만 국가는 크림을 되찾기 전에는 강화하지 않기로 약속했다. 이는 오스만 역사에서 유럽 국가와 체결한 최초의 진정한 상호 동맹 문서였으며, '이교도와는 동맹하지 않는다'는 고전적 관념이 버려졌음을 보여 주었다. 프로이센은 참전하지 않았지만, 오스트리아를 강화로 몰아붙임으로써 시스토바 조약의 길을 열었다.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["이즈마일 요새의 함락과 학살", "6a296b0c"], "d": ["도나우 삼각주에서 가장 강력한 요새로 여겨지던 이즈마일 요새는 수보로프 장군이 벌인 피비린내 나는 총공격으로 하루 만에 점령되었고, 수비대와 주민은 대부분 도륙당했다. 유럽에 큰 반향을 일으킨 이 학살은 오스만 여론에 깊은 충격을 주었고, 도나우 방어선의 중추를 부러뜨렸다. 요새는 1년 뒤 이아시 조약으로 되찾게 되지만, 그때는 이미 전쟁의 운명이 결정된 뒤였다.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["시스토바 조약 — 오스트리아 전선의 종결", "58741f1d"], "d": ["프로이센의 압력과 프랑스 혁명으로 오스트리아가 서쪽에 매이게 된 덕분에, 두 나라는 전쟁 전의 국경을 기준으로 강화에 이르렀다. 오스트리아는 베오그라드를 포함하여 점령한 모든 곳을 돌려주었고, 오스만 국가는 크로아티아 국경의 작은 조정만 받아들였다. 서부 전선이 이러한 조건으로 닫히면서 오스만 국가는 모든 힘을 러시아에 집중할 수 있었고, 이아시 조약에서의 손실도 제한되었다. 이 크로아티아 국경 조정으로 체틴(체틴그라드)과 드레지니크 그라드는 오스만에서 합스부르크로 넘어간다(TDV zistovi-antlasmasi; Korić 2016, n. 118, 제4조). 한편 오르소바(구 오르소바)는 반환되지 않은 유일한 곳이다(Bánlaky 0019/1796). 본 아틀라스는 법적 이양을 이 날짜로 기록한다(실제 점령은 1790년 4월 16일).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["이아시 조약 — 크림의 결정적 상실과 투를라(드네스트르) 국경", "a56fd194"], "d": ["5년 전쟁의 끝에 체결된 조약으로 투를라(드네스트르)강이 국경으로 정해졌다. 강의 좌안은 러시아에, 우안은 오스만에 남았고, 외지와 그 일대는 결정적으로 상실되었다. 오스만 국가는 크림을 되찾겠다는 희망을 완전히 버리고 1783년의 병합을 법적으로 인정했으며, 왈라키아와 몰다비아는 2년간의 세금 면제를 조건으로 반환되었다. 1,200만 쿠루시의 전쟁 배상금 의무까지 받아들임으로써 흑해 북쪽은 영구히 러시아에 넘겨졌다. 같은 날짜에 합류한 다른 곳: 이즈마일.", "277ee99d"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["파즈반도을루 오스만의 비딘 실질 지배", "0ce70361"], "d": ["니자므 제디드(신질서) 조치에 반발해 봉기한 파즈반도을루 오스만은 비딘 총독을 달아나게 하고 도시를 장악한 뒤, 도나우강을 따라 깊은 참호를 파서 요새화했다. 1797년 세력의 절정기에 그는 8만에 가까운 병력을 모아 니코폴리스, 시스토바, 루세, 소피아, 니시를 지배하에 두었으며, 자신을 반란자가 아니라 개혁가로 내세웠다. 바브알리(오스만 정부)가 1798~1799년에 몇 달에 걸쳐 벌인 포위는 성과가 없었고, 그는 1807년 죽을 때까지 북부 불가리아에서 반독립적으로 통치했다.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["제국 육군 공병학교(뮈헨디스하네이 베리이 휘마윤)의 개교", "e9a3a34b"], "d": ["니자므 제디드 군대에 포병·공병·측량(지도) 장교를 길러 내기 위해 하스쾨이에 육군 공병학교가 문을 열었다. 이는 1773년에 설립된 해군 공병학교에 대응하는 육군의 기관이었다. 교과에서는 대수학, 기하학, 역학, 축성술, 탄도학을 가르쳤고, 유럽 언어의 수학·포술 서적이 번역되었다. 튀르키예 근대 공학 교육의 뿌리로 여겨지는 이 학교는 오늘날 이스탄불 공과대학교의 시초로 인정된다.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["프랑스에 대한 선전 포고와 러시아·영국과의 동맹", "80e95bd7"], "d": ["나폴레옹의 이집트 점령에 대해 오스만 국가는 두 세기 반에 걸친 전통적인 프랑스와의 우호를 깨고 프랑스에 선전 포고를 했다. 같은 과정에서 역사상 처음으로 러시아와 동맹을 맺고 러시아 함대가 해협을 통과해 지중해로 나가는 것을 허용했으며, 이어 영국과도 동맹을 체결했다. 이 동맹 덕분에 이오니아 제도를 프랑스에게서 빼앗았으나, 해협을 외국 함대에 열어 준 일은 훗날 무거운 대가를 치르게 되는 선례가 되었다.", "7d8a9e45"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["아크레 방어전 — 나폴레옹의 격퇴", "56b5c45b"], "d": ["이집트에서 시리아로 진격한 나폴레옹은 아크레를 포위하고 두 달 동안 잇따라 공격을 가했다. 도시는 제자르 아흐메드 파샤가 영국 함대의 지원과 이스탄불에서 보낸 니자므 제디드 부대의 도움으로 지켜 냈다. 포위를 풀고 이집트로 철수할 수밖에 없었던 나폴레옹은 동방으로 뻗어 나가려는 꿈을 이 성벽 앞에 묻었다. 이 소식은 이스탄불에서 큰 기쁨으로 받아들여졌고, 새로 창설된 훈련 군대가 첫 중대한 시험을 통과한 증거로 여겨졌다.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["와하브파의 카르발라 습격", "522341ed"], "d": ["나지드에서 출발한 와하브파 병력은 카르발라에 들어가 도시를 약탈하고 이맘 후세인의 영묘를 파괴했으며 3,000명이 넘는 사람을 죽였다. 이라크에 있던 오스만의 쾰레멘(맘루크 출신) 총독들은 이 습격을 막지 못했고, 사건은 이란과 이스탄불 양쪽에서 큰 반발을 일으켰다. 이 공격은 사우드 운동이 더 이상 오아시스 토후국이 아니라 오스만의 성지를 위협하는 지역 세력으로 변모했음을 알리는 선언이었다.", "f571ab30"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["프랑스군의 이집트 철수", "00cfdc8c"], "d": ["오스만과 영국 군대가 육지와 바다에서 벌인 합동 작전의 결과, 먼저 카이로가, 이어 알렉산드리아가 인수되었고 프랑스군은 배에 실려 본국으로 보내졌다. 3년간의 점령이 끝나면서 이집트는 서류상으로는 오스만의 통치로 돌아갔으나, 쾰레멘 베이들과 알바니아 부대 사이의 패권 다툼이 나라를 혼란에 빠뜨렸다. 이 공백은 몇 해 안에 카발라 출신 메흐메드 알리가 부상하는 토대가 된다.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["파리 조약 — 프랑스와의 평화 회복", "1b76991f"], "d": ["이집트 철수 뒤 체결된 조약으로 오스만 국가와 프랑스 사이의 전쟁 상태가 공식적으로 끝나고 옛 카피툴라시옹(특혜 조약)이 갱신되었다. 프랑스 상선의 흑해 진입이 허용되었고, 그 대신 프랑스는 오스만의 영토 보전을 인정했다. 평화가 회복되면서 러시아와 영국 사이에 끼여 있던 셀림 3세의 대외 정책은 다시 운신의 여지를 얻었다.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["와하브파의 타이프 점령", "7b791359"], "d": ["사우드 이븐 압둘아지즈가 이끄는 와하브파 병력은 히자즈를 향한 첫 움직임으로 타이프를 포위하고 약탈했다. 이 도시는 성지로 들어가는 첫 관문으로서 함락되었다. 두 성지(하라마인)의 수호자라는 칭호를 지닌 오스만 술탄에게 이는 술탄 권위의 정당성을 직접 뒤흔드는 타격이었다. 두 달 반 뒤 같은 군대는 메카로 진격하게 된다.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["와하브파의 첫 메카 점령", "21157c05"], "d": ["타이프가 함락되고 두 달 반 뒤, 와하브파 병력은 메카에 들어가 영묘들을 허물고 자신들의 이해에 따른 질서를 세웠으며, 샤리프 갈리브는 제다로 물러날 수밖에 없었다. 순례길이 막힌 일은 이슬람 세계 전체에 반향을 일으켰고, 이스탄불은 이집트 총독 메흐메드 알리에게 군사 원조를 요청하지 않을 수 없었다. 이 첫 지배는 석 달밖에 지속되지 않는다.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["샤리프 갈리브의 메카 탈환", "83d08dff"], "d": ["제다로 물러나 있던 샤리프 갈리브는 모은 병력으로 메카를 포위했고, 25일간의 포위 끝에 와하브파에게서 도시를 되찾았다. 후트바는 다시 오스만의 이름으로 낭독되었다. 이 두 번째 지배도 오래가지 못해, 사우드 병력이 1806년에 도시를 다시 점령하게 된다.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["제1차 세르비아 봉기의 시작", "0f6e8767"], "d": ["베오그라드의 행정을 장악한 반란 예니체리 다히(우두머리)들이 세르비아 유력자들을 집단 학살하자, 카라조르제(카라 요르기)의 지도 아래 무장 저항이 시작되었다. 처음에는 술탄에게 충성을 지키며 다히들만을 상대로 벌였던 이 운동은 곧 자치와 독립을 요구하는 민족 봉기로 바뀌었다. 세르비아군은 1806년 베오그라드를 점령했으며, 이 봉기는 발칸의 민족주의 독립 운동에서 첫 번째 고리가 되었다.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["와하브파의 메디나 점령", "84e310d7"], "d": ["메카에 이어 메디나도 와하브파 병력의 손에 들어갔다. 라우다 무타하라(예언자 영묘)의 보물은 흩어졌고 도시의 돔 영묘들은 허물어졌다. 이로써 두 성지가 한꺼번에 오스만의 통제에서 벗어났고, 다마스쿠스와 이집트에서 오는 순례 대상은 여러 해 동안 길을 나서지 못했다. 메디나는 7년이 지난 1812년에야 메흐메드 알리 파샤의 아들 토순 파샤가 지휘하는 이집트군이 되찾을 수 있었다.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["러시아와의 전쟁 개시(1806~1812년 오스만·러시아 전쟁)와 해협 봉쇄", "ea170804"], "d": ["나폴레옹의 아우스터리츠 승리 뒤 프랑스에 가까워진 셀림 3세가 러시아의 압력에도 왈라키아와 몰다비아의 공(보이보드)들을 파면하자, 러시아군이 두 공국을 점령하여 전쟁이 시작되었다. 오스만 국가는 해협을 러시아 함대에 닫았고, 이에 영국도 러시아 편에 서서 이스탄불에 함대를 보냈다. 6년간 이어질 이 전쟁은 카바크츠 반란과 셀림 3세의 폐위와 뒤얽히며, 1812년 부쿠레슈티 조약에서 베사라비아를 잃는 것으로 끝나게 된다.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["영국 함대의 이스탄불 앞바다 진입(덕워스 작전)", "195bb58f"], "d": ["오스만 국가가 프랑스와의 관계를 끊도록 강요하려던 영국은 덕워스 제독이 지휘하는 함대를 다르다넬스 해협으로 통과시켜 이스탄불 앞에 정박시켰다. 프랑스 대사 세바스티아니의 지휘까지 더해져 이스탄불 주민이 총동원되었고, 해안 포대는 며칠 만에 보강되었다. 함대는 도시에 포격을 가하기도 전에 철수할 수밖에 없었으며, 돌아가는 길에 다르다넬스에서 큰 손실을 입었다. 수도가 처음으로 외국 함대의 위협을 이토록 가까이에서 받은 일은 해협 문제를 유럽 외교의 중심에 올려놓았다.", "bf71116c"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["칼레이 술타니예 조약 — 영국과의 강화와 해협 원칙", "fe282117"], "d": ["덕워스 작전이 실패한 뒤 영국과 체결한 조약으로 두 나라 사이의 전쟁이 끝났고, 영국 상인의 옛 특권이 회복되었다. 문서에 실린 이른바 '오랜 원칙' 조항은 평시에 어떠한 외국 군함도 해협을 통과할 수 없다는 것을 명문화했다. 이 원칙은 19세기 내내 해협 체제를 규정하게 되는 모든 국제적 합의의 법적 근거가 되었다.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["슬로보지아 패전 — 도나우 방면군의 포위", "54b60fd1"], "d": ["루세 앞에서 도나우강을 건넌 오스만군의 대부분은 쿠투조프가 강 건너편에서 펼친 포위 기동으로 슬로보지아에서 갇혀 굶주림에 내몰렸다. 수천 명의 병사가 항복할 수밖에 없었고, 대재상 휘하의 병력은 사실상 녹아 없어졌으며, 바브알리는 한 달 뒤 휴전을 요청해야 했다. 이 패배는 1812년 부쿠레슈티 조약에서 베사라비아를 내주는 데 동의한 직접적인 원인이다.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["베오그라드 탈환과 제1차 세르비아 봉기의 진압", "06f56f52"], "d": ["부쿠레슈티 조약으로 러시아의 지원을 잃은 세르비아 반란군은 보스니아와 루멜리아에서 온 병력의 합동 작전을 버텨 내지 못했다. 후르시드 아흐메드 파샤가 베오그라드에 입성했고, 9년간의 봉기는 완전히 진압되었다. 카라조르제는 오스트리아로 달아났고, 스메데레보 산자크는 다시 오스만의 직접 통치에 편입되었다. 그러나 가혹한 조치는 2년 뒤 밀로시 오브레노비치가 이끄는 두 번째이자 항구적인 봉기를 촉발하게 된다.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["제2차 세르비아 봉기와 밀로시 오브레노비치의 대공(바슈크네즈) 지위", "e6e82ad2"], "d": ["첫 번째 봉기가 진압된 뒤 시행된 가혹한 조치에 맞서 밀로시 오브레노비치의 지도 아래 새로운 봉기가 터졌고, 이번에 바브알리는 무력 대신 타협을 택했다. 체결된 협정으로 밀로시는 '바슈크네즈'(수석 크네즈) 칭호를 인정받았고, 세금 징수와 내정 운영의 권한은 세르비아 크네즈들에게 맡겨졌다. 이 실질적 자치의 첫 맹아는 1830년의 칙령과 1878년의 독립으로 이어지는 과정의 출발점이 되었다.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["왈라키아 봉기 — 입실란티스의 프루트강 도하와 블라디미레스쿠의 봉기", "67d46a98"], "d": ["러시아군 장군이던 알렉산드로스 입실란티스는 필리키 에테리아의 이름으로 프루트강을 건너 왈라키아와 몰다비아에서 그리스인의 전면 봉기를 일으키려 했고, 같은 무렵 투도르 블라디미레스쿠도 현지 농민을 동원했다. 두 운동은 합쳐지지 못했다. 블라디미레스쿠는 튀르크에 함께 맞서 싸우자는 입실란티스의 호소에 '나는 튀르크가 아니라 그리스인에 맞서 봉기했다'고 답했고, 얼마 지나지 않아 입실란티스의 부하들에게 살해되었다. 반란은 5월에 오스만군에 진압되었으나, 파나리오트 공(보이보드) 체제는 끝났고 반란의 불길은 모레아로 번졌다.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["리야드에서 제2차 사우드 국가의 수립", "34dad3bd"], "d": ["1818년 디리야가 함락되고 제1차 사우드 국가가 무너진 지 6년 뒤, 투르키 이븐 압둘라는 나지드에서 이집트 수비대를 몰아내고 리야드를 중심으로 새로운 사우드 토후국을 세웠다. 새 정권은 히자즈로 뻗어 나가는 것을 피하고 나지드에 머무는 쪽을 택했으며, 오스만·이집트 병력과의 직접 충돌을 멀리했다. 이 두 번째 국가는 세기말까지 존속하며 오늘날 사우디아라비아 건국으로 이어지는 사슬의 두 번째 고리가 된다. 같은 날짜에 상실한 다른 정착지: 디리야(나지드).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["아케르만 협정 — 세르비아와 두 공국에 대한 양보", "c75f15d0"], "d": ["예니체리 군단을 폐지한 직후 군대 없이 남게 된 오스만 국가는 러시아의 최후통첩 앞에서 가혹한 조건의 협정을 받아들일 수밖에 없었다. 세르비아에 약속한 자치가 확인되었고, 왈라키아와 몰다비아의 공들은 러시아의 승인 없이 파면할 수 없다는 점이 인정되었으며, 러시아 상선에는 해협에서의 완전한 자유가 부여되었다. 2년 뒤 바브알리가 그리스 문제를 이유로 협정을 인정하지 않겠다고 선언하자, 러시아는 이를 전쟁의 명분으로 삼게 된다.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["티마르 제도의 청산", "84d5d1d6"], "d": ["예니체리 군단 폐지 1년 뒤, 루멜리아와 아나톨리아의 53개 산자크에 있던 약 5,200명의 티마르 보유 시파히가 티마르 수입과 함께 아사키리 만수레 군의 기병으로 전환되었다. 이로써 오스만의 토지·조세·군대 질서를 4세기 동안 떠받쳐 온 티마르 체제가 사실상 끝났다. 비게 된 티마르는 국고로 넘어갔고, 중앙에서 봉급을 주는 군대와 현금 조세 제도로 이행하는 길이 열렸다.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["제국 의학교(트프하네이 아미레)의 설립 — 근대 의학 교육의 시작", "ac3e57c0"], "d": ["새로 창설된 아사키리 만수레 군에 의사와 외과의를 길러 내기 위해, 수석 어의(헤킴바시) 무스타파 베흐제트 에펜디의 제안으로 셰흐자데바시에 제국 의학교가 문을 열었다. 수업은 유럽의 교과 과정에 따라 편성되었고 처음에는 프랑스어로 가르쳤다. 몇 해 뒤 제국 외과학교(제라흐하네이 아미레)도 설립되어 두 기관이 합쳐졌다. 튀르키예 근대 의학 교육의 시초로 여겨지는 이 학교는 오늘날 이스탄불 의과대학의 기원으로 인정된다.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["1828~1829년 오스만·러시아 전쟁의 발발", "9dff4e05"], "d": ["나바리노에서 함대가 불타고 바브알리가 아케르만 협정을 인정하지 않겠다고 선언하자, 러시아는 두 전선에서 동시에 전쟁을 선포했다. 예니체리 군단은 막 폐지되었고 새 군대는 아직 창설 단계에 있었으므로 오스만의 방어는 처음부터 취약했다. 러시아군은 도나우강을 건너는 한편 동쪽에서는 카르스와 아할치헤를 점령했다. 1년 안에 에디르네까지 진격한 러시아군은 1829년 에디르네 조약의 가혹한 조건과 그리스의 독립을 강요하게 된다.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["아메리카 합중국과의 첫 조약", "d737516f"], "d": ["여러 해에 걸친 접촉 끝에 체결된 통상·항해 조약으로 미국은 오스만 영토에서 최혜국 지위와 해협의 상업 통항권을 얻었다. 별도의 비밀 조항은 오스만이 원할 때 미국 조선소에서 배를 건조하게 하고 완성된 배와 목재를 살 수 있도록 규정했다. 미국 상원은 조약은 비준했으나 이 비밀 조항은 18 대 27의 표결로 부결했다. 그래도 선박의 길은 막히지 않았다. 헨리 에크포드는 1831년에 가져온 배를 오스만에 팔았고, 아이날르카바크에서 일한 미국인 장인들은 함대에 새로운 형식의 배를 마련해 주었다. 이 조약은 오스만 국가가 유럽 밖의 나라와 맺은 최초의 포괄적 관계를 보여 주는 문서가 되었다.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["바그다드에서 쾰레멘(맘루크 출신) 통치의 종식", "7e1d38a3"], "d": ["중앙 집권 정책을 추진하던 마흐무드 2세는 요구한 돈을 보내지 않고 중앙에서 온 관리를 살해하게 한 바그다드 총독 다우드 파샤를 반란자로 선포했다. 알리 르자 파샤가 지휘하는 병력은 90일간의 포위 끝에 도시를 점령했고, 쾰레멘은 거의 전원이 숙청되었다. 이로써 1704년 이래 이어진 반독립적인 쾰레멘 통치가 끝났고, 이라크는 다시 중앙에 직접 편입되었다.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["마치카 병영에 육군사관학교(메크테비 하르비예) 설립", "bf31c7d9"], "d": ["아사키리 만수레이 무함마디예 군에 유럽식으로 교육받은 장교를 공급하기 위해 마치카 병영에 육군 사관 학교가 문을 열었다. 생도들은 수학, 지도 제작, 축성술, 외국어를 배웠고, 얼마 뒤에는 빈과 파리에 유학생을 보내 인력을 보강했다. 이 학교는 오스만군에서 사관학교 출신 장교의 전통, 나아가 19세기 말에 나타날 새로운 군인 지식인 세대가 태어난 곳이 되었다.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["트리폴리타니아의 중앙 직할화 — 카라만리 왕조의 종말", "faabcb96"], "d": ["카라만리 가문 내부의 왕위 다툼과, 1830년 프랑스의 알제 점령 이후 커진 유럽의 압력에 대응하여 바브알리는 트리폴리타니아에 직접 개입했다. 이스탄불에서 보낸 함대가 도시에 들어갔고, 마지막 카라만리 베이는 파면되어 이스탄불로 압송되었으며, 이 주는 중앙에서 임명한 총독에게 넘겨졌다. 124년의 왕조 시대가 끝나면서 북아프리카에서 오스만 국가가 직접 통치하는 마지막 영토가 공고해졌다.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["데프테르다르직의 폐지와 재무부(말리예 네자레티) 설립", "89f8125e"], "d": ["고전적 오스만 재정 질서의 우두머리인 데프테르다르(재무장관) 직이 폐지되고, 유럽식 부처인 재무부가 설립되어 흩어져 있던 국고들이 한 손에 모였다. 같은 해 바브알리의 다른 부서들도 네자레트(부)라는 이름으로 재편되어 근대적인 내각 구조로 이행했다. 이 조치는 1년 뒤 선포될 탄지마트 칙령의 행정적 기반을 마련한 가장 중요한 걸음 가운데 하나였다.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["영국의 아덴 정착", "ddbd556b"], "d": ["영국은 1802년 라헤지의 술탄 아흐메드 이븐 압둘카림과 맺은 통상·우호 협정을 근거로 아덴항에 군대를 상륙시키고 도시를 장악했다. 홍해 입구를 쥔 이 항구는 인도 항로의 석탄 보급 기지로서 영국 제국 전략의 요충이 되었다. 예멘에 대한 오스만 국가의 주장은 서류상으로는 계속되었으나, 남부 해안에 대한 실질적 지배는 이 이후 다시 돌아오지 않았다.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["티하마 해안으로의 복귀: 호데이다, 자비드, 모카 점령", "353982d2"], "d": ["1840년 이집트군의 철수로 주인 없이 남은 예멘 해안에, 메카 샤리프의 감독 아래 테브피크 파샤가 지휘하는 병력이 상륙하여 호데이다, 자비드, 모카 항구를 오스만의 통치에 편입했다. 사나까지 진격하려 했으나 주민의 저항 때문에 호데이다로 되돌아왔다. 이로써 고원 지대는 자이드파 이맘들에게 남았고, 오스만의 지배는 23년 동안 티하마 띠 지역에서만 이어졌다. 예멘 내륙은 1872년 아흐메드 무흐타르 파샤의 원정으로야 되찾게 된다.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["발타리만 협약: 왈라키아와 몰다비아에 대한 오스만·러시아 공동 보호", "d3bb22e9"], "d": ["1848년의 혁명이 왈라키아와 몰다비아로 번지자 오스만과 러시아의 병력이 두 공국을 함께 점령했었다. 발타리만에서 체결된 협약에 따라 공(보이보드)은 선거가 아니라 술탄이 7년 임기로 임명하며, 두 나라가 이 지역을 공동으로 감독하기로 결정되었다. 이 협정은 서류상 오스만의 주권을 유지하면서도 러시아에 실질적인 공동 권리를 인정했고, 도나우 공국들이 오스만에서 떨어져 나가는 것을 앞당겼다.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["헝가리 망명자 문제: 코슈트와 동료들의 오스만 망명", "1c7d7ef4"], "d": ["1848~1849년 헝가리 혁명이 러시아·오스트리아의 개입으로 진압되자, 러요시 코슈트와 수천 명의 헝가리인·폴란드인 난민이 오스만 영토로 피신했다. 오스트리아와 러시아는 난민의 인도를 강경하게 요구했으나, 바브알리는 영국과 프랑스의 지원을 받아 인도를 거부하고 이들을 퀴타히아에 정착시켰다. 코슈트의 일행은 그곳에 약 18개월 머물렀고, 수백 명의 난민이 이슬람으로 개종하여 오스만에 출사했다. 이 사건은 탄지마트 시대 오스만의 유럽 여론상의 위신을 높인 드문 외교적 승리 가운데 하나로 여겨졌다.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["엔쥐메니 다니시(학술원)의 설립: 이스탄불 최초의 오스만 아카데미", "6fda1365"], "d": ["공교육 최고 평의회의 결정으로 설립된 엔쥐메니 다니시는 튀르키예어 학술 서적과 교과서를 편찬하기 위해 조직한 최초의 오스만 학술원이다. 1851년 7월 18일 다륄마아리프 건물에서 의식을 치르고 문을 열었으며, 국내외 회원 가운데에는 아흐메드 제브데트 파샤도 있었다. 비록 단명했으나 제브데트 파샤의 『역사』와 『카바이디 오스마니예』(오스만어 문법) 같은 저작이 이 기관의 산물이었고, 튀르키예어가 학문의 언어가 되는 데 초석으로 여겨진다.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["올테니차 승리: 도나우 전선에서 오스만의 첫 성공", "a660ad2f"], "d": ["크림 전쟁의 개막 국면에서 총사령관(세르다르 에크렘) 외메르 뤼트피 파샤는 도나우강을 건너 올테니차에서 러시아군을 큰 손실을 입히며 격퇴했다. 이 승리는 전쟁 초두에 러시아의 진격을 저지함으로써, 오스만군이 탄지마트 이후의 훈련으로 얻은 힘을 유럽에 보여 주었다. 이 성공은 영국과 프랑스가 오스만 편에 서서 참전하기로 결정하는 것을 수월하게 한 심리적 기반을 마련했다.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["이스탄불에서 영국·프랑스와 맺은 동맹 조약", "04809278"], "d": ["크림 전쟁에서 러시아에 맞서 오스만 국가와 영국, 프랑스 사이에 체결된 동맹 조약은 세 나라가 합동 작전을 수행하며 동맹국이 전쟁이 끝나기 전에 단독 강화를 하지 않는다고 규정했다. 이로써 오스만 국가는 역사상 처음으로 유럽 강대국들과 대등한 당사자로서 군사 동맹에 들어갔다. 이 조약은 2년 뒤 파리에서 오스만이 유럽 국가 체제에 공식적으로 받아들여지는 법적 토대도 마련했다.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["이스탄불 시청(셰흐레마네티) 설립: 최초의 근대적 지방 자치 조직", "be4af27f"], "d": ["크림 전쟁 동안 이스탄불에 몰려든 연합군 병사와 늘어난 인구가 낳은 기반 시설 위기는 카디(재판관) 중심의 고전적 도시 행정의 한계를 드러냈다. 유럽의 선례를 따라 설립한 셰흐레마네티(시청)에 청소, 가격 통제(나르흐), 시장 감독, 건설 업무가 한 손에 모였고, 이듬해 베이올루·갈라타에 제6 시구(알튼즈 다이레이 벨레디예)가 시범 구역으로 조직되었다. 이 조치는 오스만 근대 지방 행정의 시작으로 인정된다.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["파리 조약: 크림 전쟁의 종결과 오스만의 유럽 국가 체제 편입", "4aee0e2a"], "d": ["크림 전쟁을 끝낸 파리 조약으로 오스만 국가는 유럽 국제법의 대등한 구성원으로 선언되었고, 영토 보전은 강대국의 공동 보장 아래 놓였다. 흑해는 중립화되었고, 러시아가 퀴취크 카이나르자 이래 내세우던 정교회 신민 보호권 주장은 무효가 되었으며, 베사라비아 남부(킬리야, 카훌, 이즈마일, 볼흐라드 군)는 몰다비아에 넘겨졌다. 그러나 이 조약은 개혁 칙령(이슬라하트 페르마느)을 국제적 약속으로 만듦으로써 내정 간섭의 문도 열어 놓았다.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["돌마바흐체 궁전의 개관: 통치 중심의 톱카프에서의 이전", "71ad26d0"], "d": ["압뒬메지드가 1842년 발리안 가문에 의뢰한 궁전이 14년의 공사 끝에 문을 열었고, 국가의 통치 중심은 4세기의 역사를 지닌 톱카프에서 보스포루스 해안으로 옮겨졌다. 유럽풍 양식, 크리스털 계단, 무아예데 홀(의전 연회장)을 갖춘 이 궁전은 탄지마트의 서구화 주장을 돌로 표현한 것이 되었다. 한편 그 막대한 비용은 오스만 재정이 외채의 악순환에 빠져든 시기에 가장 많이 비판받은 항목 가운데 하나가 되었다.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["쿠자 아래에서 왈라키아와 몰다비아의 통합: 루마니아의 탄생", "baef4da5"], "d": ["파리 조약 이후 치러진 선거에서 두 공국은 모두 알렉산드루 이오안 쿠자 대령을 공(보이보드)으로 선출하여 사실상의 통합을 이루었다. 바브알리와 오스트리아가 반대했으나, 프랑스가 지지한 기정사실은 받아들일 수밖에 없었다. 서류상으로는 오스만에 예속된 이 연합은 1862년에 루마니아라는 이름을 쓰게 되고, 1877년에는 일방적으로 독립을 선언한다. 이는 도나우강 일대에서 오스만 지배가 해체되는 과정의 전환점이다.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["쿨렐리 사건: 이스탄불에서 압뒬메지드에 대한 최초의 쿠데타 시도", "e3653b21"], "d": ["탄지마트 정책과 개혁 칙령이 비무슬림에게 부여한 평등에 반발한 군인과 민간인이 섞인 비밀 결사는, 술탄의 폐위를 계획하던 중 클르치 알리 파샤 모스크에서 모임을 갖다가 급습당했다. 피고들이 쿨렐리 병영에서 재판을 받았기 때문에 사건은 이 이름으로 불리게 되었고, 사형은 유배로 감형되었다. 이는 오스만 역사에서 이념적 동기로 결성된 조직이 시도한 최초의 궁정 쿠데타 시도로 인정된다.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["레바논산의 드루즈·마론파 내전과 다마스쿠스 사건", "5595fdd6"], "d": ["1860년 5월 시돈 근처에서 드루즈인 두 명이 살해되면서 터진 충돌은 산악 지대 사상 가장 피비린내 나는 드루즈·마론파 내전으로 번졌고, 7월에는 다마스쿠스로 옮겨붙어 수천 명의 기독교도가 목숨을 잃었다. 프랑스가 군대를 상륙시키자 바브알리는 푸아드 파샤를 비상 권한과 함께 이 지역에 파견했고, 강경한 진압 작전이 벌어졌다. 이 사건들은 유럽 개입의 구실이 되었으며, 레바논이 특별 지위를 얻은 직접적인 원인이 되었다.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["『테르쥐마느 아흐발』의 창간: 이스탄불 최초의 튀르키예어 민간 신문", "24792957"], "d": ["아가흐 에펜디가 발행하고 시나시가 편집을 맡은 『테르쥐마느 아흐발』은 국가의 지원 없이 발행된 최초의 튀르키예어 신문이다. 창간호의 서문은 백성이 자신의 일에 대해 말할 권리를 옹호했으며, 신문은 시나시의 『시인의 결혼』을 연재함으로써 근대 튀르키예 문학의 문도 열었다. 오스만에서 여론이라는 개념과 반정부 언론의 탄생은 이 날짜로 거슬러 올라간다.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["레바논산 조직 규정: 레바논의 특권 무타사리프령 지위", "bf375603"], "d": ["1860년의 학살 뒤 강대국의 압력으로 마련된 이 규정은 레바논산을 바브알리에 직속되고 종파 간 균형에 따라 구성된 행정 평의회가 다스리는 특권 무타사리프령으로 만들었다. 무타사리프는 오스만 신민인 가톨릭 기독교도여야 하고 그 임명은 강대국의 승인에 부쳐야 한다고 규정했으며, 초대 무타사리프는 다우드 파샤였다. 이 체제는 1915년까지 이어지며 근대 레바논 국가의 핵을 이루게 된다.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["압뒬메지드의 서거와 술탄 압뒬아지즈의 즉위", "27204d7c"], "d": ["22년의 치세 동안 탄지마트 칙령과 개혁 칙령에 서명한 압뒬메지드가 결핵으로 쓰러지자 동생 압뒬아지즈가 즉위했다. 새 술탄은 초기 몇 해 동안 절약 조치와 검소한 생활로 희망을 주었고, 해군을 세계의 손꼽히는 해군력 가운데 하나로 만들었다. 그러나 치세 말년에는 막대한 외채, 1875년의 파산, 발칸의 반란이 쌓여 1876년 폐위 운동의 토대를 마련하게 된다.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["통합 공국이 루마니아라는 이름을 채택", "d960e3fc"], "d": ["1859년 쿠자의 이중 선출로 사실상 통합된 왈라키아와 몰다비아는 1862년 의회와 정부를 부쿠레슈티의 한 지붕 아래로 모으고 공식적으로 루마니아라는 이름을 채택했다. 오스만 국가는 법적으로는 종주국의 지위와 연간 공납을 유지했으나, 공국에 대한 통제권은 사실상 잃었다. 도나우강 북쪽에서 4세기에 걸친 오스만 영향력의 종말은 이 날짜로 상징된다.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["수아킨, 마사와, 다흘라크의 이집트 편입", "a0924860"], "d": ["1846년 술탄 압뒬메지드가 수아킨과 함께 이집트 헤디브 메흐메드 알리 파샤에게 살야네(수입 할당)로 주었던 마사와는, 헤디브 이스마일 파샤 시대에 다흘라크, 수아킨과 함께 이집트 영토에 편입되어 카이마캄(군수)령의 지위로 조직되었다. 이로써 홍해의 아프리카 연안에 있는 이 세 항구는 법적으로는 오스만 영토로 남았으나, 행정적으로는 바브알리에서 직접 카이로로 넘어가, 이웃한 이집트·수단과 같은 속국 층에 들어갔다.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["크레타 반란의 시작(1866~1869)", "3679b861"], "d": ["그리스의 공공연한 지원으로 섬에서 터진 대규모 봉기는 크레타 그리스인의 에노시스(그리스와의 합병) 요구를 처음으로 국제 문제로 만들었다. 3년간 이어진 격렬한 산악전은 오스만군에 큰 손실을 안겼고 유럽 여론에 큰 반향을 일으켰다. 반란은 1868년 알리 파샤가 섬에 건너가 폭넓은 특권을 인정하는 조직 규정을 시행하고서야 겨우 가라앉았다.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["베오그라드와 세르비아 요새에서 마지막 오스만 수비대의 철수", "b34217db"], "d": ["강대국의 압력과 미하일로 공의 끈질긴 요구에 따라, 바브알리는 세르비아에 남아 있던 마지막 군사 거점을 비우는 데 동의했다. 1867년 4월 18일 베오그라드 요새의 오스만 군기가 내려졌고 열쇠는 공에게 넘겨졌다. 이로써 1521년 이래 이어진 오스만의 실질적인 군사 주둔이 끝났고, 세르비아의 독립으로 가는 길에서 마지막 큰 장애물이 사라졌다. 술탄의 종주권은 상징적인 깃발과 공납의 문제로만 축소되었다.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["이집트 총독에게 헤디브 칭호 수여", "09e10c12"], "d": ["카발라 왕조의 3대째인 이스마일 파샤의 집요한 로비와 이스탄불에 쏟아부은 돈의 결과, 이집트 총독에게 다른 총독들보다 우위에 있음을 강조하는 헤디브 칭호가 주어졌다. 같은 시기에 계승 방식도 아버지에서 아들로 넘어가도록 바뀌었으며, 이집트에는 외채 차입, 훈장 수여, 영사관 설치 같은 주권적 성격의 권한이 인정되었다. 이 조치들은 이집트의 오스만으로부터의 법적 이탈을 앞당긴 사슬의 첫 고리이다.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["크레타 조직 규정: 섬에 대한 폭넓은 행정 특권", "12052262"], "d": ["3년간의 반란을 끝내기 위해 대재상 알리 파샤가 직접 섬으로 건너갔고, 술탄의 재가를 받아 반포한 규정으로 크레타인에게는 혼합 행정 평의회, 지방 법원, 공무에서의 그리스어 사용, 세금 경감이 인정되었다. 이 조치는 섬에서 오스만의 지배를 30년 더 지탱했다. 그러나 기독교 주민에게 부여한 특권은 무슬림 크레타인의 입지를 약화시켰고 1896~1898년 위기의 씨앗을 뿌렸다.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["국가평의회(슈라이 데블레트)의 개원: 오스만 최고 행정 법원의 설립", "70b16497"], "d": ["1868년 3월 5일자 칙령에 따라 사법 최고 평의회가 둘로 나뉘어, 행정·입법 업무는 국가평의회에, 재판 업무는 최고 사법원(디바느 아흐캄 아들리예)에 맡겨졌다. 이 기관은 바브알리에서 의식을 치르고 문을 열었으며, 초대 의장에는 미드하트 파샤가 임명되었다. 법률안의 작성, 행정 분쟁의 해결, 관리에 대한 재판을 담당했다. 무슬림과 비무슬림이 섞인 구성원 구조를 지녀, 오스만에서 권력 분립 사상이 제도로 처음 적용된 것으로 여겨진다.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["수에즈 운하의 개통: 이집트를 거치는 인도 항로의 단축", "377ccd04"], "d": ["1859년에 시작된 공사는 10년이 걸렸고, 지중해와 홍해를 잇는 163km의 운하가 성대한 의식과 함께 개통되었다. 유럽과 인도를 잇는 길이 수천 마일 짧아지면서 이집트는 하루아침에 세계 무역의 요충이 되었다. 이 지정학적·전략적 가치는 운하 개통 13년 뒤 영국이 이집트를 점령하게 되는 가장 큰 원인이 되었고, 운하가 이집트에 지운 빚은 헤디브 정부를 파산으로 몰고 가게 된다.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["불가리아 총주교대리좌(엑사르흐청)의 설립: 불가리아 교회의 페네르로부터의 분리", "33a8272c"], "d": ["술탄의 칙령으로 그리스 총대주교청에서 분리된 독립 불가리아 교회(총주교대리좌)가 설립되었고, 어느 군이 여기에 속할지는 주민 투표에 맡겨졌다. 바브알리는 그리스의 영향력을 꺾으려고 이 조치를 취했으나 결과는 정반대였다. 이 교회는 불가리아 민족 정체성과 마케도니아에 대한 불가리아의 권리 주장을 조직하는 중심이 되었다. 이로써 발칸의 불가리아·그리스·세르비아 경쟁과 1876년 봉기의 제도적 토대가 놓였다.", "ce8f108b"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["미드하트 파샤의 나지드 원정: 알하사에서 오스만 지배의 재확립", "7db51461"], "d": ["바그다드 총독 미드하트 파샤는 사우드 가문 내부의 왕위 다툼을 이용하여 페르시아만 서안에 병력을 보내고, 알하사 지역을 나지드 산자크라는 이름으로 바스라 빌라예트에 편입했다. 압둘라 이븐 파이살을 무타사리프로 임명하여 서류상 오스만의 지배를 확립했다. 이 원정은 페르시아만에서 영국 세력의 확산을 저지하려는 것이었으며, 같은 해 카타르도 오스만의 통제에 들어오는 계기가 되었다.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["대재상 알리 파샤의 서거: 탄지마트 진용의 종말", "1cf0141c"], "d": ["1869년 푸아드 파샤가 죽은 뒤 탄지마트 정책을 홀로 떠받치던 알리 파샤가 세상을 떠남으로써, 30년 동안 국가의 대외 정책을 이끈 노련한 외교관 세대가 사라졌다. 그 뒤를 이은 마흐무드 네딤 파샤의 친러적이고 자의적인 통치는 압뒬아지즈의 개인 통치를 강화했다. 알리 파샤가 죽은 뒤 5년 안에 재정은 파산하고 발칸은 봉기했으며, 군주의 교체는 피할 수 없게 되었다.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["카타르에서 오스만 통제의 확립", "3b453165"], "d": ["영국의 압력을 받던 셰이크 카심 이븐 사니의 초청으로 오스만 병력이 카타르반도에 상륙했고, 1871년 가을 이 지역에 오스만의 통제가 확립되었다. 카타르는 나지드 산자크에 속한 카자(군)로 편성되었고 셰이크는 카이마캄(군수)에 임명되었다. 이 조치는 미드하트 파샤가 페르시아만에서 영국에 맞서 추진한 적극 정책의 가장 구체적인 성과였으며, 오스만 깃발은 1913년까지 반도에 휘날렸다.", "823711c3"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["사나 점령: 예멘에서 오스만 권위의 재확립", "978e20a0"], "d": ["수에즈 운하 개통으로 홍해의 전략적 가치가 커지자, 바브알리는 아흐메드 무흐타르 파샤의 지휘 아래 예비 사단 군대를 예멘에 보냈다. 사나를 점령함으로써 두 세기 동안 사실상 잃었던 예멘 내륙에 국가의 권위가 다시 세워졌고, 이 지역은 빌라예트(주)가 되었다. 그러나 자이드파 이맘과의 싸움은 끝내 그치지 않았고, 1891년, 1898년, 1904년의 반란은 오스만에 가장 비싸고 가장 오래 끈 국내 전선이 되었다. 같은 날짜에 합류한 다른 곳: 사나, 타이즈.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["헤르체고비나 봉기의 시작: 동방 문제의 재점화", "571b18ec"], "d": ["무거운 세금과 아얀(지방 유력자)의 압박 때문에 네베시네 일대에서 일어난 기독교 농민의 봉기는 곧 헤르체고비나 전역으로 번졌고, 세르비아와 몬테네그로에서 온 의용병으로 힘을 얻었다. 오스트리아와 러시아의 개혁 강요를 불러온 이 반란은 이듬해 불가리아 봉기와 세르비아·몬테네그로의 선전 포고를 촉발했다. 이로써 93년 전쟁(1877~78년 러시아·튀르크 전쟁)과 베를린 조약에 의한 발칸 상실로 이어지는 거대한 사슬의 첫 고리가 끊어졌다.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["오스만 재정의 파산: 외채 상환액의 절반 삭감", "2cac2fa5"], "d": ["1854년 이래 거듭 끌어 온 차관, 크림 전쟁 비용, 궁전 건축, 1873~74년의 아나톨리아 기근은 재정 적자를 500만 리라를 넘는 깊은 구렁으로 만들었다. 마흐무드 네딤 파샤 정부는 부채의 이자와 원금 상환을 5년 동안 절반으로 줄이겠다고 발표하여 사실상 모라토리엄을 선언했다. 유럽 증권 거래소에 큰 반발을 일으킨 이 결정은, 6년 뒤 무하렘 칙령과 오스만 공채 관리청(듀유느 우무미예)의 설립으로 귀결되는 과정의 시작이었다.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["무라드 5세의 폐위와 압뒬하미드 2세의 즉위", "cffb2271"], "d": ["압뒬아지즈가 폐위된 뒤 즉위한 무라드 5세는 숙부의 죽음과 체르케스 하산 사건으로 정신 건강이 크게 흔들려 직무를 수행할 수 없게 되었다. 93일의 재위 중 판단력이 온전했던 날은 7일뿐이었다. 그는 셰이휠이슬람의 파트와로 폐위되었고 동생 압뒬하미드 2세가 그 자리에 올랐다. 새 술탄은 미드하트 파샤에게 입헌제를 선포하겠다고 약속하고 즉위했다. 33년에 걸친 한 시대가 시작되고 있었다.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["테르사네(조선소) 회의: 강대국의 발칸 개혁 강요", "b5006a2c"], "d": ["발칸 위기를 해결하기 위해 강대국이 이스탄불에서 소집한 회의는 불가리아를 두 개의 자치 빌라예트로 나누고, 보스니아 헤르체고비나에 국제 감독 아래의 개혁을 시행할 것을 요구했다. 바브알리는 회의가 열린 날 대포를 쏘아 카눈 에사시(헌법)의 선포를 알림으로써, 강요에 헌정 개혁으로 맞서려 했다. 대표들은 이를 시간 끌기로 여기고 1877년 1월 20일 해산했으며, 넉 달 뒤 러시아가 선전 포고를 했다.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["돌마바흐체에서 제1차 하원(메즐리시 메부산)의 개원", "429bb279"], "d": ["카눈 에사시에 따라 선출된 115명의 의원은 1877년 3월 19일 돌마바흐체 궁전의 무아예데 홀에서 열린 의식과 함께 처음으로 모였다. 이로써 오스만 역사에 대의 의회 시대가 시작되었다. 무슬림과 비무슬림 의원들은 정부를 날카롭게 추궁했고, 전쟁의 지휘와 장관들의 책임을 토론했다. 이 대담한 반대는 의회의 수명을 단축시킨 가장 큰 원인이 되었다.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["플레브나 방어전의 시작: 가지 오스만 파샤의 저항", "0e04a878"], "d": ["93년 전쟁에서 도나우강을 건넌 러시아군의 이스탄불 진격로를 차단하기 위해 비딘에서 플레브나로 진군한 오스만 파샤는 읍을 보루와 참호로 요새화하고 다섯 달에 걸친 전설적인 방어전을 시작했다. 러시아·루마니아군의 세 차례 연속된 대공세는 큰 손실을 입고 격퇴되었으며, 차르 알렉산드르 2세가 직접 지휘하던 군대는 포위전으로 전환할 수밖에 없었다. 플레브나는 19세기 오스만군의 가장 빛나는 방어 성공으로 역사에 남았다.", "5a86466f"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["코린토스가 모레아 전제공국에 넘어가다", "392495eb"], "d": ["1358년부터 피렌체의 아차이우올리 가문이 아카이아 공국에 속한 봉토로 지니고 있던 코린토스는 1395년 비잔티움의 모레아 전제공 테오도로스의 손에 넘어갔다. 이후 도시는 오스만에 정복될 때까지 전제공국의 통치 아래 있었다.", "1803a03a"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["코린토스 정복", "87a2bc59"], "d": ["파티흐의 모레아 원정에서 아크로코린토스 요새는 석 달 동안 포위되었다가 결국 평화적으로 항복을 받아냈다. 이로써 모레아의 관문으로 여겨지던 코린토스 지협이 오스만에 넘어갔다.", "b2be3a05"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["코린토스의 베네치아 이양", "9a25b6b9"], "d": ["파트라스가 함락된 뒤 코린토스는 평화적으로 베네치아인들에게 넘겨졌고 무슬림 주민들은 도시를 떠났다. 1687년 8월 모로시니의 군대는 아테네 원정을 위해 코린토스에 집결하고 있었다.", "d92bcf7d"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["코린토스 수복", "26f53e3a"], "d": ["다마드 알리 파샤의 모레아 원정에서 첫 번째 주요 목표는 코린토스였다. 오스만군은 1715년 6월 베네치아인들로부터 도시를 되찾고, 여기서 반도의 나머지 지역으로 진격했다.", "82e2e719"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["쿠웨이트 사바 토후국의 오스만 보호령 편입", "3584dba0"], "d": ["TDV의 쿠웨이트 항목에 따르면, 이 항구는 나즈드에서 온 우투브 부족이 18세기 초에 세웠고, 사바 가문은 그 세기 말 무렵에 통치권을 넘겨받았다. 알아흐사가 사우드 가문의 손에 넘어가던 바로 그 시기에, 와하비의 압박 앞에서 바스라에 의지하는 것 외에 다른 길이 없었던 이 토후국은 오스만의 보호 아래 들어갔다. 이 관계는 1871년 미드하트 파샤의 바스라 개편으로 공식화되어 쿠웨이트는 바스라 산자크의 세 카자(군) 가운데 하나로 간주되게 된다. 훗날 이라크의 영유권 주장도 이 기록에 근거한다.", "c084f05f"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["두브로브니크 공화국의 종말 — 프랑스의 점령", "f8e27bf1"], "d": ["캄포포르미오 조약(1797)으로 달마티아 해안에 자리 잡은 프랑스군은 1806년 5월 27일 두브로브니크를 점령하여 이 작은 상인 공화국을 종식시켰다. 이로써 1458년부터 오스만에 공납을 바치며 자치와 통상 특권을 지켜 온 두브로브니크의 3세기 반에 걸친 속국 지위가 끝났다. 지도에서 도시와 공화국의 믈레트(Mljet) 섬은 프랑스의 직접 통치로 넘어간다.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["수후미의 러시아 상실 — 흑해 동부 해안의 개방", "adc96bd4"], "d": ["1806-1812년 오스만-러시아 전쟁에서 러시아 함대는 흑해 동부 해안으로 향하여, 압하지아에서 오스만 지배의 거점이던 수후미 요새(수후미칼레)를 점령했다. 이 요새는 캅카스 부족들과의 연결과 연안 교역의 중심지였다. 이를 잃으면서 러시아는 처음으로 흑해 동해안에 영구적으로 자리를 잡았고, 캅카스에서 오스만의 영향력은 아나파와 포티 주변으로 좁아졌다.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["파르가의 오스만 통치 이양", "66e0cc5d"], "d": ["파르가는 1401년부터 베네치아의 손에 있었고 오스만의 통치를 받은 적이 한 번도 없었으며, 베네치아가 멸망한 뒤에는 차례로 프랑스와 영국에 넘어갔다. TDV의 테펠레나의 알리 파샤 항목은 상황을 이렇게 요약한다. 도시는 영국에 항복했고, 1819년에야 알리 파샤의 통치에 넘겨졌다. 이 이양은 주민 대다수가 이오니아 제도로 이주하는 결과를 낳았다. 이로써 파사로비츠에서 베네치아에 남겨졌던 프레베자-파르가-보니차 삼각 거점 가운데 마지막 곳도 제국에 편입되었으며, 파르가는 94년 동안 오스만령으로 남게 된다.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["아르고스가 그리스 반란군의 손에 넘어가다", "be66a696"], "d": ["모레아 반란의 처음 몇 달 동안 아르고스와 그 일대는 오스만의 통치에서 벗어나 그리스 반란군의 손에 넘어갔다. 이 도시는 1821년 5월 오스만군의 반격 작전의 무대가 된다.", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["아흐메드 케흐야가 아르고스를 점령, 도시가 약탈되고 불타다", "d6d3ac7b"], "d": ["아흐메드 케흐야의 군대는 아르고스에서 그리스인들을 격파하고 도시를 약탈하고 불태웠으며, 도시는 잠시 오스만의 통제로 돌아갔다.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["아흐메드 케흐야가 아르고스에서 트리폴리차의 무슬림들과 합류해 트리폴리차로 진군하다", "9d679fd5"], "d": ["아흐메드 케흐야는 아르고스에서 트리폴리차의 무슬림들과 합류하여 트리폴리차를 향해 진군했으며, 아르고스는 다시 그리스 반란군의 통제 아래 들어갔다.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["코린토스가 그리스 반란군에게 넘어가다", "892dcdc6"], "d": ["그리스 독립 전쟁 중에 아크로코린토스는 반란군의 손에 넘어갔고, 요새 사령관 캬밀 베이는 포로가 되었다.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["드라말르 마흐무드 파샤가 아르고스에 본영을 설치하다", "c79abbfb"], "d": ["드라말르 마흐무드 파샤의 군대가 아르고스 평야에 진입했고, 파샤는 아르고스 읍에 본영을 설치했으며, 도시는 다시 오스만의 통제 아래 들어갔다.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["드라말르 마흐무드 파샤가 아르고스에서 철수하기 시작하다", "5e5afb74"], "d": ["아르고스를 점령한 지 2주도 되지 않아 철수할 수밖에 없게 된 드라말르 마흐무드 파샤는 휘하 군대의 첫 사단을 코린토스 방면으로 빼기 시작했으며, 아르고스는 다시 그리스 반란군의 손에 넘어갔다.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["아나볼루(나프플리오)의 반란군 상실", "1a67fa50"], "d": ["모레아에서 가장 견고한 요새를 갖춘 항구인 아나볼루는 1년이 넘는 봉쇄 끝에 굶주림으로 항복했다. 이 요새는 반란 초기부터 반도에 남아 있던 오스만 지배의 마지막 큰 거점이었으며, 이를 잃으면서 모레아 전역이 반란군의 손에 넘어갔다. 이 도시는 얼마 지나지 않아 새 그리스 국가의 첫 수도가 된다.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["레판토(이네바흐트)의 그리스 통치 이관", "c9d19d4b"], "d": ["그리스 반란 때까지 오스만의 수중에 남아 있던 코린토스만 북안의 레판토는 1829년 4월 상실되어 그리스의 통치 아래 들어갔으며, 읍의 이름은 고대의 이름인 나프팍토스로 바뀌었다. 도시의 무슬림과 유대인 주민은 완전히 사라졌고, 이곳은 작은 읍으로 변했다.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["프랑스의 알제 점령 — 300년 오자크의 종말", "0be8f568"], "d": ["채권 분쟁에서 비롯된 부채 사건을 구실로 프랑스는 알제 해안을 3년간 봉쇄한 뒤 시디 페루슈에 병력을 상륙시켰다. 3주간의 작전 끝에 후세인 데이가 항복했고, 1516년부터 이어진 오스만의 알제 오자크가 끝났다. 점령은 수도에 그치지 않았다. 내륙의 틀렘센, 셰르셸, 메데아도 같은 해 여름에 상실되었다. 해안 전체가 프랑스의 통제 아래 들어가기까지는 24년이 더 걸리게 된다.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["에우보이아의 그리스 할양 — 섬(카리스토스, 오레오이)과 함께", "7b524aa4"], "d": ["그리스 독립 전쟁 내내 격렬한 전투의 무대였으나 오스만의 수중에 남아 있던 에우보이아는 평화 조약이 발효된 뒤인 1831년 그리스에 넘겨졌다. 1470년 이래 중요한 해군 기지였던 이 도시의 무슬림 주민들은 모든 재산을 헐값에 팔고 집단으로 오스만 영토로 이주했다. 도시는 오랫동안 비어 있었으며, 독일 여행가 팔메라이어는 1842년 이곳을 유령 도시라고 묘사했다.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["프랑스의 오랑 점령", "a8415d66"], "d": ["스페인이 1792년 전쟁 없이 넘겨준 오랑은 알제 서부에서 가장 큰 항구였다. 수도가 함락된 지 6개월 뒤 프랑스군이 이 도시에 들어왔다. 여기서 시작된 서부 작전은 머지않아 15년 동안 이어질 아미르 압드 알카디르의 저항에 부딪히게 된다.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["안나바(본) 점령", "21f37fb1"], "d": ["알제리 동부의 튀니지 국경에 가까운 항구 안나바는 프랑스군에게 점령되어 콩스탕틴을 향한 진군의 기지가 되었다. 이 도시는 또한 사르데냐 섬 맞은편의 가장 가까운 아프리카 항구였다.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["아테네의 새 그리스 국가 이양 (바이에른 부대가 아크로폴리스를 인수한 날)", "deee4d37"], "d": ["1456년부터 오스만령이던 아테네는 그리스 독립 전쟁 동안 여러 차례 주인이 바뀌었고, 아크로폴리스의 수비대는 1827년에 다시 오스만의 통제 아래 들어갔다. 런던 의정서로 그어진 국경선 북쪽에 남게 되었기 때문에 도시는 새 왕국에 이양되었고 수비대는 아크로폴리스에서 철수했다. 지도의 날짜는 바이에른 부대가 아크로폴리스를 인수한 날이며, 오스만 수비대의 실제 철수는 며칠 뒤에 이루어졌다(St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, 13장; Finlay, Journals and Letters, 제1권, 67쪽). 이듬해 아테네는 아나볼루를 대신해 그리스의 수도로 선포되었다.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["베자이아(부지) 점령", "a8927e00"], "d": ["카빌리 산맥이 바다로 열리는 곳에 있는 베자이아 항구는 알제와 안나바 사이 해안선의 마지막 독립 고리였다. 함포 사격의 지원을 받아 점령되었으나, 그 뒤편의 산악 내륙은 30년이 더 지나도록 프랑스의 통제 아래 들어가지 않았다. 이러한 연안 점령들은 오스만령 알제리가 지도에서 해마다 녹아 없어지는 과정을 이룬다.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["세티프 점령", "2073731a"], "d": ["콩스탕틴이 1년 전에 함락된 뒤 프랑스군은 고원으로 올라가 옛 로마 도시 세티프를 점령하고 이곳에 상설 수비대를 두었다. 세티프는 해안과 사하라 사이의 대상로가 교차하는 지점이었으며, 이곳의 점령은 프랑스가 이제 항구뿐 아니라 내륙 교역망까지 장악하기 시작했음을 보여 주었다.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["비스크라 점령 — 사하라의 관문 상실", "d895cad0"], "d": ["비스크라는 아틀라스 산맥 남쪽 기슭에서 사하라로 열리는 관문이자 대추야자 오아시스의 중심지였다. 아미르 압드 알카디르의 저항이 꺾이기 시작하던 시기에 이곳이 점령되면서 프랑스의 통제는 처음으로 사막의 북쪽 가장자리에 닿았다. 이후의 작전은 이제 오아시스에서 오아시스로 나아가는 사막 원정이 되었다.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["투구르트 점령 — 알제리 전체의 상실", "33c056e2"], "d": ["사하라 북부의 오아시스 도시 투구르트가 점령되면서, 1830년에 시작된 점령은 오늘날 알제리의 북반부에서 완료되었다. 이 시기에 오스만 국가는 크림 전쟁에서 프랑스와 같은 편에서 싸우고 있었으며, 알제리에 대한 법적 권리를 공식적으로 포기한 적은 없었으나 실제로는 단 한 걸음도 내딛지 못했다. 북아프리카에 남은 유일한 영토는 트리폴리였다.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["엘오베이드 함락 — 코르도판이 마흐디군에게 넘어가다", "58299f62"], "d": ["스스로를 마흐디라 선언한 무함마드 아흐마드가 일으킨 운동은 수단에서 이집트의 통치에 맞서 빠르게 확산되었다. 코르도판의 중심지 엘오베이드는 4개월간의 포위 끝에 함락되어 반란의 수도가 되었으며, 도시의 국고와 무기고는 이 운동이 군대로 조직되는 것을 가능하게 했다. 수단은 법적으로 여전히 오스만에 속한 이집트 케디브국의 영토였으므로, 이 상실은 지도에서 제국의 본체로부터 빠진다.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["하르툼 함락 — 수단 전역의 상실", "d4b98464"], "d": ["10개월에 걸친 포위 끝에 마흐디군은 청나일과 백나일이 합류하는 지점의 하르툼에 진입했다. 도시의 총독 고든은 살해되었고, 구원을 위해 파견된 영국군 부대는 이틀 늦게 도착했다. 이날 이후 센나르, 동골라, 코르도판을 포함한 수단 전역은 14년 동안 마흐디국의 통치 아래 있었다. 이 지역은 1899년에야 오스만과의 연결이 완전히 끊긴 상태로 영국-이집트 공동 통치에 들어가게 된다.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["이탈리아의 마사와 점령 — 홍해 서해안의 상실", "c333b95b"], "d": ["하베시 주의 중심지였던 마사와 항구는 마흐디 반란이 수단을 뒤덮은 혼란을 틈탄 이탈리아에게 점령되었으며, 이것이 이탈리아령 에리트레아의 핵심이 되었다. 북쪽의 수아킨과 앞바다의 다흘락 제도도 같은 과정에서 상실되었다. 이로써 야부즈 술탄 셀림 시대부터 이어진 홍해 서해안의 오스만 지배는 끝났고, 홍해는 이제 양안이 모두 외국의 것인 바다가 되었다.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["이탈리아의 로도스 점령", "e08662c5"], "d": ["트리폴리 전쟁에서 오스만 국가를 협상 테이블에 앉히려 했던 이탈리아는 전쟁을 지중해로 확대하여 로도스에 병력을 상륙시켰다. 섬은 며칠 만에 항복했다. 1522년 카누니가 오랜 포위 끝에 점령해 390년 동안 지켜 온 로도스는 이로써 동지중해에서 제국의 가장 큰 섬 기지 지위를 잃었으며, 우시 조약에서는 임시 점령으로 간주되었으나 다시는 되찾지 못했다.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["이탈리아의 도데카네스 제도 점령", "200aacf2"], "d": ["로도스를 점령한 지 몇 주 만에 이탈리아 해군은 주변의 섬들도 점령했으며, 이 군도는 훗날 '도데카네스'라는 이름을 얻게 된다. 섬들 대부분은 아나톨리아 해안에서 몇 마일 떨어진 곳에 있었고 에게해 남동부의 통로를 장악하고 있었다. 이 점령은 우시 조약에서 트리폴리를 포기하는 대가로 임시적인 것으로 간주되었으나 이탈리아는 섬을 결코 비우지 않았으며, 섬들은 1947년에 그리스로 이양되게 된다.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["코스 점령", "ab246c62"], "d": ["도데카네스 작전의 마지막 고리인 코스는 보드룸 반도 바로 맞은편에 있는 비옥하고 인구가 많은 섬이었다. 이 섬이 점령됨으로써 에게해 남동쪽 모퉁이의 모든 섬이 이탈리아의 통제 아래 들어갔고, 아나톨리아 남서 해안 전체가 외국의 섬 사슬에 둘러싸이게 되었다.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["이카리아의 독립 선언", "c4452033"], "d": ["사모스와 키오스 사이의 작은 섬 이카리아에서는 이탈리아의 점령이 낳은 불확실한 상황 속에서 주민들이 봉기해 오스만 헌병을 섬에서 몰아내고, 자체 국기와 우표, 의회를 갖춘 '자유 국가'를 선포하여 다섯 달 동안 유지했다. 1912년 11월 섬은 그리스에 편입되었다. 작은 규모에도 불구하고 이 사건은 에게해에서 중앙 행정이 어떻게 해체되었는지를 분명히 보여 준다.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["사모스의 오스만 통치 이탈", "3a862f2b"], "d": ["사모스는 1832년부터 오스만에 세금을 바치고 이스탄불이 임명한 베이가 다스리던 자치 공국이었다. 트리폴리 전쟁이 만든 공백 속에서 섬의 통합파 운동이 통치권을 장악하면서 자치 공국 체제는 사실상 끝났고, 섬은 같은 해에 그리스에 편입한다고 선언했다. 아나톨리아 해안에서 2킬로미터 떨어진 이 섬은 에게해에서 가장 먼저 잃은 영토 가운데 하나가 되었다.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["이오안니나 함락 — 이피로스와 파르가의 상실", "d42fce18"], "d": ["발칸 전쟁에서 다섯 달 동안 포위된 이오안니나는 비자니 진지가 함락된 뒤 항복했으며, 도시와 함께 이피로스 전역이 그리스에 넘어갔다. 이오안니나 산자크에 속한 파르가도 이때 상실되어 94년간의 오스만 통치가 끝났다. 이오안니나의 상실은 제국이 아드리아해로 열어 둔 마지막 창이 닫히는 것을 뜻했다.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["에디르네가 불가리아에 함락되다", "459d2e56"], "d": ["다섯 달 반에 걸친 포위 끝에 탄약과 식량이 바닥난 에디르네는 항복했고, 쉬크뤼 파샤는 포로가 되었다. 1361년부터 오스만령이었고 92년 동안 수도였던 이 도시의 함락은 발칸 전쟁의 가장 큰 타격으로 여겨졌다. 에디르네는 넉 달 뒤 제2차 발칸 전쟁에서 불가리아가 다른 전선에서 무너진 틈을 타 되찾게 된다.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["얀부가 샤리프 후세인의 군대에 넘어가다", "e291c816"], "d": ["샤리프 후세인이 6월에 일으킨 봉기는 홍해 연안으로 확산되었으며, 메디나의 항구인 얀부는 영국 해군의 지원 아래 반란군의 손에 넘어갔다. 이 항구는 봉기에 외부에서 들어오는 무기와 자금의 주요 관문이 되었다. 이로써 메디나의 파흐레딘 파샤 휘하 병력은 바다와의 연결이 끊겼고, 도시는 헤자즈 철도의 끝에 홀로 남게 되었다.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["제3차 가자 전투 — 가자와 칸유니스의 상실", "c142a069"], "d": ["두 차례의 실패 끝에 앨런비는 세 번째 공세에서 베에르셰바를 우회해 전선을 돌파했고, 여섯 달 동안 지켜 온 가자 방어선은 무너졌다. 가자와 그 남쪽의 칸유니스는 같은 날 철수되었다. 이 돌파는 팔레스타인 전선 붕괴의 시작이었으며, 예루살렘은 5주 뒤 함락된다.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["코모티니 점령 — 서트라키아의 상실", "904d813c"], "d": ["무드로스 휴전 이후 먼저 연합국 부대의 통제를 받게 된 서트라키아는 산레모 회의의 결정으로 그리스에 넘겨졌고, 그리스군이 코모티니에 진입했다. 1913년 불가리아로부터 되찾았던 이 지역은 제국이 루멜리아에서 잃은 마지막 영토가 되었다. 이 지역 튀르크 주민의 지위는 3년 뒤 로잔에서 소수민족 제도로 규정되게 된다. 이 점령으로 서트라키아의 코모티니, 크산티, 알렉산드루폴리, 수플리 카자가 그리스에 넘어갔다.", "ef0aeba3"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["이스탄불의 흑사병 유행과 궁정의 에디르네 이전", "70c7a163"], "d": ["TDV 이슬람 백과사전의 이스탄불 항목에 따르면, 도시의 빠르고 조밀한 정착은 때때로 전염병이 확산되는 토대가 되었다. 1466년의 흑사병 유행 때에는 궁정과 국가 고위 관료들이 일시적으로 에디르네로 물러났다. 도시 인구는 이러한 전염병으로 심각한 손실을 입었다.", "7b20238c"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["사흔-으 세만 마드라사의 교육 개시", "021f2a83"], "d": ["TDV 이슬람 백과사전의 사흔-으 세만 항목에 따르면, 파티흐 복합 시설 안에 세워진 이 여덟 개의 마드라사는 당대 최고 수준의 교육 기관으로 설계되었으며 오스만 울라마 위계의 정점을 이루었다. 이곳의 교수직과 졸업은 이후 수 세기 동안 카디와 교수 경력에서 가장 명망 높은 단계로 여겨졌다.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["톱카프 궁전(사라이-으 제디드)의 완공", "d2db6323"], "d": ["TDV 이슬람 백과사전의 톱카프 궁전 항목에 따르면, 당대 사료들은 공사의 착공 시점과 완공 시점이 서로 다르다. 바브-으 휘마윤 비문의 883년(1478)이라는 연대에 따르면, 파티흐의 명으로 아마도 1465년에 착공된 공사는 이 해까지 대부분 완료되었고, 궁전은 옛 궁전에 있던 국가 중심의 자리를 대신했다. 이로써 파디샤는 3세기 동안 국가의 행정과 의례의 심장이 될 새 거처로 옮겨 갔다.", "5dfffded"]}
});
